INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u6-C1','math',3,1,'u6',2,'똑같이 나누기 — 전체를 나눈 조각의 모양과 크기가 모두 같아야 똑같이 나눈 것임을 알고(조각 수만으로는 아님), 겹쳐 보기·다시 모으기로 확인하기',ARRAY['4수01-10']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u6-C2','math',3,1,'u6',3,'분수 쓰고 읽기 — 전체를 똑같이 나눈 것 중의 몇을 분수로 나타내고, 아래 수 분모(똑같이 나눈 수)·위 수 분자(그중 몇)를 알아 「○분의 △」로 읽기',ARRAY['4수01-10']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u6-C3','math',3,1,'u6',3,'단위분수와 단위분수 몇 개 — 분자가 1인 분수가 단위분수임을 알고, 분수를 단위분수 몇 개로 보기(⟨3/4⟩은 ⟨1/4⟩이 3개)',ARRAY['4수01-10']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u6-C4','math',3,1,'u6',4,'전체와 부분 — 사용한(색칠한) 부분 + 남은 부분 = 전체를 분수로 나타내고, 단위분수가 분모만큼 모이면 전체가 됨을 이용해 부분을 보고 전체를 완성하기',ARRAY['4수01-10']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u6-C5','math',3,1,'u6',5,'분모가 같은 분수의 크기 비교 — 단위분수 개수로 견주어 분자가 클수록 큰 분수임을 알고, 크기가 같은 전체에서 비교하기',ARRAY['4수01-12']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u6-C6','math',3,1,'u6',6,'단위분수의 크기 비교 — 많이 나눌수록 한 칸이 작아져 단위분수는 분모가 클수록 작음을 띠로 확인하고 설명하기',ARRAY['4수01-12']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u6-C7','math',3,1,'u6',7,'분모가 10인 분수 — 전체를 똑같이 열로 나눈 한 칸이 ⟨1/10⟩이고, ⟨1/10⟩이 10개면 1이 되어 「10개 모이면 다음」 규칙이 1보다 작은 쪽으로 이어짐을 알기',ARRAY['4수01-13']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u6-C8','math',3,1,'u6',8,'소수 0.1 알기 — ⟨1/10⟩ = 0.1(영 점 일)이고 가운데 점이 소수점임을 알며, 분모가 10인 분수를 소수로 나타내고 0.몇을 0.1이 몇 개로 보기(3 mm = 0.3 cm)',ARRAY['4수01-13']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u6-C9','math',3,1,'u6',9,'소수의 크기 비교 — 0.1의 개수·띠·분수로 바꾸기 세 방법으로 소수의 크기를 견주고 설명하기',ARRAY['4수01-14']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u6-C10','math',3,1,'u6',10,'전체의 크기와 분수 — 같은 분수라도 전체의 크기가 다르면 부분의 크기가 다름을 알고, 부분을 보고 단위분수가 분모만큼 되도록 전체를 완성하기',ARRAY['4수01-10']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X01','math',3,'u6',ARRAY['M3-1-u6-C1']::text[],'조각 수만 맞으면 똑같이 나눈 것이라고 생각한다(크기가 다른 세 조각도 「똑같이 셋」)','조각의 크기가 모두 같은지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X02','math',3,'u6',ARRAY['M3-1-u6-C2','M3-1-u6-C3','M3-1-u6-C7','M3-1-u6-C8']::text[],'분모와 분자를 바꾸어 쓰거나 읽는다(4칸 중 3칸 → ⟨4/3⟩, 오분의 삼 → 삼분의 오)','아래 분모·위 분자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X03','math',3,'u6',ARRAY['M3-1-u6-C2','M3-1-u6-C4']::text[],'전체 칸 수 대신 남은(색칠 안 한) 칸 수를 분모로 쓴다(4칸 중 3칸 색칠 → ⟨3/1⟩·⟨1/3⟩)','분모는 전체 칸 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X04','math',3,'u6',ARRAY['M3-1-u6-C2','M3-1-u6-C4','M3-1-u6-C7','M3-1-u6-C8']::text[],'묻는 부분과 다른 부분을 센다(색칠 안 한 부분을 물었는데 색칠한 부분으로 답한다)','묻는 부분에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X05','math',3,'u6',ARRAY['M3-1-u6-C3','M3-1-u6-C7']::text[],'단위분수 개수를 분모로 센다(⟨5/8⟩은 ⟨1/8⟩이 8개)','분자만큼 모인 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X06','math',3,'u6',ARRAY['M3-1-u6-C2','M3-1-u6-C8']::text[],'분수나 소수를 다른 식처럼 읽는다(⟨3/5⟩ → 삼 점 오·오 더하기 삼, 0.6 → 육분의 일)','「○분의 △」·「영 점 △」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X07','math',3,'u6',ARRAY['M3-1-u6-C4','M3-1-u6-C7','M3-1-u6-C10']::text[],'「몇 개 더」를 물었는데 전체가 되는 개수(분모)를 그대로 답한다','전체 − 이미 있는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X08','math',3,'u6',ARRAY['M3-1-u6-C3']::text[],'분자가 1인 분수(단위분수) 대신 분모가 1이거나 분자가 큰 분수를 단위분수로 안다','분자가 1') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X09','math',3,'u6',ARRAY['M3-1-u6-C5']::text[],'분모가 같은 분수에서 분자가 작을수록 크다고 생각하거나 분모만 보고 같다고 한다','단위분수 개수가 많을수록 크다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X10','math',3,'u6',ARRAY['M3-1-u6-C6']::text[],'단위분수도 자연수처럼 분모가 클수록 크다고 생각한다(⟨1/3⟩ > ⟨1/2⟩)','많이 나눌수록 한 칸이 작다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X11','math',3,'u6',ARRAY['M3-1-u6-C5','M3-1-u6-C10']::text[],'전체의 크기가 달라도 같은 분수면 부분의 크기가 늘 같다고 생각한다','어떤 전체인지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X12','math',3,'u6',ARRAY['M3-1-u6-C7','M3-1-u6-C8']::text[],'⟨1/10⟩(0.1)이 10개 모인 것을 10이나 100으로 생각한다','⟨1/10⟩이 10개 = 1') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X13','math',3,'u6',ARRAY['M3-1-u6-C7','M3-1-u6-C8']::text[],'분모가 10인 분수를 소수로 쓸 때 자리를 잘못 쓴다(⟨7/10⟩ → 7.0·0.07·7, 0.1이 10개 → 0.10)','⟨△/10⟩ = 0.△') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X14','math',3,'u6',ARRAY['M3-1-u6-C8']::text[],'소수를 읽을 때 소수점 앞뒤를 바꾸어 읽는다(0.8 → 팔 점 영)','소수점 앞부터 「영 점 △」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X15','math',3,'u6',ARRAY['M3-1-u6-C9']::text[],'소수의 크기를 거꾸로 견준다(0.1의 개수가 적을수록 크다, 0.7 > 0.9)','0.1이 많을수록 크다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X16','math',3,'u6',ARRAY['M3-1-u6-C8','M3-1-u6-C9']::text[],'소수와 분수를 서로 다른 크기로 본다(0.5와 ⟨5/10⟩은 다른 수), 소수점이 있으면 늘 작다고 생각한다','0.5 = ⟨5/10⟩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X17','math',3,'u6',ARRAY['M3-1-u6-C8']::text[],'mm를 cm로 나타낼 때 단위만 바꾸거나 자리를 잘못 쓴다(3 mm → 3 cm·0.03 cm)','1 mm = 0.1 cm') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X18','math',3,'u6',ARRAY['M3-1-u6-C1','M3-1-u6-C2','M3-1-u6-C3','M3-1-u6-C4','M3-1-u6-C5','M3-1-u6-C6','M3-1-u6-C7','M3-1-u6-C8','M3-1-u6-C9','M3-1-u6-C10']::text[],'묻는 말을 거꾸로 읽는다 — 큰↔작은, 바른↔잘못, 색칠한↔색칠 안 한','물음의 핵심 말에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X19','math',3,'u6',ARRAY['M3-1-u6-C1','M3-1-u6-C4','M3-1-u6-C5','M3-1-u6-C7','M3-1-u6-C9','M3-1-u6-C10']::text[],'개수를 세거나 빼는 데서 실수해 하나 많거나 적게 답한다(나눈 선의 수를 조각 수로 세기 포함)','하나씩 짚어 다시 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u6-X20','math',3,'u6',ARRAY['M3-1-u6-C5','M3-1-u6-C6','M3-1-u6-C9']::text[],'크기를 비교할 수 있는데도 「알 수 없다」·「같다」고 한다','단위분수·0.1 개수로 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L02_basic#1','math',3,1,'u6','L02','g3_1_math_u6_L02_basic','lesson_basic','M3-1-u6-C1',1,'mc','auto','이 도형은 똑같이 몇으로 나누었나요?',ARRAY['M3-1-u6-X19']::text[],true,'{"seq":1,"concept":"M3-1-u6-C1","difficulty":1,"kind":"mc","stem":"이 도형은 똑같이 몇으로 나누었나요?","options":[{"t":"넷","correct":true},{"t":"셋","mis":"M3-1-u6-X19"},{"t":"다섯","mis":"M3-1-u6-X19"},{"t":"여덟","mis":"M3-1-u6-X19"}],"explanation":["조각을 하나씩 짚어 세면 4개예요.","조각의 모양과 크기가 모두 같아요.","그래서 똑같이 넷으로 나눈 거예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 이 도형은 똑같이 몇으로 나누었나요?","options":[{"t":"둘","correct":true},{"t":"하나","mis":"M3-1-u6-X19"},{"t":"셋","mis":"M3-1-u6-X19"},{"t":"넷","mis":"M3-1-u6-X19"}],"explanation":["조각을 하나씩 짚어 세면 2개예요.","조각의 모양과 크기가 모두 같아요.","그래서 똑같이 둘로 나눈 거예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,2],[0,2]]},{"p":[[1,0],[2,0],[2,2],[1,2]]}]}},{"stem":"이번에는 다른 문제예요. 이 도형은 똑같이 몇으로 나누었나요?","options":[{"t":"여섯","correct":true},{"t":"다섯","mis":"M3-1-u6-X19"},{"t":"일곱","mis":"M3-1-u6-X19"},{"t":"열둘","mis":"M3-1-u6-X19"}],"explanation":["조각을 하나씩 짚어 세면 6개예요.","조각의 모양과 크기가 모두 같아요.","그래서 똑같이 여섯으로 나눈 거예요."],"asset":{"type":"tiles","pieces":[{"p":[[1.5,1.5],[1.5,0],[1.657,0.008],[1.812,0.033],[1.964,0.073],[2.11,0.13],[2.25,0.201],[2.382,0.286],[2.504,0.385],[2.615,0.496],[2.714,0.618],[2.799,0.75]]},{"p":[[1.5,1.5],[2.799,0.75],[2.87,0.89],[2.927,1.036],[2.967,1.188],[2.992,1.343],[3,1.5],[2.992,1.657],[2.967,1.812],[2.927,1.964],[2.87,2.11],[2.799,2.25]]},{"p":[[1.5,1.5],[2.799,2.25],[2.714,2.382],[2.615,2.504],[2.504,2.615],[2.382,2.714],[2.25,2.799],[2.11,2.87],[1.964,2.927],[1.812,2.967],[1.657,2.992],[1.5,3]]},{"p":[[1.5,1.5