INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L02_basic#2','math',3,1,'u6','L02','g3_1_math_u6_L02_basic','lesson_basic','M3-1-u6-C1',1,'ox','auto','이 도형은 똑같이 셋으로 나누어졌어요.',ARRAY['M3-1-u6-X01']::text[],true,'{"seq":2,"concept":"M3-1-u6-C1","difficulty":1,"kind":"ox","stem":"이 도형은 똑같이 셋으로 나누어졌어요.","answer":"X","reason_options":[{"t":"조각의 크기가 서로 달라서","correct":true},{"t":"조각이 3개라서","mis":"M3-1-u6-X01"}],"mis":"M3-1-u6-X01","explanation":["조각은 3개지만 크기가 서로 달라요.","겹쳐 보면 꼭 맞지 않아요.","조각 수만 같다고 똑같이 나눈 것이 아니에요 — ×."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,2],[0,2]]},{"p":[[1,0],[3,0],[3,2],[1,2]]},{"p":[[3,0],[4,0],[4,2],[3,2]]}]},"variant_rule":{"alt":[{"stem":"이 도형은 똑같이 둘로 나누어졌어요.","answer":"X","reason_options":[{"t":"조각의 크기가 서로 달라서","correct":true},{"t":"조각이 2개라서","mis":"M3-1-u6-X01"}],"explanation":["조각은 2개지만 크기가 서로 달라요.","겹쳐 보면 꼭 맞지 않아요.","조각 수만 같다고 똑같이 나눈 것이 아니에요 — ×."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1.4,0],[1.4,2],[0,2]]},{"p":[[1.4,0],[2,0],[2,2],[1.4,2]]}]}},{"stem":"이 도형은 똑같이 나누어졌어요.","answer":"O","reason_options":[{"t":"조각의 모양과 크기가 모두 같아서","correct":true},{"t":"조각 수만 세면 되어서","mis":"M3-1-u6-X01"}],"explanation":["조각을 겹쳐 보면 모양과 크기가 꼭 맞아요.","2조각의 크기가 모두 같아요.","그래서 똑같이 나눈 거예요 — ○."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[2,0],[0,2]]},{"p":[[2,0],[2,2],[0,2]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L02_basic#3','math',3,1,'u6','L02','g3_1_math_u6_L02_basic','lesson_basic','M3-1-u6-C1',1,'mc','auto','다문화 축제에서 떡 한 개를 똑같이 넷으로 나누었어요. 나눈 조각을 모두 모으면 무엇이 될까요?',ARRAY['M3-1-u6-X19','M3-1-u6-X04']::text[],true,'{"seq":3,"concept":"M3-1-u6-C1","difficulty":1,"kind":"mc","stem":"다문화 축제에서 떡 한 개를 똑같이 넷으로 나누었어요. 나눈 조각을 모두 모으면 무엇이 될까요?","options":[{"t":"처음 떡 한 개","correct":true},{"t":"떡 4개","mis":"M3-1-u6-X19"},{"t":"한 조각","mis":"M3-1-u6-X04"},{"t":"처음 떡의 반","mis":"M3-1-u6-X19"}],"explanation":["똑같이 나눈 조각은 처음 전체를 쪼갠 것이에요.","조각 4개를 모두 모으면 다시 처음 모양이 돼요.","그래서 처음 떡 한 개가 돼요."],"variant_rule":{"alt":[{"stem":"다문화 축제에서 타르트 한 개를 똑같이 둘로 나누었어요. 나눈 조각을 모두 모으면 무엇이 될까요?","options":[{"t":"처음 타르트 한 개","correct":true},{"t":"타르트 2개","mis":"M3-1-u6-X19"},{"t":"한 조각","mis":"M3-1-u6-X04"},{"t":"처음 타르트의 반","mis":"M3-1-u6-X19"}],"explanation":["똑같이 나눈 조각은 처음 전체를 쪼갠 것이에요.","조각 2개를 모두 모으면 다시 처음 모양이 돼요.","그래서 처음 타르트 한 개가 돼요."],"asset":null},{"stem":"다문화 축제에서 케이크 한 개를 똑같이 넷으로 나누었어요. 나눈 조각을 모두 모으면 무엇이 될까요?","options":[{"t":"처음 케이크 한 개","correct":true},{"t":"케이크 4개","mis":"M3-1-u6-X19"},{"t":"한 조각","mis":"M3-1-u6-X04"},{"t":"처음 케이크의 반","mis":"M3-1-u6-X19"}],"explanation":["똑같이 나눈 조각은 처음 전체를 쪼갠 것이에요.","조각 4개를 모두 모으면 다시 처음 모양이 돼요.","그래서 처음 케이크 한 개가 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
