INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L02_basic#8','math',3,1,'u6','L02','g3_1_math_u6_L02_basic','lesson_basic','M3-1-u6-C1',2,'error','auto','「똑같이 나누기」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u6-X01','M3-1-u6-X18']::text[],true,'{"seq":8,"concept":"M3-1-u6-C1","difficulty":2,"kind":"error","stem":"「똑같이 나누기」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「조각 수만 맞으면 똑같이 나눈 거야」","correct":true,"mis_target":"M3-1-u6-X01"},{"t":"태오 — 「조각의 크기가 모두 같아야 해」","mis":"M3-1-u6-X18"},{"t":"지윤 — 「나눈 조각을 다시 모으면 처음 전체가 돼」","mis":"M3-1-u6-X18"}],"explanation":["똑같이 나누면 조각의 모양과 크기가 모두 같아요.","민서의 말은 크기를 보지 않았어요.","조각 수만으로는 똑같이 나눈 것인지 알 수 없어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 「똑같이 나누기」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「조각 모양만 비슷하면 크기는 달라도 돼」","correct":true,"mis_target":"M3-1-u6-X01"},{"t":"도윤 — 「나눈 조각을 다시 모으면 처음 전체가 돼」","mis":"M3-1-u6-X18"},{"t":"지유 — 「한 조각은 전체보다 작아」","mis":"M3-1-u6-X18"}],"explanation":["똑같이 나누면 조각의 모양과 크기가 모두 같아요.","민서의 말은 크기를 보지 않았어요.","조각 수만으로는 똑같이 나눈 것인지 알 수 없어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 「똑같이 나누기」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「조각 모양만 비슷하면 크기는 달라도 돼」","correct":true,"mis_target":"M3-1-u6-X01"},{"t":"나래 — 「한 조각은 전체보다 작아」","mis":"M3-1-u6-X18"},{"t":"태오 — 「조각의 크기가 모두 같아야 해」","mis":"M3-1-u6-X18"}],"explanation":["똑같이 나누면 조각의 모양과 크기가 모두 같아요.","서준의 말은 크기를 보지 않았어요.","조각 수만으로는 똑같이 나눈 것인지 알 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L02_basic#9','math',3,1,'u6','L02','g3_1_math_u6_L02_basic','lesson_basic','M3-1-u6-C1',2,'sa','auto','정사각형 색종이를 반으로 두 번 접었다가 폈어요. 색종이는 똑같이 몇 조각으로 나뉘나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u6-C1","difficulty":2,"kind":"sa","stem":"정사각형 색종이를 반으로 두 번 접었다가 폈어요. 색종이는 똑같이 몇 조각으로 나뉘나요? 숫자로 쓰세요.","answer":["4"],"explanation":["반으로 한 번 접으면 2조각이에요.","한 번 더 접을 때마다 조각이 2배가 돼요.","반으로 두 번 접으면 4조각이에요 — 접은 선의 수가 아니라 조각 수를 세요."],"variant_rule":{"alt":[{"stem":"정사각형 색종이를 반으로 한 번 접었다가 폈어요. 색종이는 똑같이 몇 조각으로 나뉘나요? 숫자로 쓰세요.","answer":["2"],"explanation":["반으로 한 번 접으면 2조각이에요.","두 조각의 크기는 같아요.","반으로 한 번 접으면 2조각이에요 — 접은 선의 수가 아니라 조각 수를 세요."],"asset":null},{"stem":"정사각형 색종이를 반으로 세 번 접었다가 폈어요. 색종이는 똑같이 몇 조각으로 나뉘나요? 숫자로 쓰세요.","answer":["8"],"explanation":["반으로 한 번 접으면 2조각이에요.","한 번 더 접을 때마다 조각이 2배가 돼요.","반으로 세 번 접으면 8조각이에요 — 접은 선의 수가 아니라 조각 수를 세요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L02_basic#10','math',3,1,'u6','L02','g3_1_math_u6_L02_basic','lesson_basic','M3-1-u6-C1',3,'sa','auto','크기가 다른 조각으로 나눈 띠예요. 큰 조각만 작은 조각과 크기가 같게 둘로 더 나누면, 띠는 똑같이 몇 조각이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u6-C1","difficulty":3,"kind":"sa","stem":"크기가 다른 조각으로 나눈 띠예요. 큰 조각만 작은 조각과 크기가 같게 둘로 더 나누면, 띠는 똑같이 몇 조각이 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["큰 조각은 작은 조각 2개만 해요.","큰 조각을 둘로 나누면 모든 조각의 크기가 같아져요.","작은 조각과 같은 크기 조각이 모두 4개 — 똑같이 4조각이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[2,0],[2,2],[0,2]]},{"p":[[2,0],[3,0],[3,2],[2,2]]},{"p":[[3,0],[4,0],[4,2],[3,2]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 크기가 다른 조각으로 나눈 띠예요. 큰 조각만 작은 조각과 크기가 같게 둘로 더 나누면, 띠는 똑같이 몇 조각이 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["큰 조각은 작은 조각 2개만 해요.","큰 조각을 둘로 나누면 모든 조각의 크기가 같아져요.","작은 조각과 같은 크기 조각이 모두 5개 — 똑같이 5조각이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,2],[0,2]]},{"p":[[1,0],[2,0],[2,2],[1,2]]},{"p":[[2,0],[4,0],[4,2],[2,2]]},{"p":[[4,0],[5,0],[5,2],[4,2]]}]}},{"stem":"이번에는 다른 문제예요. 크기가 다른 조각으로 나눈 띠예요. 큰 조각만 작은 조각과 크기가 같게 둘로 더 나누면, 띠는 똑같이 몇 조각이 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["큰 조각은 작은 조각 2개만 해요.","큰 조각을 둘로 나누면 모든 조각의 크기가 같아져요.","작은 조각과 같은 크기 조각이 모두 4개 — 똑같이 4조각이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,2],[0,2]]},{"p":[[1,0],[3,0],[3,2],[1,2]]},{"p":[[3,0],[4,0],[4,2],[3,2]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
