INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L02_challenge#8','math',3,1,'u6','L02','g3_1_math_u6_L02_challenge','lesson_challenge','M3-1-u6-C1',4,'essay','teacher','서준이가 크기가 다른 세 조각으로 자른 떡을 보고 「조각이 셋이니까 똑같이 셋으로 나눈 거야.」라고 했어요. 서준이의 말이 맞는지 판단하고, 그렇게 생각한 까닭을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u6-C1","difficulty":4,"kind":"essay","stem":"서준이가 크기가 다른 세 조각으로 자른 떡을 보고 「조각이 셋이니까 똑같이 셋으로 나눈 거야.」라고 했어요. 서준이의 말이 맞는지 판단하고, 그렇게 생각한 까닭을 써 보세요.","answer_guide":{"answer":"예: 틀렸다. 똑같이 나누었다는 것은 나눈 조각의 모양과 크기가 모두 같다는 뜻이다. 조각이 셋이어도 크기가 다르면 똑같이 나눈 것이 아니다. 조각을 겹쳐 보면 꼭 맞지 않는다.","scoring_points":["틀렸다고 판단했는가","조각의 크기가 모두 같아야 한다고 썼는가","겹쳐 보기 등 확인 방법을 들었는가"]},"explanation":["조각 수만으로는 알 수 없어요.","크기가 모두 같아야 똑같이 나눈 거예요.","그래서 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L02_challenge#9','math',3,1,'u6','L02','g3_1_math_u6_L02_challenge','lesson_challenge','M3-1-u6-C1',4,'essay','teacher','정사각형 떡을 친구 네 명이 똑같이 나누어 먹으려고 해요. 똑같이 넷으로 나누는 방법을 두 가지 쓰고, 똑같이 나누었는지 확인하는 방법도 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u6-C1","difficulty":4,"kind":"essay","stem":"정사각형 떡을 친구 네 명이 똑같이 나누어 먹으려고 해요. 똑같이 넷으로 나누는 방법을 두 가지 쓰고, 똑같이 나누었는지 확인하는 방법도 써 보세요.","answer_guide":{"answer":"예: ① 가로로 한 번, 세로로 한 번 잘라 작은 정사각형 4개로 나눈다. ② 두 대각선을 따라 잘라 삼각형 4개로 나눈다. 나눈 조각을 서로 겹쳐 보아 모양과 크기가 꼭 맞으면 똑같이 나눈 것이다.","scoring_points":["똑같이 넷으로 나누는 방법을 두 가지 썼는가","두 방법 모두 네 조각의 크기가 같은가","겹쳐 보기(또는 다시 모으기)로 확인하는 방법을 썼는가"]},"explanation":["나누는 방법은 여러 가지예요.","어떻게 나누든 네 조각의 크기가 같아야 해요.","겹쳐 보면 확인할 수 있어요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]},{"p":[[2.9,0],[4.9,0],[3.9,1]]},{"p":[[4.9,0],[4.9,2],[3.9,1]]},{"p":[[4.9,2],[2.9,2],[3.9,1]]},{"p":[[2.9,2],[2.9,0],[3.9,1]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
