INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L03_basic#1','math',3,1,'u6','L03','g3_1_math_u6_L03_basic','lesson_basic','M3-1-u6-C2',1,'mc','auto','색칠한 부분은 전체의 얼마인지 분수로 나타내면 무엇인가요?',ARRAY['M3-1-u6-X02','M3-1-u6-X04','M3-1-u6-X19']::text[],true,'{"seq":1,"concept":"M3-1-u6-C2","difficulty":1,"kind":"mc","stem":"색칠한 부분은 전체의 얼마인지 분수로 나타내면 무엇인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨4/3⟩","mis":"M3-1-u6-X02"},{"t":"⟨1/4⟩","mis":"M3-1-u6-X04"},{"t":"⟨3/5⟩","mis":"M3-1-u6-X19"}],"explanation":["전체를 똑같이 4칸으로 나누었어요 — 분모 4.","색칠한 칸은 3칸이에요 — 분자 3.","색칠한 부분은 ⟨3/4⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 색칠한 부분은 전체의 얼마인지 분수로 나타내면 무엇인가요?","options":[{"t":"⟨3/6⟩","correct":true},{"t":"⟨6/3⟩","mis":"M3-1-u6-X02"},{"t":"⟨1/6⟩","mis":"M3-1-u6-X05"},{"t":"⟨3/7⟩","mis":"M3-1-u6-X19"}],"explanation":["전체를 똑같이 6칸으로 나누었어요 — 분모 6.","색칠한 칸은 3칸이에요 — 분자 3.","색칠한 부분은 ⟨3/6⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,2],[0,2]],"hi":true},{"p":[[1,0],[2,0],[2,2],[1,2]]},{"p":[[2,0],[3,0],[3,2],[2,2]]},{"p":[[3,0],[4,0],[4,2],[3,2]],"hi":true},{"p":[[4,0],[5,0],[5,2],[4,2]]},{"p":[[5,0],[6,0],[6,2],[5,2]],"hi":true}]}},{"stem":"이번에는 다른 문제예요. 색칠한 부분은 전체의 얼마인지 분수로 나타내면 무엇인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨3/4⟩","mis":"M3-1-u6-X04"},{"t":"⟨1/3⟩","mis":"M3-1-u6-X03"},{"t":"⟨1/5⟩","mis":"M3-1-u6-X19"}],"explanation":["전체를 똑같이 4칸으로 나누었어요 — 분모 4.","색칠한 칸은 1칸이에요 — 분자 1.","색칠한 부분은 ⟨1/4⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO