INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L03_basic#2','math',3,1,'u6','L03','g3_1_math_u6_L03_basic','lesson_basic','M3-1-u6-C2',1,'mc','auto','분수 ⟨3/5⟩을 바르게 읽은 것은 무엇인가요?',ARRAY['M3-1-u6-X02','M3-1-u6-X06']::text[],true,'{"seq":2,"concept":"M3-1-u6-C2","difficulty":1,"kind":"mc","stem":"분수 ⟨3/5⟩을 바르게 읽은 것은 무엇인가요?","options":[{"t":"오분의 삼","correct":true},{"t":"삼분의 오","mis":"M3-1-u6-X02"},{"t":"삼 점 오","mis":"M3-1-u6-X06"},{"t":"오 더하기 삼","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 5, 분자 3이에요.","⟨3/5⟩은 「오분의 삼」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"분수 ⟨5/8⟩를 바르게 읽은 것은 무엇인가요?","options":[{"t":"팔분의 오","correct":true},{"t":"오분의 팔","mis":"M3-1-u6-X02"},{"t":"오 점 팔","mis":"M3-1-u6-X06"},{"t":"팔 더하기 오","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 8, 분자 5예요.","⟨5/8⟩는 「팔분의 오」라고 읽어요."],"asset":null},{"stem":"분수 ⟨2/5⟩를 바르게 읽은 것은 무엇인가요?","options":[{"t":"오분의 이","correct":true},{"t":"이분의 오","mis":"M3-1-u6-X02"},{"t":"이 점 오","mis":"M3-1-u6-X06"},{"t":"오 더하기 이","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 5, 분자 2예요.","⟨2/5⟩는 「오분의 이」라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L03_basic#3','math',3,1,'u6','L03','g3_1_math_u6_L03_basic','lesson_basic','M3-1-u6-C2',1,'sa','auto','분수 ⟨3/8⟩에서 분모는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u6-C2","difficulty":1,"kind":"sa","stem":"분수 ⟨3/8⟩에서 분모는 무엇인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["분수에서 아래 수가 분모, 위 수가 분자예요.","⟨3/8⟩은 분모 8, 분자 3이에요.","분모는 8이에요."],"variant_rule":{"alt":[{"stem":"분수 ⟨3/5⟩에서 분모는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분수에서 아래 수가 분모, 위 수가 분자예요.","⟨3/5⟩은 분모 5, 분자 3이에요.","분모는 5예요."],"asset":null},{"stem":"분수 ⟨2/3⟩에서 분모는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분수에서 아래 수가 분모, 위 수가 분자예요.","⟨2/3⟩는 분모 3, 분자 2예요.","분모는 3이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
