INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L03_basic#6','math',3,1,'u6','L03','g3_1_math_u6_L03_basic','lesson_basic','M3-1-u6-C3',2,'mc','auto','⟨2/3⟩는 ⟨1/3⟩이 몇 개인가요?',ARRAY['M3-1-u6-X05','M3-1-u6-X04']::text[],true,'{"seq":6,"concept":"M3-1-u6-C3","difficulty":2,"kind":"mc","stem":"⟨2/3⟩는 ⟨1/3⟩이 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"3개","mis":"M3-1-u6-X05"},{"t":"1개","mis":"M3-1-u6-X04"},{"t":"5개","mis":"M3-1-u6-X05"}],"explanation":["⟨2/3⟩는 전체를 3칸으로 나눈 것 중 2칸이에요.","한 칸이 ⟨1/3⟩이에요.","⟨2/3⟩는 ⟨1/3⟩이 2개예요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩는 ⟨1/6⟩이 몇 개인가요?","options":[{"t":"5개","correct":true},{"t":"6개","mis":"M3-1-u6-X05"},{"t":"1개","mis":"M3-1-u6-X04"},{"t":"11개","mis":"M3-1-u6-X05"}],"explanation":["⟨5/6⟩는 전체를 6칸으로 나눈 것 중 5칸이에요.","한 칸이 ⟨1/6⟩이에요.","⟨5/6⟩는 ⟨1/6⟩이 5개예요."],"asset":null},{"stem":"⟨4/6⟩는 ⟨1/6⟩이 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"6개","mis":"M3-1-u6-X05"},{"t":"2개","mis":"M3-1-u6-X04"},{"t":"5개","mis":"M3-1-u6-X19"}],"explanation":["⟨4/6⟩는 전체를 6칸으로 나눈 것 중 4칸이에요.","한 칸이 ⟨1/6⟩이에요.","⟨4/6⟩는 ⟨1/6⟩이 4개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L03_basic#7','math',3,1,'u6','L03','g3_1_math_u6_L03_basic','lesson_basic','M3-1-u6-C3',2,'mc','auto','⟨1/8⟩이 5개이면 어떤 분수인가요?',ARRAY['M3-1-u6-X02','M3-1-u6-X05','M3-1-u6-X03']::text[],true,'{"seq":7,"concept":"M3-1-u6-C3","difficulty":2,"kind":"mc","stem":"⟨1/8⟩이 5개이면 어떤 분수인가요?","options":[{"t":"⟨5/8⟩","correct":true},{"t":"⟨8/5⟩","mis":"M3-1-u6-X02"},{"t":"⟨1/13⟩","mis":"M3-1-u6-X05"},{"t":"⟨5/13⟩","mis":"M3-1-u6-X03"}],"explanation":["⟨1/8⟩이 5개 모이면 분자가 5가 돼요.","분모 8은 그대로예요.","그래서 ⟨5/8⟩예요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩이 2개이면 어떤 분수인가요?","options":[{"t":"⟨2/6⟩","correct":true},{"t":"⟨6/2⟩","mis":"M3-1-u6-X02"},{"t":"⟨1/8⟩","mis":"M3-1-u6-X05"},{"t":"⟨1/12⟩","mis":"M3-1-u6-X05"}],"explanation":["⟨1/6⟩이 2개 모이면 분자가 2가 돼요.","분모 6은 그대로예요.","그래서 ⟨2/6⟩예요."],"asset":null},{"stem":"⟨1/9⟩이 3개이면 어떤 분수인가요?","options":[{"t":"⟨3/9⟩","correct":true},{"t":"⟨9/3⟩","mis":"M3-1-u6-X02"},{"t":"⟨1/12⟩","mis":"M3-1-u6-X05"},{"t":"⟨3/12⟩","mis":"M3-1-u6-X03"}],"explanation":["⟨1/9⟩이 3개 모이면 분자가 3이 돼요.","분모 9는 그대로예요.","그래서 ⟨3/9⟩이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L03_basic#8','math',3,1,'u6','L03','g3_1_math_u6_L03_basic','lesson_basic','M3-1-u6-C2',2,'ox','auto','유나가 ⟨3/8⟩을 두고 「분모는 3, 분자는 8이야.」라고 말했어요. 바르게 말했어요.',ARRAY['M3-1-u6-X02']::text[],true,'{"seq":8,"concept":"M3-1-u6-C2","difficulty":2,"kind":"ox","stem":"유나가 ⟨3/8⟩을 두고 「분모는 3, 분자는 8이야.」라고 말했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"아래 수 8이 분모, 위 수 3이 분자라서","correct":true},{"t":"8분의 3에서 먼저 읽는 수가 분자라서","mis":"M3-1-u6-X02"}],"mis":"M3-1-u6-X02","explanation":["분모는 아래, 분자는 위에 써요.","⟨3/8⟩의 분모는 8, 분자는 3이에요.","유나는 분모와 분자를 바꾸어 말했어요 — ×."],"variant_rule":{"alt":[{"stem":"서준이 ⟨2/6⟩를 두고 「분모는 2, 분자는 6이야.」라고 말했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"아래 수 6이 분모, 위 수 2가 분자라서","correct":true},{"t":"6분의 2에서 먼저 읽는 수가 분자라서","mis":"M3-1-u6-X02"}],"explanation":["분모는 아래, 분자는 위에 써요.","⟨2/6⟩의 분모는 6, 분자는 2예요.","서준는 분모와 분자를 바꾸어 말했어요 — ×."],"asset":null},{"stem":"민서가 ⟨3/4⟩을 두고 「분모는 3, 분자는 4야.」라고 말했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"아래 수 4가 분모, 위 수 3이 분자라서","correct":true},{"t":"4분의 3에서 먼저 읽는 수가 분자라서","mis":"M3-1-u6-X02"}],"explanation":["분모는 아래, 분자는 위에 써요.","⟨3/4⟩의 분모는 4, 분자는 3이에요.","민서는 분모와 분자를 바꾸어 말했어요 — ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L03_basic#9','math',3,1,'u6','L03','g3_1_math_u6_L03_basic','lesson_basic','M3-1-u6-C3',2,'sa','auto','색칠한 부분은 ⟨1/4⟩이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u6-C3","difficulty":2,"kind":"sa","stem":"색칠한 부분은 ⟨1/4⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["전체를 똑같이 4칸으로 나누었으니 한 칸이 ⟨1/4⟩이에요.","색칠한 칸은 2칸이에요.","⟨1/4⟩이 2개 — ⟨2/4⟩."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[2,0],[1,1]]},{"p":[[2,0],[2,2],[1,1]]},{"p":[[2,2],[0,2],[1,1]],"hi":true},{"p":[[0,2],[0,0],[1,1]],"hi":true}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 색칠한 부분은 ⟨1/4⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["전체를 똑같이 4칸으로 나누었으니 한 칸이 ⟨1/4⟩이에요.","색칠한 칸은 3칸이에요.","⟨1/4⟩이 3개 — ⟨3/4⟩."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true}]}},{"stem":"색칠한 부분은 ⟨1/8⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["전체를 똑같이 8칸으로 나누었으니 한 칸이 ⟨1/8⟩이에요.","색칠한 칸은 2칸이에요.","⟨1/8⟩이 2개 — ⟨2/8⟩."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,2],[0,2]],"hi":true},{"p":[[1,0],[2,0],[2,2],[1,2]]},{"p":[[2,0],[3,0],[3,2],[2,2]]},{"p":[[3,0],[4,0],[4,2],[3,2]]},{"p":[[4,0],[5,0],[5,2],[4,2]]},{"p":[[5,0],[6,0],[6,2],[5,2]]},{"p":[[6,0],[7,0],[7,2],[6,2]]},{"p":[[7,0],[8,0],[8,2],[7,2]],"hi":true}],"u":37}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L03_basic#10','math',3,1,'u6','L03','g3_1_math_u6_L03_basic','lesson_basic','M3-1-u6-C2',3,'error','auto','분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u6-X02','M3-1-u6-X18']::text[],true,'{"seq":10,"concept":"M3-1-u6-C2","difficulty":3,"kind":"error","stem":"분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나래 — 「⟨3/7⟩의 분모는 3이야」","correct":true,"mis_target":"M3-1-u6-X02"},{"t":"태오 — 「⟨3/7⟩은 ⟨1/7⟩이 3개야」","mis":"M3-1-u6-X18"},{"t":"유나 — 「⟨3/7⟩은 칠분의 삼이라고 읽어」","mis":"M3-1-u6-X18"}],"explanation":["⟨3/7⟩은 분모 7, 분자 3이에요.","⟨1/7⟩이 3개이고 「칠분의 삼」이라고 읽어요.","나래의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유나 — 「⟨5/9⟩의 분모는 5야」","correct":true,"mis_target":"M3-1-u6-X02"},{"t":"나래 — 「단위분수는 분자가 1이야」","mis":"M3-1-u6-X18"},{"t":"민서 — 「⟨5/9⟩는 구분의 오라고 읽어」","mis":"M3-1-u6-X18"}],"explanation":["⟨5/9⟩는 분모 9, 분자 5예요.","⟨1/9⟩이 5개이고 「구분의 오」라고 읽어요.","유나의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하은 — 「⟨3/5⟩의 분모는 3이야」","correct":true,"mis_target":"M3-1-u6-X02"},{"t":"태오 — 「단위분수는 분자가 1이야」","mis":"M3-1-u6-X18"},{"t":"지윤 — 「⟨3/5⟩은 오분의 삼이라고 읽어」","mis":"M3-1-u6-X18"}],"explanation":["⟨3/5⟩은 분모 5, 분자 3이에요.","⟨1/5⟩이 3개이고 「오분의 삼」이라고 읽어요.","하은의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L03_challenge#1','math',3,1,'u6','L03','g3_1_math_u6_L03_challenge','lesson_challenge','M3-1-u6-C2',2,'match','auto','분수와 읽는 말을 알맞게 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u6-C2","difficulty":2,"kind":"match","stem":"분수와 읽는 말을 알맞게 이으세요.","pairs":[{"l":"⟨3/7⟩","r":"칠분의 삼"},{"l":"⟨3/9⟩","r":"구분의 삼"},{"l":"⟨3/8⟩","r":"팔분의 삼"}],"mis":"M3-1-u6-X02","explanation":["아래 분모를 먼저 「○분의」로 읽어요.","⟨3/7⟩ = 칠분의 삼, ⟨3/9⟩ = 구분의 삼, ⟨3/8⟩ = 팔분의 삼.","분모와 분자를 바꾸면 다른 분수예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 분수와 읽는 말을 알맞게 이으세요.","pairs":[{"l":"⟨2/5⟩","r":"오분의 이"},{"l":"⟨2/4⟩","r":"사분의 이"},{"l":"⟨2/8⟩","r":"팔분의 이"}],"explanation":["아래 분모를 먼저 「○분의」로 읽어요.","⟨2/5⟩ = 오분의 이, ⟨2/4⟩ = 사분의 이, ⟨2/8⟩ = 팔분의 이.","분모와 분자를 바꾸면 다른 분수예요."],"asset":null},{"stem":"이번에는 다른 문제예요. 분수와 읽는 말을 알맞게 이으세요.","pairs":[{"l":"⟨2/9⟩","r":"구분의 이"},{"l":"⟨1/5⟩","r":"오분의 일"},{"l":"⟨5/9⟩","r":"구분의 오"}],"explanation":["아래 분모를 먼저 「○분의」로 읽어요.","⟨2/9⟩ = 구분의 이, ⟨1/5⟩ = 오분의 일, ⟨5/9⟩ = 구분의 오.","분모와 분자를 바꾸면 다른 분수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
