INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L03_challenge#7','math',3,1,'u6','L03','g3_1_math_u6_L03_challenge','lesson_challenge','M3-1-u6-C2',3,'error','auto','분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u6-X02','M3-1-u6-X18']::text[],true,'{"seq":7,"concept":"M3-1-u6-C2","difficulty":3,"kind":"error","stem":"분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「⟨6/7⟩의 분모는 6이야」","correct":true,"mis_target":"M3-1-u6-X02"},{"t":"지윤 — 「⟨6/7⟩은 ⟨1/7⟩이 6개야」","mis":"M3-1-u6-X18"},{"t":"유나 — 「단위분수는 분자가 1이야」","mis":"M3-1-u6-X18"}],"explanation":["⟨6/7⟩은 분모 7, 분자 6이에요.","⟨1/7⟩이 6개이고 「칠분의 육」이라고 읽어요.","태오의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「⟨2/5⟩의 분모는 2야」","correct":true,"mis_target":"M3-1-u6-X02"},{"t":"유나 — 「아래 수가 분모, 위 수가 분자야」","mis":"M3-1-u6-X18"},{"t":"도윤 — 「⟨2/5⟩는 오분의 이라고 읽어」","mis":"M3-1-u6-X18"}],"explanation":["⟨2/5⟩는 분모 5, 분자 2예요.","⟨1/5⟩이 2개이고 「오분의 이」라고 읽어요.","민서의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지윤 — 「⟨3/10⟩은 ⟨1/10⟩이 10개야」","correct":true,"mis_target":"M3-1-u6-X05"},{"t":"현우 — 「⟨3/10⟩은 십분의 삼이라고 읽어」","mis":"M3-1-u6-X18"},{"t":"유나 — 「아래 수가 분모, 위 수가 분자야」","mis":"M3-1-u6-X18"}],"explanation":["⟨3/10⟩은 분모 10, 분자 3이에요.","⟨1/10⟩이 3개이고 「십분의 삼」이라고 읽어요.","지윤의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L03_challenge#8','math',3,1,'u6','L03','g3_1_math_u6_L03_challenge','lesson_challenge','M3-1-u6-C2',4,'essay','teacher','도윤이는 똑같이 네 칸으로 나눈 도형에서 3칸을 색칠하고 색칠한 부분을 ⟨3/1⟩이라고 썼어요. 도윤이가 무엇을 잘못했는지 쓰고, 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u6-C2","difficulty":4,"kind":"essay","stem":"도윤이는 똑같이 네 칸으로 나눈 도형에서 3칸을 색칠하고 색칠한 부분을 ⟨3/1⟩이라고 썼어요. 도윤이가 무엇을 잘못했는지 쓰고, 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 분모에는 전체를 똑같이 나눈 칸 수인 4를 써야 하는데 색칠하지 않은 칸 수 1을 썼다. 분자는 색칠한 칸 수 3이다. 바르게 쓰면 ⟨3/4⟩(4분의 3)이다.","scoring_points":["분모 자리에 전체 칸 수를 써야 한다고 썼는가","분자는 색칠한 칸 수라고 썼는가","⟨3/4⟩으로 고쳤는가"]},"explanation":["분모 = 전체를 똑같이 나눈 수.","분자 = 그중 색칠한 수.","⟨3/4⟩이 맞아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L03_challenge#9','math',3,1,'u6','L03','g3_1_math_u6_L03_challenge','lesson_challenge','M3-1-u6-C3',4,'essay','teacher','⟨5/8⟩는 ⟨1/8⟩이 몇 개인지 쓰고, 띠 그림을 이용해 그렇게 생각한 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u6-C3","difficulty":4,"kind":"essay","stem":"⟨5/8⟩는 ⟨1/8⟩이 몇 개인지 쓰고, 띠 그림을 이용해 그렇게 생각한 까닭을 설명해 보세요.","answer_guide":{"answer":"예: ⟨5/8⟩는 ⟨1/8⟩이 5개이다. 띠를 똑같이 8칸으로 나누면 한 칸이 ⟨1/8⟩이고, ⟨5/8⟩는 그중 5칸이므로 한 칸이 5개 모인 것이다.","scoring_points":["5개라고 답했는가","한 칸이 ⟨1/8⟩임을 썼는가","분자만큼 모였다고 설명했는가"]},"explanation":["8칸 중 한 칸이 ⟨1/8⟩이에요.","⟨5/8⟩는 그중 5칸이에요.","⟨1/8⟩이 5개예요."],"asset":{"type":"fbar","bars":[{"den":8,"num":5}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L03_challenge#10','math',3,1,'u6','L03','g3_1_math_u6_L03_challenge','lesson_challenge','M3-1-u6-C2',4,'mc','auto','분모가 12보다 크지 않은 분수예요. 분모와 분자를 더하면 8이고, 분모가 분자보다 2 커요. 이 분수는 무엇인가요?',ARRAY['M3-1-u6-X02','M3-1-u6-X19']::text[],true,'{"seq":10,"concept":"M3-1-u6-C2","difficulty":4,"kind":"mc","stem":"분모가 12보다 크지 않은 분수예요. 분모와 분자를 더하면 8이고, 분모가 분자보다 2 커요. 이 분수는 무엇인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨5/3⟩","mis":"M3-1-u6-X02"},{"t":"⟨2/8⟩","mis":"M3-1-u6-X19"},{"t":"⟨2/6⟩","mis":"M3-1-u6-X19"}],"explanation":["분모 + 분자 = 8, 분모 − 분자 = 2예요.","합에서 차를 빼면 분자의 2배 — 8 − 2 = 6, 분자 3.","분모는 5 — 분수는 ⟨3/5⟩이에요."],"variant_rule":{"alt":[{"stem":"분모가 12보다 크지 않은 분수예요. 분모와 분자를 더하면 8이고, 분모가 분자보다 4 커요. 이 분수는 무엇인가요?","options":[{"t":"⟨2/6⟩","correct":true},{"t":"⟨6/2⟩","mis":"M3-1-u6-X02"},{"t":"⟨4/8⟩","mis":"M3-1-u6-X19"},{"t":"⟨3/5⟩","mis":"M3-1-u6-X19"}],"explanation":["분모 + 분자 = 8, 분모 − 분자 = 4예요.","합에서 차를 빼면 분자의 2배 — 8 − 4 = 4, 분자 2.","분모는 6 — 분수는 ⟨2/6⟩예요."],"asset":null},{"stem":"분모가 12보다 크지 않은 분수예요. 분모와 분자를 더하면 19이고, 분모가 분자보다 3 커요. 이 분수는 무엇인가요?","options":[{"t":"⟨8/11⟩","correct":true},{"t":"⟨11/8⟩","mis":"M3-1-u6-X02"},{"t":"⟨3/19⟩","mis":"M3-1-u6-X19"},{"t":"⟨9/10⟩","mis":"M3-1-u6-X19"}],"explanation":["분모 + 분자 = 19, 분모 − 분자 = 3이에요.","합에서 차를 빼면 분자의 2배 — 19 − 3 = 16, 분자 8.","분모는 11 — 분수는 ⟨8/11⟩이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L04_basic#1','math',3,1,'u6','L04','g3_1_math_u6_L04_basic','lesson_basic','M3-1-u6-C4',1,'mc','auto','색칠하지 않은 부분은 전체의 얼마인지 분수로 나타내면 무엇인가요?',ARRAY['M3-1-u6-X04','M3-1-u6-X03','M3-1-u6-X19']::text[],true,'{"seq":1,"concept":"M3-1-u6-C4","difficulty":1,"kind":"mc","stem":"색칠하지 않은 부분은 전체의 얼마인지 분수로 나타내면 무엇인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨3/4⟩","mis":"M3-1-u6-X04"},{"t":"⟨1/3⟩","mis":"M3-1-u6-X03"},{"t":"⟨1/5⟩","mis":"M3-1-u6-X19"}],"explanation":["전체를 똑같이 4칸으로 나누었어요 — 분모 4.","색칠하지 않은 칸은 1칸이에요 — 분자 1.","색칠하지 않은 부분은 ⟨1/4⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 색칠하지 않은 부분은 전체의 얼마인지 분수로 나타내면 무엇인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨4/3⟩","mis":"M3-1-u6-X02"},{"t":"⟨1/4⟩","mis":"M3-1-u6-X04"},{"t":"⟨3/5⟩","mis":"M3-1-u6-X19"}],"explanation":["전체를 똑같이 4칸으로 나누었어요 — 분모 4.","색칠하지 않은 칸은 3칸이에요 — 분자 3.","색칠하지 않은 부분은 ⟨3/4⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[3,0],[3,0.7],[0,0.7]]},{"p":[[0,0.7],[3,0.7],[3,1.4],[0,1.4]]},{"p":[[0,1.4],[3,1.4],[3,2.1],[0,2.1]]},{"p":[[0,2.1],[3,2.1],[3,2.8],[0,2.8]],"hi":true}]}},{"stem":"이번에는 다른 문제예요. 색칠하지 않은 부분은 전체의 얼마인지 분수로 나타내면 무엇인가요?","options":[{"t":"⟨2/4⟩","correct":true},{"t":"⟨4/2⟩","mis":"M3-1-u6-X02"},{"t":"⟨1/4⟩","mis":"M3-1-u6-X05"},{"t":"⟨2/5⟩","mis":"M3-1-u6-X19"}],"explanation":["전체를 똑같이 4칸으로 나누었어요 — 분모 4.","색칠하지 않은 칸은 2칸이에요 — 분자 2.","색칠하지 않은 부분은 ⟨2/4⟩예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE