INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L04_basic#2','math',3,1,'u6','L04','g3_1_math_u6_L04_basic','lesson_basic','M3-1-u6-C4',1,'mc','auto','국기 도화지 전체 중 ⟨2/5⟩만큼을 사용했어요. 남은 부분은 전체의 얼마인가요?',ARRAY['M3-1-u6-X04','M3-1-u6-X02','M3-1-u6-X03']::text[],true,'{"seq":2,"concept":"M3-1-u6-C4","difficulty":1,"kind":"mc","stem":"국기 도화지 전체 중 ⟨2/5⟩만큼을 사용했어요. 남은 부분은 전체의 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨2/5⟩","mis":"M3-1-u6-X04"},{"t":"⟨5/3⟩","mis":"M3-1-u6-X02"},{"t":"⟨3/2⟩","mis":"M3-1-u6-X03"}],"explanation":["사용한 부분 + 남은 부분 = 전체예요.","전체 5칸 중 2칸을 썼으니 3칸이 남아요.","남은 부분은 ⟨3/5⟩이에요."],"variant_rule":{"alt":[{"stem":"색 도화지 전체 중 ⟨2/6⟩만큼을 사용했어요. 남은 부분은 전체의 얼마인가요?","options":[{"t":"⟨4/6⟩","correct":true},{"t":"⟨2/6⟩","mis":"M3-1-u6-X04"},{"t":"⟨6/4⟩","mis":"M3-1-u6-X02"},{"t":"⟨4/2⟩","mis":"M3-1-u6-X03"}],"explanation":["사용한 부분 + 남은 부분 = 전체예요.","전체 6칸 중 2칸을 썼으니 4칸이 남아요.","남은 부분은 ⟨4/6⟩예요."],"asset":null},{"stem":"포장지 전체 중 ⟨2/4⟩만큼을 사용했어요. 남은 부분은 전체의 얼마인가요?","options":[{"t":"⟨2/4⟩","correct":true},{"t":"⟨4/2⟩","mis":"M3-1-u6-X02"},{"t":"⟨3/4⟩","mis":"M3-1-u6-X19"},{"t":"⟨1/4⟩","mis":"M3-1-u6-X05"}],"explanation":["사용한 부분 + 남은 부분 = 전체예요.","전체 4칸 중 2칸을 썼으니 2칸이 남아요.","남은 부분은 ⟨2/4⟩예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L04_basic#3','math',3,1,'u6','L04','g3_1_math_u6_L04_basic','lesson_basic','M3-1-u6-C4',1,'sa','auto','⟨1/4⟩이 몇 개 모이면 전체가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u6-C4","difficulty":1,"kind":"sa","stem":"⟨1/4⟩이 몇 개 모이면 전체가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨1/4⟩은 전체를 똑같이 4칸으로 나눈 한 칸이에요.","한 칸이 4개 모이면 전체예요.","단위분수는 분모만큼 모이면 전체 — 4개."],"variant_rule":{"alt":[{"stem":"⟨1/3⟩이 몇 개 모이면 전체가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨1/3⟩은 전체를 똑같이 3칸으로 나눈 한 칸이에요.","한 칸이 3개 모이면 전체예요.","단위분수는 분모만큼 모이면 전체 — 3개."],"asset":null},{"stem":"⟨1/8⟩이 몇 개 모이면 전체가 되나요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨1/8⟩은 전체를 똑같이 8칸으로 나눈 한 칸이에요.","한 칸이 8개 모이면 전체예요.","단위분수는 분모만큼 모이면 전체 — 8개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
