INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_basic#4','math',3,1,'u6','L05','g3_1_math_u6_L05_basic','lesson_basic','M3-1-u6-C5',1,'mc','auto','분모가 같은 분수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['M3-1-u6-X09','M3-1-u6-X20']::text[],true,'{"seq":4,"concept":"M3-1-u6-C5","difficulty":1,"kind":"mc","stem":"분모가 같은 분수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"분자가 클수록 큰 분수예요","correct":true},{"t":"분자가 작을수록 큰 분수예요","mis":"M3-1-u6-X09"},{"t":"분모가 같으니 늘 두 분수가 같아요","mis":"M3-1-u6-X20"},{"t":"분모가 클수록 큰 분수예요","mis":"M3-1-u6-X09"}],"explanation":["분모가 같으면 한 칸(단위분수)의 크기가 같아요.","그래서 칸이 많은 쪽, 곧 분자가 큰 쪽이 커요.","분자가 클수록 큰 분수예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 분모가 같은 분수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"분자끼리 견주어 큰 쪽이 커요","correct":true},{"t":"분자가 작을수록 큰 분수예요","mis":"M3-1-u6-X09"},{"t":"분모가 같으니 늘 두 분수가 같아요","mis":"M3-1-u6-X20"},{"t":"분모가 클수록 큰 분수예요","mis":"M3-1-u6-X09"}],"explanation":["분모가 같으면 한 칸(단위분수)의 크기가 같아요.","그래서 칸이 많은 쪽, 곧 분자가 큰 쪽이 커요.","분자끼리 견주어 큰 쪽이 커요."],"asset":null},{"stem":"이번에는 다른 문제예요. 분모가 같은 분수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"단위분수가 많이 모일수록 큰 분수예요","correct":true},{"t":"분자가 작을수록 큰 분수예요","mis":"M3-1-u6-X09"},{"t":"분모가 같으니 늘 두 분수가 같아요","mis":"M3-1-u6-X20"},{"t":"분모가 클수록 큰 분수예요","mis":"M3-1-u6-X09"}],"explanation":["분모가 같으면 한 칸(단위분수)의 크기가 같아요.","그래서 칸이 많은 쪽, 곧 분자가 큰 쪽이 커요.","단위분수가 많이 모일수록 큰 분수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_basic#5','math',3,1,'u6','L05','g3_1_math_u6_L05_basic','lesson_basic','M3-1-u6-C5',2,'mc','auto','크기가 같은 초콜릿을 도윤은 ⟨3/8⟩만큼, 하은은 ⟨5/8⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?',ARRAY['M3-1-u6-X09','M3-1-u6-X20']::text[],true,'{"seq":5,"concept":"M3-1-u6-C5","difficulty":2,"kind":"mc","stem":"크기가 같은 초콜릿을 도윤은 ⟨3/8⟩만큼, 하은은 ⟨5/8⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"하은","correct":true},{"t":"도윤","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["초콜릿 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 3과 5.","분자가 큰 하은이 더 많이 먹었어요."],"variant_rule":{"alt":[{"stem":"크기가 같은 떡을 지윤은 ⟨8/9⟩만큼, 태오는 ⟨6/9⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"지윤","correct":true},{"t":"태오","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["떡 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 8과 6.","분자가 큰 지윤이 더 많이 먹었어요."],"asset":null},{"stem":"크기가 같은 월병을 나래는 ⟨1/7⟩만큼, 서준은 ⟨2/7⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"서준","correct":true},{"t":"나래","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["월병 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 1과 2.","분자가 큰 서준이 더 많이 먹었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_basic#6','math',3,1,'u6','L05','g3_1_math_u6_L05_basic','lesson_basic','M3-1-u6-C5',2,'mc','auto','⟨6/7⟩과 ⟨4/7⟩ 중 더 작은 수는 무엇인가요?',ARRAY['M3-1-u6-X18','M3-1-u6-X20']::text[],true,'{"seq":6,"concept":"M3-1-u6-C5","difficulty":2,"kind":"mc","stem":"⟨6/7⟩과 ⟨4/7⟩ 중 더 작은 수는 무엇인가요?","options":[{"t":"⟨4/7⟩","correct":true},{"t":"⟨6/7⟩","mis":"M3-1-u6-X18"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개, ⟨4/7⟩는 4개예요.","분모가 같으면 분자가 클수록 큰 분수예요.","6 > 4이므로 ⟨6/7⟩ > ⟨4/7⟩."],"variant_rule":{"alt":[{"stem":"⟨2/5⟩와 ⟨4/5⟩ 중 더 작은 수는 무엇인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨4/5⟩","mis":"M3-1-u6-X18"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["⟨2/5⟩는 ⟨1/5⟩이 2개, ⟨4/5⟩는 4개예요.","분모가 같으면 분자가 클수록 큰 분수예요.","2 < 4이므로 ⟨2/5⟩ < ⟨4/5⟩."],"asset":null},{"stem":"⟨5/6⟩와 ⟨4/6⟩ 중 더 작은 수는 무엇인가요?","options":[{"t":"⟨4/6⟩","correct":true},{"t":"⟨5/6⟩","mis":"M3-1-u6-X18"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["⟨5/6⟩는 ⟨1/6⟩이 5개, ⟨4/6⟩는 4개예요.","분모가 같으면 분자가 클수록 큰 분수예요.","5 > 4이므로 ⟨5/6⟩ > ⟨4/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_basic#7','math',3,1,'u6','L05','g3_1_math_u6_L05_basic','lesson_basic','M3-1-u6-C5',2,'sa','auto','⟨4/7⟩는 ⟨3/7⟩보다 ⟨1/7⟩이 몇 개 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u6-C5","difficulty":2,"kind":"sa","stem":"⟨4/7⟩는 ⟨3/7⟩보다 ⟨1/7⟩이 몇 개 더 많은가요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨4/7⟩는 ⟨1/7⟩이 4개예요.","⟨3/7⟩은 3개예요.","4 − 3 = 1개 더 많아요."],"asset":{"type":"fbar","bars":[{"den":7,"num":4},{"den":7,"num":3}]},"variant_rule":{"alt":[{"stem":"⟨4/9⟩는 ⟨1/9⟩보다 ⟨1/9⟩이 몇 개 더 많은가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨4/9⟩는 ⟨1/9⟩이 4개예요.","⟨1/9⟩은 1개예요.","4 − 1 = 3개 더 많아요."],"asset":{"type":"fbar","bars":[{"den":9,"num":4},{"den":9,"num":1}]}},{"stem":"⟨5/6⟩는 ⟨4/6⟩보다 ⟨1/6⟩이 몇 개 더 많은가요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨5/6⟩는 ⟨1/6⟩이 5개예요.","⟨4/6⟩는 4개예요.","5 − 4 = 1개 더 많아요."],"asset":{"type":"fbar","bars":[{"den":6,"num":5},{"den":6,"num":4}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_basic#8','math',3,1,'u6','L05','g3_1_math_u6_L05_basic','lesson_basic','M3-1-u6-C5',2,'ox','auto','크기가 다른 두 종이에 각각 ⟨3/4⟩만큼 색칠했어요. 두 색칠한 부분의 크기는 꼭 같아요.',ARRAY['M3-1-u6-X11']::text[],true,'{"seq":8,"concept":"M3-1-u6-C5","difficulty":2,"kind":"ox","stem":"크기가 다른 두 종이에 각각 ⟨3/4⟩만큼 색칠했어요. 두 색칠한 부분의 크기는 꼭 같아요.","answer":"X","reason_options":[{"t":"전체 종이의 크기가 달라서","correct":true},{"t":"분수가 ⟨3/4⟩으로 같아서","mis":"M3-1-u6-X11"}],"mis":"M3-1-u6-X11","explanation":["분수는 「어떤 전체」를 나눈 것인지가 중요해요.","전체가 크면 ⟨3/4⟩만큼도 커요.","크기가 같은 전체에서만 분수로 견줄 수 있어요 — ×."],"variant_rule":{"alt":[{"stem":"크기가 다른 두 종이에 각각 ⟨1/6⟩만큼 색칠했어요. 두 색칠한 부분의 크기는 꼭 같아요.","answer":"X","reason_options":[{"t":"전체 종이의 크기가 달라서","correct":true},{"t":"분수가 ⟨1/6⟩로 같아서","mis":"M3-1-u6-X11"}],"explanation":["분수는 「어떤 전체」를 나눈 것인지가 중요해요.","전체가 크면 ⟨1/6⟩만큼도 커요.","크기가 같은 전체에서만 분수로 견줄 수 있어요 — ×."],"asset":null},{"stem":"크기가 다른 두 종이에 각각 ⟨4/8⟩만큼 색칠했어요. 두 색칠한 부분의 크기는 꼭 같아요.","answer":"X","reason_options":[{"t":"전체 종이의 크기가 달라서","correct":true},{"t":"분수가 ⟨4/8⟩로 같아서","mis":"M3-1-u6-X11"}],"explanation":["분수는 「어떤 전체」를 나눈 것인지가 중요해요.","전체가 크면 ⟨4/8⟩만큼도 커요.","크기가 같은 전체에서만 분수로 견줄 수 있어요 — ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_basic#9','math',3,1,'u6','L05','g3_1_math_u6_L05_basic','lesson_basic','M3-1-u6-C5',2,'error','auto','분모가 같은 분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u6-X09','M3-1-u6-X18']::text[],true,'{"seq":9,"concept":"M3-1-u6-C5","difficulty":2,"kind":"error","stem":"분모가 같은 분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지윤 — 「분모가 같으면 분자가 작을수록 커」","correct":true,"mis_target":"M3-1-u6-X09"},{"t":"나래 — 「⟨7/9⟩이 ⟨4/9⟩보다 커」","mis":"M3-1-u6-X18"},{"t":"태오 — 「단위분수 개수가 많을수록 커」","mis":"M3-1-u6-X18"}],"explanation":["분모가 같으면 분자가 클수록 커요.","⟨7/9⟩ > ⟨4/9⟩예요.","지윤의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 분모가 같은 분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「⟨3/5⟩이 ⟨4/5⟩보다 커」","correct":true,"mis_target":"M3-1-u6-X09"},{"t":"도윤 — 「단위분수 개수가 많을수록 커」","mis":"M3-1-u6-X18"},{"t":"하은 — 「크기가 같은 전체에서 견주어야 해」","mis":"M3-1-u6-X18"}],"explanation":["분모가 같으면 분자가 클수록 커요.","⟨4/5⟩ > ⟨3/5⟩이에요.","현우의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 분모가 같은 분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나래 — 「분모가 같으니 ⟨7/8⟩과 ⟨1/8⟩은 같아」","correct":true,"mis_target":"M3-1-u6-X20"},{"t":"현우 — 「크기가 같은 전체에서 견주어야 해」","mis":"M3-1-u6-X18"},{"t":"도윤 — 「⟨7/8⟩이 ⟨1/8⟩보다 커」","mis":"M3-1-u6-X18"}],"explanation":["분모가 같으면 분자가 클수록 커요.","⟨7/8⟩ > ⟨1/8⟩이에요.","나래의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_basic#10','math',3,1,'u6','L05','g3_1_math_u6_L05_basic','lesson_basic','M3-1-u6-C5',3,'mc','auto','가장 큰 수는 무엇인가요? ⟨2/7⟩, ⟨4/7⟩, ⟨3/7⟩, ⟨5/7⟩',ARRAY['M3-1-u6-X18','M3-1-u6-X09']::text[],true,'{"seq":10,"concept":"M3-1-u6-C5","difficulty":3,"kind":"mc","stem":"가장 큰 수는 무엇인가요? ⟨2/7⟩, ⟨4/7⟩, ⟨3/7⟩, ⟨5/7⟩","options":[{"t":"⟨5/7⟩","correct":true},{"t":"⟨2/7⟩","mis":"M3-1-u6-X18"},{"t":"⟨4/7⟩","mis":"M3-1-u6-X09"},{"t":"⟨3/7⟩","mis":"M3-1-u6-X09"}],"explanation":["분모가 7로 모두 같아요.","분자를 견주어요 — 2, 4, 3, 5.","가장 큰 분수는 ⟨5/7⟩예요."],"variant_rule":{"alt":[{"stem":"가장 큰 수는 무엇인가요? ⟨6/8⟩, ⟨5/8⟩, ⟨3/8⟩, ⟨2/8⟩","options":[{"t":"⟨6/8⟩","correct":true},{"t":"⟨5/8⟩","mis":"M3-1-u6-X09"},{"t":"⟨3/8⟩","mis":"M3-1-u6-X09"},{"t":"⟨2/8⟩","mis":"M3-1-u6-X18"}],"explanation":["분모가 8로 모두 같아요.","분자를 견주어요 — 6, 5, 3, 2.","가장 큰 분수는 ⟨6/8⟩이에요."],"asset":null},{"stem":"가장 큰 수는 무엇인가요? ⟨5/7⟩, ⟨2/7⟩, ⟨1/7⟩, ⟨6/7⟩","options":[{"t":"⟨6/7⟩","correct":true},{"t":"⟨5/7⟩","mis":"M3-1-u6-X09"},{"t":"⟨2/7⟩","mis":"M3-1-u6-X09"},{"t":"⟨1/7⟩","mis":"M3-1-u6-X18"}],"explanation":["분모가 7로 모두 같아요.","분자를 견주어요 — 5, 2, 1, 6.","가장 큰 분수는 ⟨6/7⟩이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_challenge#1','math',3,1,'u6','L05','g3_1_math_u6_L05_challenge','lesson_challenge','M3-1-u6-C5',2,'mc','auto','두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. ⟨2/8⟩ ○ ⟨6/8⟩',ARRAY['M3-1-u6-X09','M3-1-u6-X20']::text[],true,'{"seq":1,"concept":"M3-1-u6-C5","difficulty":2,"kind":"mc","stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. ⟨2/8⟩ ○ ⟨6/8⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u6-X09"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["⟨2/8⟩는 ⟨1/8⟩이 2개, ⟨6/8⟩은 6개예요.","분모가 같으면 분자가 클수록 큰 분수예요.","2 < 6이므로 ⟨2/8⟩ < ⟨6/8⟩."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. ⟨7/9⟩ ○ ⟨6/9⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u6-X09"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["⟨7/9⟩은 ⟨1/9⟩이 7개, ⟨6/9⟩은 6개예요.","분모가 같으면 분자가 클수록 큰 분수예요.","7 > 6이므로 ⟨7/9⟩ > ⟨6/9⟩."],"asset":null},{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. ⟨5/11⟩ ○ ⟨1/11⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u6-X09"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["⟨5/11⟩는 ⟨1/11⟩이 5개, ⟨1/11⟩은 1개예요.","분모가 같으면 분자가 클수록 큰 분수예요.","5 > 1이므로 ⟨5/11⟩ > ⟨1/11⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_challenge#2','math',3,1,'u6','L05','g3_1_math_u6_L05_challenge','lesson_challenge','M3-1-u6-C5',2,'mc','auto','크기가 같은 초콜릿을 지유는 ⟨4/8⟩만큼, 나래는 ⟨2/8⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?',ARRAY['M3-1-u6-X09','M3-1-u6-X20']::text[],true,'{"seq":2,"concept":"M3-1-u6-C5","difficulty":2,"kind":"mc","stem":"크기가 같은 초콜릿을 지유는 ⟨4/8⟩만큼, 나래는 ⟨2/8⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"지유","correct":true},{"t":"나래","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["초콜릿 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 4와 2.","분자가 큰 지유가 더 많이 먹었어요."],"variant_rule":{"alt":[{"stem":"크기가 같은 떡을 민서는 ⟨8/12⟩만큼, 유나는 ⟨11/12⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"유나","correct":true},{"t":"민서","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["떡 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 8과 11.","분자가 큰 유나가 더 많이 먹었어요."],"asset":null},{"stem":"크기가 같은 월병을 민서는 ⟨4/9⟩만큼, 유나는 ⟨8/9⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"유나","correct":true},{"t":"민서","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["월병 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 4와 8.","분자가 큰 유나가 더 많이 먹었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_challenge#3','math',3,1,'u6','L05','g3_1_math_u6_L05_challenge','lesson_challenge','M3-1-u6-C5',3,'mc','auto','가장 작은 수는 무엇인가요? ⟨3/7⟩, ⟨6/7⟩, ⟨1/7⟩, ⟨4/7⟩',ARRAY['M3-1-u6-X09','M3-1-u6-X18']::text[],true,'{"seq":3,"concept":"M3-1-u6-C5","difficulty":3,"kind":"mc","stem":"가장 작은 수는 무엇인가요? ⟨3/7⟩, ⟨6/7⟩, ⟨1/7⟩, ⟨4/7⟩","options":[{"t":"⟨1/7⟩","correct":true},{"t":"⟨3/7⟩","mis":"M3-1-u6-X09"},{"t":"⟨6/7⟩","mis":"M3-1-u6-X18"},{"t":"⟨4/7⟩","mis":"M3-1-u6-X09"}],"explanation":["분모가 7로 모두 같아요.","분자를 견주어요 — 3, 6, 1, 4.","가장 작은 분수는 ⟨1/7⟩이에요."],"variant_rule":{"alt":[{"stem":"가장 작은 수는 무엇인가요? ⟨8/11⟩, ⟨7/11⟩, ⟨2/11⟩, ⟨1/11⟩","options":[{"t":"⟨1/11⟩","correct":true},{"t":"⟨8/11⟩","mis":"M3-1-u6-X18"},{"t":"⟨7/11⟩","mis":"M3-1-u6-X09"},{"t":"⟨2/11⟩","mis":"M3-1-u6-X09"}],"explanation":["분모가 11로 모두 같아요.","분자를 견주어요 — 8, 7, 2, 1.","가장 작은 분수는 ⟨1/11⟩이에요."],"asset":null},{"stem":"가장 작은 수는 무엇인가요? ⟨5/11⟩, ⟨8/11⟩, ⟨3/11⟩, ⟨10/11⟩","options":[{"t":"⟨3/11⟩","correct":true},{"t":"⟨5/11⟩","mis":"M3-1-u6-X09"},{"t":"⟨8/11⟩","mis":"M3-1-u6-X09"},{"t":"⟨10/11⟩","mis":"M3-1-u6-X18"}],"explanation":["분모가 11로 모두 같아요.","분자를 견주어요 — 5, 8, 3, 10.","가장 작은 분수는 ⟨3/11⟩이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_challenge#4','math',3,1,'u6','L05','g3_1_math_u6_L05_challenge','lesson_challenge','M3-1-u6-C5',3,'sa','auto','⟨□/10⟩ < ⟨4/10⟩ — □ 안에 들어갈 수 있는 수 중 가장 큰 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u6-C5","difficulty":3,"kind":"sa","stem":"⟨□/10⟩ < ⟨4/10⟩ — □ 안에 들어갈 수 있는 수 중 가장 큰 수는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모가 같으니 분자를 견주어요.","□는 4보다 작아야 해요.","그중 가장 큰 수는 3이에요."],"variant_rule":{"alt":[{"stem":"⟨□/7⟩ < ⟨5/7⟩ — □ 안에 들어갈 수 있는 수 중 가장 큰 수는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모가 같으니 분자를 견주어요.","□는 5보다 작아야 해요.","그중 가장 큰 수는 4예요."],"asset":null},{"stem":"⟨□/6⟩ < ⟨3/6⟩ — □ 안에 들어갈 수 있는 수 중 가장 큰 수는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모가 같으니 분자를 견주어요.","□는 3보다 작아야 해요.","그중 가장 큰 수는 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_challenge#5','math',3,1,'u6','L05','g3_1_math_u6_L05_challenge','lesson_challenge','M3-1-u6-C5',3,'sa','auto','⟨□/11⟩는 ⟨6/11⟩보다 크고 ⟨8/11⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u6-C5","difficulty":3,"kind":"sa","stem":"⟨□/11⟩는 ⟨6/11⟩보다 크고 ⟨8/11⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["분모가 같으니 분자만 견주어요.","□는 6보다 크고 8보다 작은 수 — 7.","모두 1개예요."],"variant_rule":{"alt":[{"stem":"⟨□/10⟩는 ⟨5/10⟩보다 크고 ⟨8/10⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모가 같으니 분자만 견주어요.","□는 5보다 크고 8보다 작은 수 — 6, 7.","모두 2개예요."],"asset":null},{"stem":"⟨□/12⟩는 ⟨5/12⟩보다 크고 ⟨10/12⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모가 같으니 분자만 견주어요.","□는 5보다 크고 10보다 작은 수 — 6, 7, 8, 9.","모두 4개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_challenge#6','math',3,1,'u6','L05','g3_1_math_u6_L05_challenge','lesson_challenge','M3-1-u6-C5',3,'error','auto','분모가 같은 분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u6-X09','M3-1-u6-X18']::text[],true,'{"seq":6,"concept":"M3-1-u6-C5","difficulty":3,"kind":"error","stem":"분모가 같은 분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「분모가 같으면 분자가 작을수록 커」","correct":true,"mis_target":"M3-1-u6-X09"},{"t":"도윤 — 「⟨4/7⟩가 ⟨2/7⟩보다 커」","mis":"M3-1-u6-X18"},{"t":"민서 — 「단위분수 개수가 많을수록 커」","mis":"M3-1-u6-X18"}],"explanation":["분모가 같으면 분자가 클수록 커요.","⟨4/7⟩ > ⟨2/7⟩예요.","현우의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 분모가 같은 분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나래 — 「⟨1/12⟩이 ⟨2/12⟩보다 커」","correct":true,"mis_target":"M3-1-u6-X09"},{"t":"하은 — 「단위분수 개수가 많을수록 커」","mis":"M3-1-u6-X18"},{"t":"민서 — 「크기가 같은 전체에서 견주어야 해」","mis":"M3-1-u6-X18"}],"explanation":["분모가 같으면 분자가 클수록 커요.","⟨2/12⟩ > ⟨1/12⟩이에요.","나래의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 분모가 같은 분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지윤 — 「분모가 같으니 ⟨3/10⟩과 ⟨7/10⟩은 같아」","correct":true,"mis_target":"M3-1-u6-X20"},{"t":"지유 — 「크기가 같은 전체에서 견주어야 해」","mis":"M3-1-u6-X18"},{"t":"하은 — 「⟨7/10⟩이 ⟨3/10⟩보다 커」","mis":"M3-1-u6-X18"}],"explanation":["분모가 같으면 분자가 클수록 커요.","⟨7/10⟩ > ⟨3/10⟩이에요.","지윤의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_challenge#7','math',3,1,'u6','L05','g3_1_math_u6_L05_challenge','lesson_challenge','M3-1-u6-C5',3,'ox','auto','크기가 다른 두 종이에 각각 ⟨8/9⟩만큼 색칠했어요. 두 색칠한 부분의 크기는 꼭 같아요.',ARRAY['M3-1-u6-X11']::text[],true,'{"seq":7,"concept":"M3-1-u6-C5","difficulty":3,"kind":"ox","stem":"크기가 다른 두 종이에 각각 ⟨8/9⟩만큼 색칠했어요. 두 색칠한 부분의 크기는 꼭 같아요.","answer":"X","reason_options":[{"t":"전체 종이의 크기가 달라서","correct":true},{"t":"분수가 ⟨8/9⟩로 같아서","mis":"M3-1-u6-X11"}],"mis":"M3-1-u6-X11","explanation":["분수는 「어떤 전체」를 나눈 것인지가 중요해요.","전체가 크면 ⟨8/9⟩만큼도 커요.","크기가 같은 전체에서만 분수로 견줄 수 있어요 — ×."],"variant_rule":{"alt":[{"stem":"크기가 다른 두 종이에 각각 ⟨5/7⟩만큼 색칠했어요. 두 색칠한 부분의 크기는 꼭 같아요.","answer":"X","reason_options":[{"t":"전체 종이의 크기가 달라서","correct":true},{"t":"분수가 ⟨5/7⟩로 같아서","mis":"M3-1-u6-X11"}],"explanation":["분수는 「어떤 전체」를 나눈 것인지가 중요해요.","전체가 크면 ⟨5/7⟩만큼도 커요.","크기가 같은 전체에서만 분수로 견줄 수 있어요 — ×."],"asset":null},{"stem":"크기가 다른 두 종이에 각각 ⟨7/10⟩만큼 색칠했어요. 두 색칠한 부분의 크기는 꼭 같아요.","answer":"X","reason_options":[{"t":"전체 종이의 크기가 달라서","correct":true},{"t":"분수가 ⟨7/10⟩로 같아서","mis":"M3-1-u6-X11"}],"explanation":["분수는 「어떤 전체」를 나눈 것인지가 중요해요.","전체가 크면 ⟨7/10⟩만큼도 커요.","크기가 같은 전체에서만 분수로 견줄 수 있어요 — ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_challenge#8','math',3,1,'u6','L05','g3_1_math_u6_L05_challenge','lesson_challenge','M3-1-u6-C5',4,'essay','teacher','초콜릿을 지유는 ⟨3/8⟩, 도윤이는 ⟨5/8⟩만큼 먹었어요. 누가 더 많이 먹었는지 두 가지 방법으로 설명해 보세요. (초콜릿의 크기는 같아요.)','{}'::text[],false,'{"seq":8,"concept":"M3-1-u6-C5","difficulty":4,"kind":"essay","stem":"초콜릿을 지유는 ⟨3/8⟩, 도윤이는 ⟨5/8⟩만큼 먹었어요. 누가 더 많이 먹었는지 두 가지 방법으로 설명해 보세요. (초콜릿의 크기는 같아요.)","answer_guide":{"answer":"예: ① 단위분수 개수로 — ⟨3/8⟩은 ⟨1/8⟩이 3개, ⟨5/8⟩는 5개이므로 ⟨5/8⟩가 더 크다. ② 띠 그림으로 — 같은 길이 띠를 8칸으로 나누어 3칸과 5칸을 색칠하면 5칸이 더 길다. 그래서 도윤이가 더 많이 먹었다.","scoring_points":["도윤이가 더 많이 먹었다고 답했는가","단위분수 개수(분자)로 견주었는가","띠 그림 등 다른 방법으로도 설명했는가"]},"explanation":["분모가 8로 같아요.","분자 3 < 5.","도윤이가 더 많이 먹었어요."],"asset":{"type":"fbar","bars":[{"den":8,"num":3},{"den":8,"num":5}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_challenge#9','math',3,1,'u6','L05','g3_1_math_u6_L05_challenge','lesson_challenge','M3-1-u6-C5',4,'essay','teacher','크기가 다른 두 종이에 각각 ⟨3/4⟩만큼 색칠했어요. 「두 색칠한 부분은 크기가 꼭 같다」고 할 수 있는지 판단하고 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u6-C5","difficulty":4,"kind":"essay","stem":"크기가 다른 두 종이에 각각 ⟨3/4⟩만큼 색칠했어요. 「두 색칠한 부분은 크기가 꼭 같다」고 할 수 있는지 판단하고 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 할 수 없다. 분수는 전체를 똑같이 나눈 것 중의 몇이므로 전체의 크기에 따라 부분의 크기도 달라진다. 큰 종이의 ⟨3/4⟩이 작은 종이의 ⟨3/4⟩보다 크다. 분수의 크기 비교는 크기가 같은 전체에서 해야 한다.","scoring_points":["같다고 할 수 없다고 판단했는가","전체의 크기가 다르면 부분도 다르다고 썼는가","크기가 같은 전체에서 비교해야 한다고 썼는가"]},"explanation":["분수는 어떤 전체인지가 중요해요.","전체가 다르면 부분도 달라요.","꼭 같다고 할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L05_challenge#10','math',3,1,'u6','L05','g3_1_math_u6_L05_challenge','lesson_challenge','M3-1-u6-C5',4,'sa','auto','⟨□/6⟩는 ⟨1/6⟩보다 크고 ⟨4/6⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u6-C5","difficulty":4,"kind":"sa","stem":"⟨□/6⟩는 ⟨1/6⟩보다 크고 ⟨4/6⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모가 같으니 분자만 견주어요.","□는 1보다 크고 4보다 작은 수 — 2, 3.","모두 2개예요."],"variant_rule":{"alt":[{"stem":"⟨□/8⟩는 ⟨2/8⟩보다 크고 ⟨4/8⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["분모가 같으니 분자만 견주어요.","□는 2보다 크고 4보다 작은 수 — 3.","모두 1개예요."],"asset":null},{"stem":"⟨□/8⟩는 ⟨2/8⟩보다 크고 ⟨5/8⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모가 같으니 분자만 견주어요.","□는 2보다 크고 5보다 작은 수 — 3, 4.","모두 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_basic#1','math',3,1,'u6','L06','g3_1_math_u6_L06_basic','lesson_basic','M3-1-u6-C6',1,'mc','auto','⟨1/2⟩과 ⟨1/5⟩ 중 더 큰 수는 무엇인가요?',ARRAY['M3-1-u6-X10','M3-1-u6-X20']::text[],true,'{"seq":1,"concept":"M3-1-u6-C6","difficulty":1,"kind":"mc","stem":"⟨1/2⟩과 ⟨1/5⟩ 중 더 큰 수는 무엇인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1/5⟩","mis":"M3-1-u6-X10"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["단위분수는 분자가 1이고 분모만큼 나눈 한 칸이에요.","많이 나눌수록 한 칸이 작아져요 — 분모가 클수록 작은 수예요.","분모 2와 5 — ⟨1/2⟩ > ⟨1/5⟩."],"variant_rule":{"alt":[{"stem":"⟨1/8⟩과 ⟨1/7⟩ 중 더 큰 수는 무엇인가요?","options":[{"t":"⟨1/7⟩","correct":true},{"t":"⟨1/8⟩","mis":"M3-1-u6-X10"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["단위분수는 분자가 1이고 분모만큼 나눈 한 칸이에요.","많이 나눌수록 한 칸이 작아져요 — 분모가 클수록 작은 수예요.","분모 8과 7 — ⟨1/8⟩ < ⟨1/7⟩."],"asset":null},{"stem":"⟨1/4⟩과 ⟨1/5⟩ 중 더 큰 수는 무엇인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨1/5⟩","mis":"M3-1-u6-X10"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["단위분수는 분자가 1이고 분모만큼 나눈 한 칸이에요.","많이 나눌수록 한 칸이 작아져요 — 분모가 클수록 작은 수예요.","분모 4와 5 — ⟨1/4⟩ > ⟨1/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
