INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_basic#6','math',3,1,'u6','L06','g3_1_math_u6_L06_basic','lesson_basic','M3-1-u6-C6',2,'mc','auto','가장 큰 수는 무엇인가요? ⟨1/9⟩, ⟨1/10⟩, ⟨1/6⟩, ⟨1/7⟩',ARRAY['M3-1-u6-X10','M3-1-u6-X18']::text[],true,'{"seq":6,"concept":"M3-1-u6-C6","difficulty":2,"kind":"mc","stem":"가장 큰 수는 무엇인가요? ⟨1/9⟩, ⟨1/10⟩, ⟨1/6⟩, ⟨1/7⟩","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨1/9⟩","mis":"M3-1-u6-X10"},{"t":"⟨1/10⟩","mis":"M3-1-u6-X18"},{"t":"⟨1/7⟩","mis":"M3-1-u6-X10"}],"explanation":["모두 단위분수예요.","분모가 작을수록 큰 수예요 — 분모 9, 10, 6, 7.","가장 큰 수는 ⟨1/6⟩이에요."],"variant_rule":{"alt":[{"stem":"가장 큰 수는 무엇인가요? ⟨1/4⟩, ⟨1/5⟩, ⟨1/2⟩, ⟨1/9⟩","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1/4⟩","mis":"M3-1-u6-X10"},{"t":"⟨1/5⟩","mis":"M3-1-u6-X10"},{"t":"⟨1/9⟩","mis":"M3-1-u6-X18"}],"explanation":["모두 단위분수예요.","분모가 작을수록 큰 수예요 — 분모 4, 5, 2, 9.","가장 큰 수는 ⟨1/2⟩이에요."],"asset":null},{"stem":"가장 큰 수는 무엇인가요? ⟨1/4⟩, ⟨1/2⟩, ⟨1/10⟩, ⟨1/8⟩","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1/4⟩","mis":"M3-1-u6-X10"},{"t":"⟨1/10⟩","mis":"M3-1-u6-X18"},{"t":"⟨1/8⟩","mis":"M3-1-u6-X10"}],"explanation":["모두 단위분수예요.","분모가 작을수록 큰 수예요 — 분모 4, 2, 10, 8.","가장 큰 수는 ⟨1/2⟩이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_basic#7','math',3,1,'u6','L06','g3_1_math_u6_L06_basic','lesson_basic','M3-1-u6-C6',2,'ox','auto','유나가 「3이 2보다 크니까 ⟨1/3⟩이 ⟨1/2⟩보다 커.」라고 했어요. 바르게 말했어요.',ARRAY['M3-1-u6-X10']::text[],true,'{"seq":7,"concept":"M3-1-u6-C6","difficulty":2,"kind":"ox","stem":"유나가 「3이 2보다 크니까 ⟨1/3⟩이 ⟨1/2⟩보다 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"많이 나눌수록 한 칸이 작아져서","correct":true},{"t":"분모가 큰 수가 늘 더 커서","mis":"M3-1-u6-X10"}],"mis":"M3-1-u6-X10","explanation":["⟨1/3⟩은 전체를 3칸, ⟨1/2⟩은 2칸으로 나눈 한 칸이에요.","3칸으로 나눈 한 칸이 더 작아요.","⟨1/3⟩ < ⟨1/2⟩ — 틀렸어요(×)."],"asset":{"type":"fbar","bars":[{"den":2,"num":1},{"den":3,"num":1}]},"variant_rule":{"alt":[{"stem":"지윤이 「8이 4보다 크니까 ⟨1/8⟩이 ⟨1/4⟩보다 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"많이 나눌수록 한 칸이 작아져서","correct":true},{"t":"분모가 큰 수가 늘 더 커서","mis":"M3-1-u6-X10"}],"explanation":["⟨1/8⟩은 전체를 8칸, ⟨1/4⟩은 4칸으로 나눈 한 칸이에요.","8칸으로 나눈 한 칸이 더 작아요.","⟨1/8⟩ < ⟨1/4⟩ — 틀렸어요(×)."],"asset":{"type":"fbar","bars":[{"den":4,"num":1},{"den":8,"num":1}]}},{"stem":"유나가 「8이 5보다 크니까 ⟨1/8⟩이 ⟨1/5⟩보다 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"많이 나눌수록 한 칸이 작아져서","correct":true},{"t":"분모가 큰 수가 늘 더 커서","mis":"M3-1-u6-X10"}],"explanation":["⟨1/8⟩은 전체를 8칸, ⟨1/5⟩은 5칸으로 나눈 한 칸이에요.","8칸으로 나눈 한 칸이 더 작아요.","⟨1/8⟩ < ⟨1/5⟩ — 틀렸어요(×)."],"asset":{"type":"fbar","bars":[{"den":5,"num":1},{"den":8,"num":1}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_basic#8','math',3,1,'u6','L06','g3_1_math_u6_L06_basic','lesson_basic','M3-1-u6-C6',2,'mc','auto','크기가 같은 피자를 민서네 모둠은 4명이, 서준네 모둠은 8명이 똑같이 나누어 먹었어요. 한 사람이 먹은 조각이 더 큰 모둠은 누구네인가요?',ARRAY['M3-1-u6-X10','M3-1-u6-X20']::text[],true,'{"seq":8,"concept":"M3-1-u6-C6","difficulty":2,"kind":"mc","stem":"크기가 같은 피자를 민서네 모둠은 4명이, 서준네 모둠은 8명이 똑같이 나누어 먹었어요. 한 사람이 먹은 조각이 더 큰 모둠은 누구네인가요?","options":[{"t":"민서네","correct":true},{"t":"서준네","mis":"M3-1-u6-X10"},{"t":"두 모둠이 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["4명이 나누면 한 사람이 ⟨1/4⟩, 8명이 나누면 ⟨1/8⟩씩 먹어요.","나누는 사람이 적을수록 한 조각이 커요.","⟨1/4⟩ > ⟨1/8⟩ — 민서네 조각이 커요."],"variant_rule":{"alt":[{"stem":"크기가 같은 피자를 민서네 모둠은 8명이, 지유네 모둠은 9명이 똑같이 나누어 먹었어요. 한 사람이 먹은 조각이 더 큰 모둠은 누구네인가요?","options":[{"t":"민서네","correct":true},{"t":"지유네","mis":"M3-1-u6-X10"},{"t":"두 모둠이 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["8명이 나누면 한 사람이 ⟨1/8⟩, 9명이 나누면 ⟨1/9⟩씩 먹어요.","나누는 사람이 적을수록 한 조각이 커요.","⟨1/8⟩ > ⟨1/9⟩ — 민서네 조각이 커요."],"asset":null},{"stem":"크기가 같은 피자를 나래네 모둠은 6명이, 도윤네 모둠은 5명이 똑같이 나누어 먹었어요. 한 사람이 먹은 조각이 더 큰 모둠은 누구네인가요?","options":[{"t":"도윤네","correct":true},{"t":"나래네","mis":"M3-1-u6-X10"},{"t":"두 모둠이 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["6명이 나누면 한 사람이 ⟨1/6⟩, 5명이 나누면 ⟨1/5⟩씩 먹어요.","나누는 사람이 적을수록 한 조각이 커요.","⟨1/5⟩ > ⟨1/6⟩ — 도윤네 조각이 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_basic#9','math',3,1,'u6','L06','g3_1_math_u6_L06_basic','lesson_basic','M3-1-u6-C6',2,'error','auto','단위분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u6-X10','M3-1-u6-X18']::text[],true,'{"seq":9,"concept":"M3-1-u6-C6","difficulty":2,"kind":"error","stem":"단위분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나래 — 「⟨1/6⟩이 ⟨1/2⟩보다 커」","correct":true,"mis_target":"M3-1-u6-X10"},{"t":"도윤 — 「분모가 작을수록 한 칸이 커」","mis":"M3-1-u6-X18"},{"t":"민서 — 「많이 나눌수록 한 칸이 작아져」","mis":"M3-1-u6-X18"}],"explanation":["단위분수는 분모가 클수록 작아요.","⟨1/2⟩ > ⟨1/6⟩이에요.","나래의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 단위분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「분자가 모두 1이니 단위분수는 크기가 같아」","correct":true,"mis_target":"M3-1-u6-X20"},{"t":"유나 — 「많이 나눌수록 한 칸이 작아져」","mis":"M3-1-u6-X18"},{"t":"현우 — 「⟨1/5⟩이 ⟨1/8⟩보다 커」","mis":"M3-1-u6-X18"}],"explanation":["단위분수는 분모가 클수록 작아요.","⟨1/5⟩ > ⟨1/8⟩이에요.","도윤의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 단위분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지윤 — 「분모가 클수록 단위분수가 커」","correct":true,"mis_target":"M3-1-u6-X10"},{"t":"나래 — 「⟨1/2⟩이 ⟨1/3⟩보다 커」","mis":"M3-1-u6-X18"},{"t":"지유 — 「분모가 작을수록 한 칸이 커」","mis":"M3-1-u6-X18"}],"explanation":["단위분수는 분모가 클수록 작아요.","⟨1/2⟩ > ⟨1/3⟩이에요.","지윤의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_basic#10','math',3,1,'u6','L06','g3_1_math_u6_L06_basic','lesson_basic','M3-1-u6-C6',3,'sa','auto','⟨1/□⟩ > ⟨1/5⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u6-C6","difficulty":3,"kind":"sa","stem":"⟨1/□⟩ > ⟨1/5⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 5보다 작고 1보다 큰 수 — 2, 3, 4.","모두 3개예요."],"variant_rule":{"alt":[{"stem":"⟨1/□⟩ > ⟨1/8⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 8보다 작고 1보다 큰 수 — 2, 3, 4, 5, 6, 7.","모두 6개예요."],"asset":null},{"stem":"⟨1/□⟩ > ⟨1/4⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 4보다 작고 1보다 큰 수 — 2, 3.","모두 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_challenge#1','math',3,1,'u6','L06','g3_1_math_u6_L06_challenge','lesson_challenge','M3-1-u6-C6',2,'mc','auto','두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. ⟨1/11⟩ ○ ⟨1/4⟩',ARRAY['M3-1-u6-X10','M3-1-u6-X20']::text[],true,'{"seq":1,"concept":"M3-1-u6-C6","difficulty":2,"kind":"mc","stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. ⟨1/11⟩ ○ ⟨1/4⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u6-X10"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["단위분수는 분자가 1이고 분모만큼 나눈 한 칸이에요.","많이 나눌수록 한 칸이 작아져요 — 분모가 클수록 작은 수예요.","분모 11과 4 — ⟨1/11⟩ < ⟨1/4⟩."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. ⟨1/4⟩ ○ ⟨1/6⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u6-X10"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["단위분수는 분자가 1이고 분모만큼 나눈 한 칸이에요.","많이 나눌수록 한 칸이 작아져요 — 분모가 클수록 작은 수예요.","분모 4와 6 — ⟨1/4⟩ > ⟨1/6⟩."],"asset":null},{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. ⟨1/6⟩ ○ ⟨1/8⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u6-X10"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["단위분수는 분자가 1이고 분모만큼 나눈 한 칸이에요.","많이 나눌수록 한 칸이 작아져요 — 분모가 클수록 작은 수예요.","분모 6과 8 — ⟨1/6⟩ > ⟨1/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_challenge#2','math',3,1,'u6','L06','g3_1_math_u6_L06_challenge','lesson_challenge','M3-1-u6-C6',2,'mc','auto','크기가 같은 피자를 나래네 모둠은 5명이, 지유네 모둠은 3명이 똑같이 나누어 먹었어요. 한 사람이 먹은 조각이 더 큰 모둠은 누구네인가요?',ARRAY['M3-1-u6-X10','M3-1-u6-X20']::text[],true,'{"seq":2,"concept":"M3-1-u6-C6","difficulty":2,"kind":"mc","stem":"크기가 같은 피자를 나래네 모둠은 5명이, 지유네 모둠은 3명이 똑같이 나누어 먹었어요. 한 사람이 먹은 조각이 더 큰 모둠은 누구네인가요?","options":[{"t":"지유네","correct":true},{"t":"나래네","mis":"M3-1-u6-X10"},{"t":"두 모둠이 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["5명이 나누면 한 사람이 ⟨1/5⟩, 3명이 나누면 ⟨1/3⟩씩 먹어요.","나누는 사람이 적을수록 한 조각이 커요.","⟨1/3⟩ > ⟨1/5⟩ — 지유네 조각이 커요."],"variant_rule":{"alt":[{"stem":"크기가 같은 피자를 지윤네 모둠은 8명이, 지유네 모둠은 10명이 똑같이 나누어 먹었어요. 한 사람이 먹은 조각이 더 큰 모둠은 누구네인가요?","options":[{"t":"지윤네","correct":true},{"t":"지유네","mis":"M3-1-u6-X10"},{"t":"두 모둠이 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["8명이 나누면 한 사람이 ⟨1/8⟩, 10명이 나누면 ⟨1/10⟩씩 먹어요.","나누는 사람이 적을수록 한 조각이 커요.","⟨1/8⟩ > ⟨1/10⟩ — 지윤네 조각이 커요."],"asset":null},{"stem":"크기가 같은 피자를 도윤네 모둠은 10명이, 나래네 모둠은 6명이 똑같이 나누어 먹었어요. 한 사람이 먹은 조각이 더 큰 모둠은 누구네인가요?","options":[{"t":"나래네","correct":true},{"t":"도윤네","mis":"M3-1-u6-X10"},{"t":"두 모둠이 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["10명이 나누면 한 사람이 ⟨1/10⟩, 6명이 나누면 ⟨1/6⟩씩 먹어요.","나누는 사람이 적을수록 한 조각이 커요.","⟨1/6⟩ > ⟨1/10⟩ — 나래네 조각이 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_challenge#3','math',3,1,'u6','L06','g3_1_math_u6_L06_challenge','lesson_challenge','M3-1-u6-C6',3,'mc','auto','가장 작은 수는 무엇인가요? ⟨1/10⟩, ⟨1/9⟩, ⟨1/6⟩, ⟨1/3⟩',ARRAY['M3-1-u6-X10','M3-1-u6-X18']::text[],true,'{"seq":3,"concept":"M3-1-u6-C6","difficulty":3,"kind":"mc","stem":"가장 작은 수는 무엇인가요? ⟨1/10⟩, ⟨1/9⟩, ⟨1/6⟩, ⟨1/3⟩","options":[{"t":"⟨1/10⟩","correct":true},{"t":"⟨1/9⟩","mis":"M3-1-u6-X10"},{"t":"⟨1/6⟩","mis":"M3-1-u6-X10"},{"t":"⟨1/3⟩","mis":"M3-1-u6-X18"}],"explanation":["모두 단위분수예요.","분모가 작을수록 큰 수예요 — 분모 10, 9, 6, 3.","가장 작은 수는 ⟨1/10⟩이에요."],"variant_rule":{"alt":[{"stem":"가장 작은 수는 무엇인가요? ⟨1/10⟩, ⟨1/4⟩, ⟨1/2⟩, ⟨1/9⟩","options":[{"t":"⟨1/10⟩","correct":true},{"t":"⟨1/4⟩","mis":"M3-1-u6-X10"},{"t":"⟨1/2⟩","mis":"M3-1-u6-X18"},{"t":"⟨1/9⟩","mis":"M3-1-u6-X10"}],"explanation":["모두 단위분수예요.","분모가 작을수록 큰 수예요 — 분모 10, 4, 2, 9.","가장 작은 수는 ⟨1/10⟩이에요."],"asset":null},{"stem":"가장 작은 수는 무엇인가요? ⟨1/2⟩, ⟨1/7⟩, ⟨1/4⟩, ⟨1/8⟩","options":[{"t":"⟨1/8⟩","correct":true},{"t":"⟨1/2⟩","mis":"M3-1-u6-X18"},{"t":"⟨1/7⟩","mis":"M3-1-u6-X10"},{"t":"⟨1/4⟩","mis":"M3-1-u6-X10"}],"explanation":["모두 단위분수예요.","분모가 작을수록 큰 수예요 — 분모 2, 7, 4, 8.","가장 작은 수는 ⟨1/8⟩이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_challenge#4','math',3,1,'u6','L06','g3_1_math_u6_L06_challenge','lesson_challenge','M3-1-u6-C6',3,'sa','auto','⟨1/□⟩ > ⟨1/6⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u6-C6","difficulty":3,"kind":"sa","stem":"⟨1/□⟩ > ⟨1/6⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 6보다 작고 1보다 큰 수 — 2, 3, 4, 5.","모두 4개예요."],"variant_rule":{"alt":[{"stem":"⟨1/□⟩ > ⟨1/7⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 7보다 작고 1보다 큰 수 — 2, 3, 4, 5, 6.","모두 5개예요."],"asset":null},{"stem":"⟨1/□⟩ > ⟨1/8⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 8보다 작고 1보다 큰 수 — 2, 3, 4, 5, 6, 7.","모두 6개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_challenge#5','math',3,1,'u6','L06','g3_1_math_u6_L06_challenge','lesson_challenge','M3-1-u6-C6',3,'error','auto','단위분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u6-X10','M3-1-u6-X18']::text[],true,'{"seq":5,"concept":"M3-1-u6-C6","difficulty":3,"kind":"error","stem":"단위분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「분모가 클수록 단위분수가 커」","correct":true,"mis_target":"M3-1-u6-X10"},{"t":"지윤 — 「⟨1/8⟩이 ⟨1/9⟩보다 커」","mis":"M3-1-u6-X18"},{"t":"하은 — 「분모가 작을수록 한 칸이 커」","mis":"M3-1-u6-X18"}],"explanation":["단위분수는 분모가 클수록 작아요.","⟨1/8⟩ > ⟨1/9⟩이에요.","현우의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 단위분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「⟨1/8⟩이 ⟨1/6⟩보다 커」","correct":true,"mis_target":"M3-1-u6-X10"},{"t":"하은 — 「분모가 작을수록 한 칸이 커」","mis":"M3-1-u6-X18"},{"t":"나래 — 「많이 나눌수록 한 칸이 작아져」","mis":"M3-1-u6-X18"}],"explanation":["단위분수는 분모가 클수록 작아요.","⟨1/6⟩ > ⟨1/8⟩이에요.","현우의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 단위분수의 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하은 — 「분자가 모두 1이니 단위분수는 크기가 같아」","correct":true,"mis_target":"M3-1-u6-X20"},{"t":"태오 — 「많이 나눌수록 한 칸이 작아져」","mis":"M3-1-u6-X18"},{"t":"나래 — 「⟨1/7⟩이 ⟨1/9⟩보다 커」","mis":"M3-1-u6-X18"}],"explanation":["단위분수는 분모가 클수록 작아요.","⟨1/7⟩ > ⟨1/9⟩이에요.","하은의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_challenge#6','math',3,1,'u6','L06','g3_1_math_u6_L06_challenge','lesson_challenge','M3-1-u6-C6',3,'ox','auto','도윤이 「12가 11보다 크니까 ⟨1/12⟩이 ⟨1/11⟩보다 커.」라고 했어요. 바르게 말했어요.',ARRAY['M3-1-u6-X10']::text[],true,'{"seq":6,"concept":"M3-1-u6-C6","difficulty":3,"kind":"ox","stem":"도윤이 「12가 11보다 크니까 ⟨1/12⟩이 ⟨1/11⟩보다 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"많이 나눌수록 한 칸이 작아져서","correct":true},{"t":"분모가 큰 수가 늘 더 커서","mis":"M3-1-u6-X10"}],"mis":"M3-1-u6-X10","explanation":["⟨1/12⟩은 전체를 12칸, ⟨1/11⟩은 11칸으로 나눈 한 칸이에요.","12칸으로 나눈 한 칸이 더 작아요.","⟨1/12⟩ < ⟨1/11⟩ — 틀렸어요(×)."],"asset":{"type":"fbar","bars":[{"den":11,"num":1},{"den":12,"num":1}]},"variant_rule":{"alt":[{"stem":"태오가 「12가 6보다 크니까 ⟨1/12⟩이 ⟨1/6⟩보다 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"많이 나눌수록 한 칸이 작아져서","correct":true},{"t":"분모가 큰 수가 늘 더 커서","mis":"M3-1-u6-X10"}],"explanation":["⟨1/12⟩은 전체를 12칸, ⟨1/6⟩은 6칸으로 나눈 한 칸이에요.","12칸으로 나눈 한 칸이 더 작아요.","⟨1/12⟩ < ⟨1/6⟩ — 틀렸어요(×)."],"asset":{"type":"fbar","bars":[{"den":6,"num":1},{"den":12,"num":1}]}},{"stem":"현우가 「10이 6보다 크니까 ⟨1/10⟩이 ⟨1/6⟩보다 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"많이 나눌수록 한 칸이 작아져서","correct":true},{"t":"분모가 큰 수가 늘 더 커서","mis":"M3-1-u6-X10"}],"explanation":["⟨1/10⟩은 전체를 10칸, ⟨1/6⟩은 6칸으로 나눈 한 칸이에요.","10칸으로 나눈 한 칸이 더 작아요.","⟨1/10⟩ < ⟨1/6⟩ — 틀렸어요(×)."],"asset":{"type":"fbar","bars":[{"den":6,"num":1},{"den":10,"num":1}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_challenge#7','math',3,1,'u6','L06','g3_1_math_u6_L06_challenge','lesson_challenge','M3-1-u6-C6',3,'sa','auto','⟨1/9⟩ < ⟨1/□⟩ < ⟨1/6⟩ — □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u6-C6","difficulty":3,"kind":"sa","stem":"⟨1/9⟩ < ⟨1/□⟩ < ⟨1/6⟩ — □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["단위분수는 분모가 클수록 작아요.","□는 6보다 크고 9보다 작은 수 — 7, 8.","모두 2개예요."],"variant_rule":{"alt":[{"stem":"⟨1/9⟩ < ⟨1/□⟩ < ⟨1/5⟩ — □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["단위분수는 분모가 클수록 작아요.","□는 5보다 크고 9보다 작은 수 — 6, 7, 8.","모두 3개예요."],"asset":null},{"stem":"⟨1/7⟩ < ⟨1/□⟩ < ⟨1/4⟩ — □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["단위분수는 분모가 클수록 작아요.","□는 4보다 크고 7보다 작은 수 — 5, 6.","모두 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_challenge#8','math',3,1,'u6','L06','g3_1_math_u6_L06_challenge','lesson_challenge','M3-1-u6-C6',4,'essay','teacher','지유가 「3이 2보다 크니까 ⟨1/3⟩이 ⟨1/2⟩보다 클 거야.」라고 했어요. 지유의 말이 맞는지 판단하고, 띠 그림을 이용해 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u6-C6","difficulty":4,"kind":"essay","stem":"지유가 「3이 2보다 크니까 ⟨1/3⟩이 ⟨1/2⟩보다 클 거야.」라고 했어요. 지유의 말이 맞는지 판단하고, 띠 그림을 이용해 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 같은 길이의 띠를 둘로 나눈 한 칸(⟨1/2⟩)과 셋으로 나눈 한 칸(⟨1/3⟩)을 견주면 둘로 나눈 한 칸이 더 길다. 많이 나눌수록 한 칸이 작아지므로 ⟨1/2⟩ > ⟨1/3⟩이다.","scoring_points":["틀렸다고 판단했는가","띠 그림으로 한 칸의 크기를 견주었는가","많이 나눌수록 한 칸이 작아진다고 썼는가"]},"explanation":["분모가 크면 많이 나눈 거예요.","많이 나눌수록 한 칸이 작아요.","⟨1/2⟩ > ⟨1/3⟩."],"asset":{"type":"fbar","bars":[{"den":2,"num":1},{"den":3,"num":1}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_challenge#9','math',3,1,'u6','L06','g3_1_math_u6_L06_challenge','lesson_challenge','M3-1-u6-C6',4,'essay','teacher','크기가 같은 피자를 한 모둠은 3명이, 다른 모둠은 5명이 똑같이 나누어 먹었어요. 어느 모둠 친구가 한 조각을 더 많이 먹었는지 분수를 써서 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u6-C6","difficulty":4,"kind":"essay","stem":"크기가 같은 피자를 한 모둠은 3명이, 다른 모둠은 5명이 똑같이 나누어 먹었어요. 어느 모둠 친구가 한 조각을 더 많이 먹었는지 분수를 써서 설명해 보세요.","answer_guide":{"answer":"예: 3명 모둠은 한 사람이 ⟨1/3⟩씩, 5명 모둠은 ⟨1/5⟩씩 먹는다. 단위분수는 분모가 작을수록 크므로 ⟨1/3⟩ > ⟨1/5⟩이다. 그래서 3명 모둠 친구가 한 조각을 더 많이 먹었다.","scoring_points":["한 사람 몫을 ⟨1/3⟩, ⟨1/5⟩로 나타냈는가","분모가 작을수록 크다는 것으로 견주었는가","3명 모둠이 더 많이 먹었다고 답했는가"]},"explanation":["3명 → ⟨1/3⟩, 5명 → ⟨1/5⟩.","분모가 작을수록 커요.","3명 모둠 친구가 더 많이 먹어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L06_challenge#10','math',3,1,'u6','L06','g3_1_math_u6_L06_challenge','lesson_challenge','M3-1-u6-C6',4,'sa','auto','⟨1/9⟩ < ⟨1/□⟩ < ⟨1/4⟩ — □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u6-C6","difficulty":4,"kind":"sa","stem":"⟨1/9⟩ < ⟨1/□⟩ < ⟨1/4⟩ — □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["단위분수는 분모가 클수록 작아요.","□는 4보다 크고 9보다 작은 수 — 5, 6, 7, 8.","모두 4개예요."],"variant_rule":{"alt":[{"stem":"⟨1/10⟩ < ⟨1/□⟩ < ⟨1/5⟩ — □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["단위분수는 분모가 클수록 작아요.","□는 5보다 크고 10보다 작은 수 — 6, 7, 8, 9.","모두 4개예요."],"asset":null},{"stem":"⟨1/10⟩ < ⟨1/□⟩ < ⟨1/4⟩ — □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["단위분수는 분모가 클수록 작아요.","□는 4보다 크고 10보다 작은 수 — 5, 6, 7, 8, 9.","모두 5개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_basic#1','math',3,1,'u6','L07','g3_1_math_u6_L07_basic','lesson_basic','M3-1-u6-C7',1,'mc','auto','띠를 똑같이 열 칸으로 나누어 색칠했어요. 색칠한 부분을 분수로 나타내면 무엇인가요?',ARRAY['M3-1-u6-X02','M3-1-u6-X04','M3-1-u6-X03']::text[],true,'{"seq":1,"concept":"M3-1-u6-C7","difficulty":1,"kind":"mc","stem":"띠를 똑같이 열 칸으로 나누어 색칠했어요. 색칠한 부분을 분수로 나타내면 무엇인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"⟨10/3⟩","mis":"M3-1-u6-X02"},{"t":"⟨7/10⟩","mis":"M3-1-u6-X04"},{"t":"⟨3/7⟩","mis":"M3-1-u6-X03"}],"explanation":["띠를 똑같이 10칸으로 나누었어요 — 분모 10.","그중 3칸을 색칠했어요.","색칠한 부분은 ⟨3/10⟩이에요."],"asset":{"type":"fbar","bars":[{"den":10,"num":3}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 띠를 똑같이 열 칸으로 나누어 색칠했어요. 색칠한 부분을 분수로 나타내면 무엇인가요?","options":[{"t":"⟨8/10⟩","correct":true},{"t":"⟨10/8⟩","mis":"M3-1-u6-X02"},{"t":"⟨2/10⟩","mis":"M3-1-u6-X04"},{"t":"⟨8/2⟩","mis":"M3-1-u6-X03"}],"explanation":["띠를 똑같이 10칸으로 나누었어요 — 분모 10.","그중 8칸을 색칠했어요.","색칠한 부분은 ⟨8/10⟩이에요."],"asset":{"type":"fbar","bars":[{"den":10,"num":8}]}},{"stem":"이번에는 다른 문제예요. 띠를 똑같이 열 칸으로 나누어 색칠했어요. 색칠한 부분을 분수로 나타내면 무엇인가요?","options":[{"t":"⟨2/10⟩","correct":true},{"t":"⟨10/2⟩","mis":"M3-1-u6-X02"},{"t":"⟨8/10⟩","mis":"M3-1-u6-X04"},{"t":"⟨2/8⟩","mis":"M3-1-u6-X03"}],"explanation":["띠를 똑같이 10칸으로 나누었어요 — 분모 10.","그중 2칸을 색칠했어요.","색칠한 부분은 ⟨2/10⟩예요."],"asset":{"type":"fbar","bars":[{"den":10,"num":2}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_basic#2','math',3,1,'u6','L07','g3_1_math_u6_L07_basic','lesson_basic','M3-1-u6-C7',1,'sa','auto','⟨7/10⟩은 ⟨1/10⟩이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u6-C7","difficulty":1,"kind":"sa","stem":"⟨7/10⟩은 ⟨1/10⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["⟨1/10⟩은 전체를 똑같이 열로 나눈 한 칸이에요.","⟨7/10⟩은 그 한 칸이 7개예요.","7개예요."],"variant_rule":{"alt":[{"stem":"⟨4/10⟩는 ⟨1/10⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨1/10⟩은 전체를 똑같이 열로 나눈 한 칸이에요.","⟨4/10⟩는 그 한 칸이 4개예요.","4개예요."],"asset":null},{"stem":"⟨5/10⟩는 ⟨1/10⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨1/10⟩은 전체를 똑같이 열로 나눈 한 칸이에요.","⟨5/10⟩는 그 한 칸이 5개예요.","5개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_basic#3','math',3,1,'u6','L07','g3_1_math_u6_L07_basic','lesson_basic','M3-1-u6-C7',1,'mc','auto','⟨1/10⟩이 10개 모이면 얼마인가요?',ARRAY['M3-1-u6-X12','M3-1-u6-X05']::text[],true,'{"seq":3,"concept":"M3-1-u6-C7","difficulty":1,"kind":"mc","stem":"⟨1/10⟩이 10개 모이면 얼마인가요?","options":[{"t":"1","correct":true},{"t":"10","mis":"M3-1-u6-X12"},{"t":"100","mis":"M3-1-u6-X12"},{"t":"⟨1/10⟩","mis":"M3-1-u6-X05"}],"explanation":["⟨1/10⟩은 1을 열로 나눈 한 칸이에요.","한 칸이 10개 모이면 처음 1이 돼요.","⟨1/10⟩이 10개면 1이에요."],"variant_rule":{"alt":[{"stem":"1이 10개 모이면 얼마인가요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M3-1-u6-X19"},{"t":"100","mis":"M3-1-u6-X12"},{"t":"⟨1/10⟩","mis":"M3-1-u6-X12"}],"explanation":["10개가 모이면 다음 자리가 돼요.","1이 10개면 10이에요.","10이에요."],"asset":null},{"stem":"10이 10개 모이면 얼마인가요?","options":[{"t":"100","correct":true},{"t":"10","mis":"M3-1-u6-X19"},{"t":"1000","mis":"M3-1-u6-X12"},{"t":"20","mis":"M3-1-u6-X19"}],"explanation":["10개가 모이면 다음 자리가 돼요.","10이 10개면 100이에요.","100이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_basic#4','math',3,1,'u6','L07','g3_1_math_u6_L07_basic','lesson_basic','M3-1-u6-C7',1,'mc','auto','전체를 똑같이 열로 나눈 것 중 일곱을 분수로 나타내면 무엇인가요?',ARRAY['M3-1-u6-X02','M3-1-u6-X05','M3-1-u6-X03']::text[],true,'{"seq":4,"concept":"M3-1-u6-C7","difficulty":1,"kind":"mc","stem":"전체를 똑같이 열로 나눈 것 중 일곱을 분수로 나타내면 무엇인가요?","options":[{"t":"⟨7/10⟩","correct":true},{"t":"⟨10/7⟩","mis":"M3-1-u6-X02"},{"t":"⟨1/7⟩","mis":"M3-1-u6-X05"},{"t":"⟨7/3⟩","mis":"M3-1-u6-X03"}],"explanation":["똑같이 열로 나누었으니 분모는 10이에요.","그중 일곱 — 분자는 7.","⟨7/10⟩이에요."],"variant_rule":{"alt":[{"stem":"전체를 똑같이 열로 나눈 것 중 아홉을 분수로 나타내면 무엇인가요?","options":[{"t":"⟨9/10⟩","correct":true},{"t":"⟨10/9⟩","mis":"M3-1-u6-X02"},{"t":"⟨1/9⟩","mis":"M3-1-u6-X05"},{"t":"⟨1/10⟩","mis":"M3-1-u6-X04"}],"explanation":["똑같이 열로 나누었으니 분모는 10이에요.","그중 아홉 — 분자는 9.","⟨9/10⟩예요."],"asset":null},{"stem":"전체를 똑같이 열로 나눈 것 중 여섯을 분수로 나타내면 무엇인가요?","options":[{"t":"⟨6/10⟩","correct":true},{"t":"⟨10/6⟩","mis":"M3-1-u6-X02"},{"t":"⟨1/6⟩","mis":"M3-1-u6-X05"},{"t":"⟨6/4⟩","mis":"M3-1-u6-X03"}],"explanation":["똑같이 열로 나누었으니 분모는 10이에요.","그중 여섯 — 분자는 6.","⟨6/10⟩이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_basic#5','math',3,1,'u6','L07','g3_1_math_u6_L07_basic','lesson_basic','M3-1-u6-C7',2,'mc','auto','앞의 수가 10개 모이면 다음 수가 되는 규칙이에요. □ 안에 알맞은 수는 무엇인가요? ⟨1/10⟩ → 1 → 10 → □',ARRAY['M3-1-u6-X19','M3-1-u6-X12']::text[],true,'{"seq":5,"concept":"M3-1-u6-C7","difficulty":2,"kind":"mc","stem":"앞의 수가 10개 모이면 다음 수가 되는 규칙이에요. □ 안에 알맞은 수는 무엇인가요? ⟨1/10⟩ → 1 → 10 → □","options":[{"t":"100","correct":true},{"t":"20","mis":"M3-1-u6-X19"},{"t":"11","mis":"M3-1-u6-X19"},{"t":"1000","mis":"M3-1-u6-X12"}],"explanation":["⟨1/10⟩이 10개면 1이에요.","1이 10개면 10, 10이 10개면 100이에요.","□는 100이에요."],"variant_rule":{"alt":[{"stem":"앞의 수가 10개 모이면 다음 수가 되는 규칙이에요. □ 안에 알맞은 수는 무엇인가요? □ → 1 → 10 → 100","options":[{"t":"⟨1/10⟩","correct":true},{"t":"0","mis":"M3-1-u6-X12"},{"t":"1","mis":"M3-1-u6-X19"},{"t":"⟨1/2⟩","mis":"M3-1-u6-X12"}],"explanation":["⟨1/10⟩이 10개면 1이에요.","1이 10개면 10, 10이 10개면 100이에요.","□는 ⟨1/10⟩이에요."],"asset":null},{"stem":"앞의 수가 10개 모이면 다음 수가 되는 규칙이에요. □ 안에 알맞은 수는 무엇인가요? ⟨1/10⟩ → □ → 10 → 100","options":[{"t":"1","correct":true},{"t":"5","mis":"M3-1-u6-X19"},{"t":"⟨9/10⟩","mis":"M3-1-u6-X12"},{"t":"11","mis":"M3-1-u6-X19"}],"explanation":["⟨1/10⟩이 10개면 1이에요.","1이 10개면 10, 10이 10개면 100이에요.","□는 1이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_basic#6','math',3,1,'u6','L07','g3_1_math_u6_L07_basic','lesson_basic','M3-1-u6-C7',2,'ox','auto','지유가 100, 10, 1, ⟨1/10⟩이 각각 1개씩 있는 수를 「1111」이라고 썼어요. 바르게 썼어요.',ARRAY['M3-1-u6-X12']::text[],true,'{"seq":6,"concept":"M3-1-u6-C7","difficulty":2,"kind":"ox","stem":"지유가 100, 10, 1, ⟨1/10⟩이 각각 1개씩 있는 수를 「1111」이라고 썼어요. 바르게 썼어요.","answer":"X","reason_options":[{"t":"1111은 1000이 1개인 수라서 자리가 달라져서","correct":true},{"t":"1이 네 개 있으니 1111이 맞아서","mis":"M3-1-u6-X12"}],"mis":"M3-1-u6-X12","explanation":["1111은 1000, 100, 10, 1이 하나씩인 수예요.","⟨1/10⟩은 1보다 작은 쪽의 수라 그렇게 쓸 수 없어요.","그래서 새로운 표현(소수)이 필요해요 — ×."],"variant_rule":{"alt":[{"stem":"지윤이 「⟨1/10⟩이 10개 모이면 1이야.」라고 했어요. 바르게 말했어요.","answer":"O","reason_options":[{"t":"1을 열로 나눈 한 칸이 10개면 처음 1이라서","correct":true},{"t":"⟨1/10⟩이 10개면 10이라서","mis":"M3-1-u6-X12"}],"explanation":["⟨1/10⟩은 1을 똑같이 열로 나눈 한 칸이에요.","한 칸이 10개 모이면 처음 1이 돼요.","바르게 말했어요 — ○."],"asset":null},{"stem":"도윤이 「⟨1/10⟩이 10개 모이면 100이야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"⟨1/10⟩이 10개면 1이라서","correct":true},{"t":"10개씩 모이면 늘 100이 되어서","mis":"M3-1-u6-X12"}],"explanation":["10개가 모이면 바로 다음 자리가 돼요.","⟨1/10⟩이 10개면 1, 1이 10개면 10, 10이 10개면 100이에요.","100이 아니라 1 — ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_basic#7','math',3,1,'u6','L07','g3_1_math_u6_L07_basic','lesson_basic','M3-1-u6-C7',2,'sa','auto','⟨7/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u6-C7","difficulty":2,"kind":"sa","stem":"⟨7/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨7/10⟩은 ⟨1/10⟩이 7개예요.","10 − 7 = 3개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"⟨1/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["9"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨1/10⟩은 ⟨1/10⟩이 1개예요.","10 − 1 = 9개 더 있어야 해요."],"asset":null},{"stem":"⟨9/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨9/10⟩는 ⟨1/10⟩이 9개예요.","10 − 9 = 1개 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_basic#8','math',3,1,'u6','L07','g3_1_math_u6_L07_basic','lesson_basic','M3-1-u6-C7',2,'error','auto','분모가 10인 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u6-X12','M3-1-u6-X18']::text[],true,'{"seq":8,"concept":"M3-1-u6-C7","difficulty":2,"kind":"error","stem":"분모가 10인 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「⟨1/10⟩이 10개면 10이야」","correct":true,"mis_target":"M3-1-u6-X12"},{"t":"하은 — 「1이 10개면 10이야」","mis":"M3-1-u6-X18"},{"t":"서준 — 「⟨4/10⟩는 ⟨1/10⟩이 4개야」","mis":"M3-1-u6-X18"}],"explanation":["⟨1/10⟩이 10개면 1이에요.","1이 10개면 10, 10이 10개면 100이에요.","지유의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 분모가 10인 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「1이 10개면 100이야」","correct":true,"mis_target":"M3-1-u6-X12"},{"t":"하은 — 「⟨7/10⟩은 ⟨1/10⟩이 7개야」","mis":"M3-1-u6-X18"},{"t":"민서 — 「⟨1/10⟩이 10개면 1이야」","mis":"M3-1-u6-X18"}],"explanation":["⟨1/10⟩이 10개면 1이에요.","1이 10개면 10, 10이 10개면 100이에요.","태오의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 분모가 10인 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「⟨1/10⟩이 10개면 100이야」","correct":true,"mis_target":"M3-1-u6-X12"},{"t":"지유 — 「⟨1/10⟩이 10개면 1이야」","mis":"M3-1-u6-X18"},{"t":"서준 — 「1이 10개면 10이야」","mis":"M3-1-u6-X18"}],"explanation":["⟨1/10⟩이 10개면 1이에요.","1이 10개면 10, 10이 10개면 100이에요.","현우의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_basic#9','math',3,1,'u6','L07','g3_1_math_u6_L07_basic','lesson_basic','M3-1-u6-C7',2,'sa','auto','⟨7/10⟩은 ⟨3/10⟩보다 ⟨1/10⟩이 몇 개 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u6-C7","difficulty":2,"kind":"sa","stem":"⟨7/10⟩은 ⟨3/10⟩보다 ⟨1/10⟩이 몇 개 더 많은가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨7/10⟩은 ⟨1/10⟩이 7개예요.","⟨3/10⟩은 3개예요.","7 − 3 = 4개 더 많아요."],"asset":{"type":"fbar","bars":[{"den":10,"num":7},{"den":10,"num":3}]},"variant_rule":{"alt":[{"stem":"⟨8/10⟩은 ⟨5/10⟩보다 ⟨1/10⟩이 몇 개 더 많은가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨8/10⟩은 ⟨1/10⟩이 8개예요.","⟨5/10⟩는 5개예요.","8 − 5 = 3개 더 많아요."],"asset":{"type":"fbar","bars":[{"den":10,"num":8},{"den":10,"num":5}]}},{"stem":"⟨2/10⟩는 ⟨1/10⟩보다 ⟨1/10⟩이 몇 개 더 많은가요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨2/10⟩는 ⟨1/10⟩이 2개예요.","⟨1/10⟩은 1개예요.","2 − 1 = 1개 더 많아요."],"asset":{"type":"fbar","bars":[{"den":10,"num":2},{"den":10,"num":1}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_basic#10','math',3,1,'u6','L07','g3_1_math_u6_L07_basic','lesson_basic','M3-1-u6-C7',3,'sa','auto','1과 ⟨7/10⟩을 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u6-C7","difficulty":3,"kind":"sa","stem":"1과 ⟨7/10⟩을 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["1은 ⟨1/10⟩이 10개예요.","⟨7/10⟩은 ⟨1/10⟩이 7개예요.","10 + 7 = 17개예요."],"variant_rule":{"alt":[{"stem":"1과 ⟨1/10⟩을 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["1은 ⟨1/10⟩이 10개예요.","⟨1/10⟩은 ⟨1/10⟩이 1개예요.","10 + 1 = 11개예요."],"asset":null},{"stem":"1과 ⟨8/10⟩을 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["1은 ⟨1/10⟩이 10개예요.","⟨8/10⟩은 ⟨1/10⟩이 8개예요.","10 + 8 = 18개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_challenge#1','math',3,1,'u6','L07','g3_1_math_u6_L07_challenge','lesson_challenge','M3-1-u6-C7',2,'mc','auto','앞의 수가 10개 모이면 다음 수가 되는 규칙이에요. □ 안에 알맞은 수는 무엇인가요? □ → 1 → 10 → 100',ARRAY['M3-1-u6-X12','M3-1-u6-X19']::text[],true,'{"seq":1,"concept":"M3-1-u6-C7","difficulty":2,"kind":"mc","stem":"앞의 수가 10개 모이면 다음 수가 되는 규칙이에요. □ 안에 알맞은 수는 무엇인가요? □ → 1 → 10 → 100","options":[{"t":"⟨1/10⟩","correct":true},{"t":"0","mis":"M3-1-u6-X12"},{"t":"1","mis":"M3-1-u6-X19"},{"t":"⟨1/2⟩","mis":"M3-1-u6-X12"}],"explanation":["⟨1/10⟩이 10개면 1이에요.","1이 10개면 10, 10이 10개면 100이에요.","□는 ⟨1/10⟩이에요."],"variant_rule":{"alt":[{"stem":"앞의 수가 10개 모이면 다음 수가 되는 규칙이에요. □ 안에 알맞은 수는 무엇인가요? ⟨1/10⟩ → □ → 10 → 100","options":[{"t":"1","correct":true},{"t":"5","mis":"M3-1-u6-X19"},{"t":"⟨9/10⟩","mis":"M3-1-u6-X12"},{"t":"11","mis":"M3-1-u6-X19"}],"explanation":["⟨1/10⟩이 10개면 1이에요.","1이 10개면 10, 10이 10개면 100이에요.","□는 1이에요."],"asset":null},{"stem":"앞의 수가 10개 모이면 다음 수가 되는 규칙이에요. □ 안에 알맞은 수는 무엇인가요? ⟨1/10⟩ → 1 → 10 → □","options":[{"t":"100","correct":true},{"t":"20","mis":"M3-1-u6-X19"},{"t":"11","mis":"M3-1-u6-X19"},{"t":"1000","mis":"M3-1-u6-X12"}],"explanation":["⟨1/10⟩이 10개면 1이에요.","1이 10개면 10, 10이 10개면 100이에요.","□는 100이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
