INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_challenge#4','math',3,1,'u6','L07','g3_1_math_u6_L07_challenge','lesson_challenge','M3-1-u6-C7',3,'error','auto','분모가 10인 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u6-X12','M3-1-u6-X18']::text[],true,'{"seq":4,"concept":"M3-1-u6-C7","difficulty":3,"kind":"error","stem":"분모가 10인 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나래 — 「⟨1/10⟩이 10개면 10이야」","correct":true,"mis_target":"M3-1-u6-X12"},{"t":"지윤 — 「1이 10개면 10이야」","mis":"M3-1-u6-X18"},{"t":"태오 — 「⟨6/10⟩은 ⟨1/10⟩이 6개야」","mis":"M3-1-u6-X18"}],"explanation":["⟨1/10⟩이 10개면 1이에요.","1이 10개면 10, 10이 10개면 100이에요.","나래의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 분모가 10인 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「1이 10개면 100이야」","correct":true,"mis_target":"M3-1-u6-X12"},{"t":"민서 — 「⟨2/10⟩는 ⟨1/10⟩이 2개야」","mis":"M3-1-u6-X18"},{"t":"나래 — 「⟨1/10⟩이 10개면 1이야」","mis":"M3-1-u6-X18"}],"explanation":["⟨1/10⟩이 10개면 1이에요.","1이 10개면 10, 10이 10개면 100이에요.","도윤의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 분모가 10인 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「⟨1/10⟩이 10개면 100이야」","correct":true,"mis_target":"M3-1-u6-X12"},{"t":"태오 — 「⟨1/10⟩이 10개면 1이야」","mis":"M3-1-u6-X18"},{"t":"유나 — 「1이 10개면 10이야」","mis":"M3-1-u6-X18"}],"explanation":["⟨1/10⟩이 10개면 1이에요.","1이 10개면 10, 10이 10개면 100이에요.","서준의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_challenge#5','math',3,1,'u6','L07','g3_1_math_u6_L07_challenge','lesson_challenge','M3-1-u6-C7',3,'ox','auto','현우가 「⟨1/10⟩이 10개 모이면 100이야.」라고 했어요. 바르게 말했어요.',ARRAY['M3-1-u6-X12']::text[],true,'{"seq":5,"concept":"M3-1-u6-C7","difficulty":3,"kind":"ox","stem":"현우가 「⟨1/10⟩이 10개 모이면 100이야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"⟨1/10⟩이 10개면 1이라서","correct":true},{"t":"10개씩 모이면 늘 100이 되어서","mis":"M3-1-u6-X12"}],"mis":"M3-1-u6-X12","explanation":["10개가 모이면 바로 다음 자리가 돼요.","⟨1/10⟩이 10개면 1, 1이 10개면 10, 10이 10개면 100이에요.","100이 아니라 1 — ×."],"variant_rule":{"alt":[{"stem":"나래가 100, 10, 1, ⟨1/10⟩이 각각 1개씩 있는 수를 「1111」이라고 썼어요. 바르게 썼어요.","answer":"X","reason_options":[{"t":"1111은 1000이 1개인 수라서 자리가 달라져서","correct":true},{"t":"1이 네 개 있으니 1111이 맞아서","mis":"M3-1-u6-X12"}],"explanation":["1111은 1000, 100, 10, 1이 하나씩인 수예요.","⟨1/10⟩은 1보다 작은 쪽의 수라 그렇게 쓸 수 없어요.","그래서 새로운 표현(소수)이 필요해요 — ×."],"asset":null},{"stem":"나래가 「⟨1/10⟩이 10개 모이면 1이야.」라고 했어요. 바르게 말했어요.","answer":"O","reason_options":[{"t":"1을 열로 나눈 한 칸이 10개면 처음 1이라서","correct":true},{"t":"⟨1/10⟩이 10개면 10이라서","mis":"M3-1-u6-X12"}],"explanation":["⟨1/10⟩은 1을 똑같이 열로 나눈 한 칸이에요.","한 칸이 10개 모이면 처음 1이 돼요.","바르게 말했어요 — ○."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_challenge#6','math',3,1,'u6','L07','g3_1_math_u6_L07_challenge','lesson_challenge','M3-1-u6-C7',3,'mc','auto','두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. ⟨2/10⟩ ○ ⟨6/10⟩',ARRAY['M3-1-u6-X09','M3-1-u6-X20']::text[],true,'{"seq":6,"concept":"M3-1-u6-C7","difficulty":3,"kind":"mc","stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. ⟨2/10⟩ ○ ⟨6/10⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u6-X09"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["⟨2/10⟩는 ⟨1/10⟩이 2개, ⟨6/10⟩은 6개예요.","분모가 같으면 분자가 클수록 큰 분수예요.","2 < 6이므로 ⟨2/10⟩ < ⟨6/10⟩."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. ⟨6/10⟩ ○ ⟨3/10⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u6-X09"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["⟨6/10⟩은 ⟨1/10⟩이 6개, ⟨3/10⟩은 3개예요.","분모가 같으면 분자가 클수록 큰 분수예요.","6 > 3이므로 ⟨6/10⟩ > ⟨3/10⟩."],"asset":null},{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. ⟨6/10⟩ ○ ⟨2/10⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u6-X09"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["⟨6/10⟩은 ⟨1/10⟩이 6개, ⟨2/10⟩는 2개예요.","분모가 같으면 분자가 클수록 큰 분수예요.","6 > 2이므로 ⟨6/10⟩ > ⟨2/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_challenge#7','math',3,1,'u6','L07','g3_1_math_u6_L07_challenge','lesson_challenge','M3-1-u6-C7',3,'sa','auto','띠의 ⟨4/10⟩만큼을 색칠하고, ⟨3/10⟩만큼을 더 색칠했어요. 색칠한 부분은 모두 ⟨□/10⟩예요. □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u6-C7","difficulty":3,"kind":"sa","stem":"띠의 ⟨4/10⟩만큼을 색칠하고, ⟨3/10⟩만큼을 더 색칠했어요. 색칠한 부분은 모두 ⟨□/10⟩예요. □ 안에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["⟨4/10⟩는 ⟨1/10⟩이 4개, ⟨3/10⟩은 3개예요.","모두 4 + 3 = 7개예요.","색칠한 부분은 ⟨7/10⟩이에요."],"asset":{"type":"fbar","bars":[{"den":10,"num":7}]},"variant_rule":{"alt":[{"stem":"띠의 ⟨7/10⟩만큼을 색칠하고, ⟨2/10⟩만큼을 더 색칠했어요. 색칠한 부분은 모두 ⟨□/10⟩예요. □ 안에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["⟨7/10⟩은 ⟨1/10⟩이 7개, ⟨2/10⟩는 2개예요.","모두 7 + 2 = 9개예요.","색칠한 부분은 ⟨9/10⟩예요."],"asset":{"type":"fbar","bars":[{"den":10,"num":9}]}},{"stem":"띠의 ⟨3/10⟩만큼을 색칠하고, ⟨3/10⟩만큼을 더 색칠했어요. 색칠한 부분은 모두 ⟨□/10⟩예요. □ 안에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["⟨3/10⟩은 ⟨1/10⟩이 3개, ⟨3/10⟩은 3개예요.","모두 3 + 3 = 6개예요.","색칠한 부분은 ⟨6/10⟩이에요."],"asset":{"type":"fbar","bars":[{"den":10,"num":6}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_challenge#8','math',3,1,'u6','L07','g3_1_math_u6_L07_challenge','lesson_challenge','M3-1-u6-C7',4,'essay','teacher','현우가 100, 10, 1, ⟨1/10⟩이 각각 1개씩 있는 수를 「1111」이라고 썼어요. 현우의 생각이 맞는지 판단하고, 왜 새로운 표현 방법이 필요한지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u6-C7","difficulty":4,"kind":"essay","stem":"현우가 100, 10, 1, ⟨1/10⟩이 각각 1개씩 있는 수를 「1111」이라고 썼어요. 현우의 생각이 맞는지 판단하고, 왜 새로운 표현 방법이 필요한지 써 보세요.","answer_guide":{"answer":"예: 틀렸다. 1111은 1000, 100, 10, 1이 하나씩 있는 수이다. 자릿값은 왼쪽으로 갈수록 10배씩 커지므로 1111로 쓰면 각 수의 자리가 달라진다. ⟨1/10⟩처럼 1보다 작은 수를 자릿값에 이어 나타내려면 새로운 표현(소수)이 필요하다.","scoring_points":["틀렸다고 판단했는가","1111로 쓰면 자리가 달라진다고 썼는가","1보다 작은 수를 나타낼 새로운 표현이 필요하다고 썼는가"]},"explanation":["1111은 1000이 1개인 수예요.","자리가 달라져요.","새 표현(소수)이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_challenge#9','math',3,1,'u6','L07','g3_1_math_u6_L07_challenge','lesson_challenge','M3-1-u6-C7',4,'essay','teacher','⟨1/10⟩이 10개 모이면 얼마가 되는지 쓰고, 「10개 모이면 다음이 된다」는 규칙을 1, 10, 100과 이어서 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u6-C7","difficulty":4,"kind":"essay","stem":"⟨1/10⟩이 10개 모이면 얼마가 되는지 쓰고, 「10개 모이면 다음이 된다」는 규칙을 1, 10, 100과 이어서 설명해 보세요.","answer_guide":{"answer":"예: ⟨1/10⟩이 10개 모이면 1이 된다. 1이 10개면 10, 10이 10개면 100이 되는 것처럼 앞의 것이 10개 모이면 다음 것이 된다. ⟨1/10⟩은 이 규칙을 1보다 작은 쪽으로 이어 준다.","scoring_points":["⟨1/10⟩이 10개면 1이라고 썼는가","1·10·100의 규칙을 함께 썼는가","1보다 작은 쪽으로 이어진다고 설명했는가"]},"explanation":["⟨1/10⟩ × 10개 = 1.","1 → 10 → 100도 10개씩.","규칙이 1보다 작은 쪽으로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L07_challenge#10','math',3,1,'u6','L07','g3_1_math_u6_L07_challenge','lesson_challenge','M3-1-u6-C7',4,'sa','auto','⟨1/10⟩이 17개인 수는 1과 ⟨□/10⟩만큼이에요. □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u6-C7","difficulty":4,"kind":"sa","stem":"⟨1/10⟩이 17개인 수는 1과 ⟨□/10⟩만큼이에요. □ 안에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["⟨1/10⟩이 10개면 1이에요.","17개 = 10개 + 7개예요.","1과 ⟨7/10⟩ — □는 7이에요."],"variant_rule":{"alt":[{"stem":"⟨1/10⟩이 18개인 수는 1과 ⟨□/10⟩만큼이에요. □ 안에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["⟨1/10⟩이 10개면 1이에요.","18개 = 10개 + 8개예요.","1과 ⟨8/10⟩ — □는 8이에요."],"asset":null},{"stem":"⟨1/10⟩이 15개인 수는 1과 ⟨□/10⟩만큼이에요. □ 안에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["⟨1/10⟩이 10개면 1이에요.","15개 = 10개 + 5개예요.","1과 ⟨5/10⟩ — □는 5예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L08_basic#1','math',3,1,'u6','L08','g3_1_math_u6_L08_basic','lesson_basic','M3-1-u6-C8',1,'mc','auto','⟨1/10⟩을 소수로 나타내면 무엇인가요?',ARRAY['M3-1-u6-X13']::text[],true,'{"seq":1,"concept":"M3-1-u6-C8","difficulty":1,"kind":"mc","stem":"⟨1/10⟩을 소수로 나타내면 무엇인가요?","options":[{"t":"0.1","correct":true},{"t":"1.0","mis":"M3-1-u6-X13"},{"t":"0.01","mis":"M3-1-u6-X13"},{"t":"1","mis":"M3-1-u6-X13"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨1/10⟩은 0.1이 1개예요.","⟨1/10⟩ = 0.1이에요."],"variant_rule":{"alt":[{"stem":"⟨8/10⟩을 소수로 나타내면 무엇인가요?","options":[{"t":"0.8","correct":true},{"t":"8.0","mis":"M3-1-u6-X13"},{"t":"0.08","mis":"M3-1-u6-X13"},{"t":"8","mis":"M3-1-u6-X13"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨8/10⟩은 0.1이 8개예요.","⟨8/10⟩ = 0.8이에요."],"asset":null},{"stem":"⟨3/10⟩을 소수로 나타내면 무엇인가요?","options":[{"t":"0.3","correct":true},{"t":"3.0","mis":"M3-1-u6-X13"},{"t":"0.03","mis":"M3-1-u6-X13"},{"t":"3","mis":"M3-1-u6-X13"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨3/10⟩은 0.1이 3개예요.","⟨3/10⟩ = 0.3이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L08_basic#2','math',3,1,'u6','L08','g3_1_math_u6_L08_basic','lesson_basic','M3-1-u6-C8',1,'mc','auto','띠를 똑같이 열 칸으로 나누어 색칠했어요. 색칠한 부분을 소수로 나타내면 무엇인가요?',ARRAY['M3-1-u6-X04','M3-1-u6-X13']::text[],true,'{"seq":2,"concept":"M3-1-u6-C8","difficulty":1,"kind":"mc","stem":"띠를 똑같이 열 칸으로 나누어 색칠했어요. 색칠한 부분을 소수로 나타내면 무엇인가요?","options":[{"t":"0.4","correct":true},{"t":"0.6","mis":"M3-1-u6-X04"},{"t":"4.0","mis":"M3-1-u6-X13"},{"t":"4","mis":"M3-1-u6-X13"}],"explanation":["한 칸은 ⟨1/10⟩ = 0.1이에요.","색칠한 칸은 4칸 — 0.1이 4개예요.","색칠한 부분은 0.4예요."],"asset":{"type":"fbar","bars":[{"den":10,"num":4}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 띠를 똑같이 열 칸으로 나누어 색칠했어요. 색칠한 부분을 소수로 나타내면 무엇인가요?","options":[{"t":"0.1","correct":true},{"t":"0.9","mis":"M3-1-u6-X04"},{"t":"1.0","mis":"M3-1-u6-X13"},{"t":"1","mis":"M3-1-u6-X13"}],"explanation":["한 칸은 ⟨1/10⟩ = 0.1이에요.","색칠한 칸은 1칸 — 0.1이 1개예요.","색칠한 부분은 0.1이에요."],"asset":{"type":"fbar","bars":[{"den":10,"num":1}]}},{"stem":"이번에는 다른 문제예요. 띠를 똑같이 열 칸으로 나누어 색칠했어요. 색칠한 부분을 소수로 나타내면 무엇인가요?","options":[{"t":"0.3","correct":true},{"t":"0.7","mis":"M3-1-u6-X04"},{"t":"3.0","mis":"M3-1-u6-X13"},{"t":"3","mis":"M3-1-u6-X13"}],"explanation":["한 칸은 ⟨1/10⟩ = 0.1이에요.","색칠한 칸은 3칸 — 0.1이 3개예요.","색칠한 부분은 0.3이에요."],"asset":{"type":"fbar","bars":[{"den":10,"num":3}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
