INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L08_basic#8','math',3,1,'u6','L08','g3_1_math_u6_L08_basic','lesson_basic','M3-1-u6-C8',2,'ox','auto','지윤이 「0.1이 10개면 0.10이야.」라고 했어요. 바르게 말했어요.',ARRAY['M3-1-u6-X13']::text[],true,'{"seq":8,"concept":"M3-1-u6-C8","difficulty":2,"kind":"ox","stem":"지윤이 「0.1이 10개면 0.10이야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"0.1이 10개면 1이 되어서","correct":true},{"t":"0.1 뒤에 0을 붙이면 10개라서","mis":"M3-1-u6-X13"}],"mis":"M3-1-u6-X13","explanation":["0.1은 ⟨1/10⟩이에요.","⟨1/10⟩이 10개 모이면 1이에요.","0.1이 10개면 1 — 틀렸어요(×)."],"variant_rule":{"alt":[{"stem":"나래가 「0.1이 10개면 10이야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"0.1이 10개면 1이라서","correct":true},{"t":"1이 10개면 10이니까 0.1도 10개면 10이라서","mis":"M3-1-u6-X12"}],"explanation":["0.1은 1을 열로 나눈 한 칸이에요.","한 칸이 10개면 1이에요.","10이 아니라 1 — ×."],"asset":null},{"stem":"나래가 「0.1이 10개면 1이야.」라고 했어요. 바르게 말했어요.","answer":"O","reason_options":[{"t":"0.1은 ⟨1/10⟩이라 10개면 전체 1이 되어서","correct":true},{"t":"0.1이 10개면 10이라서","mis":"M3-1-u6-X12"}],"explanation":["0.1 = ⟨1/10⟩이에요.","⟨1/10⟩이 10개면 1이에요.","바르게 말했어요 — ○."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L08_basic#9','math',3,1,'u6','L08','g3_1_math_u6_L08_basic','lesson_basic','M3-1-u6-C8',2,'match','auto','크기가 같은 분수와 소수를 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u6-C8","difficulty":2,"kind":"match","stem":"크기가 같은 분수와 소수를 알맞게 이으세요.","pairs":[{"l":"⟨7/10⟩","r":"0.7"},{"l":"⟨8/10⟩","r":"0.8"},{"l":"⟨9/10⟩","r":"0.9"}],"mis":"M3-1-u6-X13","explanation":["⟨1/10⟩ = 0.1이에요.","⟨7/10⟩ = 0.7, ⟨8/10⟩ = 0.8, ⟨9/10⟩ = 0.9.","분자가 소수점 뒤 수가 돼요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 크기가 같은 분수와 소수를 알맞게 이으세요.","pairs":[{"l":"⟨9/10⟩","r":"0.9"},{"l":"⟨5/10⟩","r":"0.5"},{"l":"⟨1/10⟩","r":"0.1"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨9/10⟩ = 0.9, ⟨5/10⟩ = 0.5, ⟨1/10⟩ = 0.1.","분자가 소수점 뒤 수가 돼요."],"asset":null},{"stem":"이번에는 다른 문제예요. 크기가 같은 분수와 소수를 알맞게 이으세요.","pairs":[{"l":"⟨4/10⟩","r":"0.4"},{"l":"⟨2/10⟩","r":"0.2"},{"l":"⟨1/10⟩","r":"0.1"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨4/10⟩ = 0.4, ⟨2/10⟩ = 0.2, ⟨1/10⟩ = 0.1.","분자가 소수점 뒤 수가 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L08_basic#10','math',3,1,'u6','L08','g3_1_math_u6_L08_basic','lesson_basic','M3-1-u6-C8',3,'mc','auto','크기가 다른 하나는 어느 것인가요?',ARRAY['M3-1-u6-X16']::text[],true,'{"seq":10,"concept":"M3-1-u6-C8","difficulty":3,"kind":"mc","stem":"크기가 다른 하나는 어느 것인가요?","options":[{"t":"4.0","correct":true},{"t":"0.1이 4개인 수","mis":"M3-1-u6-X16"},{"t":"⟨4/10⟩","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩이 4개인 수","mis":"M3-1-u6-X16"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨4/10⟩, 0.4, 0.1이 4개는 모두 같은 크기예요.","4.0만 크기가 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 크기가 다른 하나는 어느 것인가요?","options":[{"t":"4.0","correct":true},{"t":"⟨4/10⟩","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩이 4개인 수","mis":"M3-1-u6-X16"},{"t":"0.4","mis":"M3-1-u6-X16"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨4/10⟩, 0.4, 0.1이 4개는 모두 같은 크기예요.","4.0만 크기가 달라요."],"asset":null},{"stem":"이번에는 다른 문제예요. 크기가 다른 하나는 어느 것인가요?","options":[{"t":"0.1이 9개인 수","correct":true},{"t":"0.1이 1개인 수","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩이 1개인 수","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩","mis":"M3-1-u6-X16"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨1/10⟩, 0.1, 0.1이 1개는 모두 같은 크기예요.","0.1이 9개인 수만 크기가 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L08_challenge#1','math',3,1,'u6','L08','g3_1_math_u6_L08_challenge','lesson_challenge','M3-1-u6-C8',2,'sa','auto','0.8에 0.1이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u6-C8","difficulty":2,"kind":"sa","stem":"0.8에 0.1이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["0.1이 10개 모이면 1이에요.","0.8은 0.1이 8개예요.","10 − 8 = 2개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"0.6에 0.1이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["0.1이 10개 모이면 1이에요.","0.6은 0.1이 6개예요.","10 − 6 = 4개 더 있어야 해요."],"asset":null},{"stem":"0.3에 0.1이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["7"],"explanation":["0.1이 10개 모이면 1이에요.","0.3은 0.1이 3개예요.","10 − 3 = 7개 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
