INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L08_challenge#3','math',3,1,'u6','L08','g3_1_math_u6_L08_challenge','lesson_challenge','M3-1-u6-C8',3,'mc','auto','크기가 다른 하나는 어느 것인가요?',ARRAY['M3-1-u6-X16']::text[],true,'{"seq":3,"concept":"M3-1-u6-C8","difficulty":3,"kind":"mc","stem":"크기가 다른 하나는 어느 것인가요?","options":[{"t":"0.9","correct":true},{"t":"⟨1/10⟩이 1개인 수","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩","mis":"M3-1-u6-X16"},{"t":"0.1이 1개인 수","mis":"M3-1-u6-X16"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨1/10⟩, 0.1, 0.1이 1개는 모두 같은 크기예요.","0.9만 크기가 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 크기가 다른 하나는 어느 것인가요?","options":[{"t":"0.1이 2개인 수","correct":true},{"t":"0.1이 8개인 수","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩이 8개인 수","mis":"M3-1-u6-X16"},{"t":"⟨8/10⟩","mis":"M3-1-u6-X16"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨8/10⟩, 0.8, 0.1이 8개는 모두 같은 크기예요.","0.1이 2개인 수만 크기가 달라요."],"asset":null},{"stem":"이번에는 다른 문제예요. 크기가 다른 하나는 어느 것인가요?","options":[{"t":"7.0","correct":true},{"t":"0.1이 7개인 수","mis":"M3-1-u6-X16"},{"t":"⟨7/10⟩","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩이 7개인 수","mis":"M3-1-u6-X16"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨7/10⟩, 0.7, 0.1이 7개는 모두 같은 크기예요.","7.0만 크기가 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L08_challenge#4','math',3,1,'u6','L08','g3_1_math_u6_L08_challenge','lesson_challenge','M3-1-u6-C8',3,'error','auto','소수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u6-X13','M3-1-u6-X18']::text[],true,'{"seq":4,"concept":"M3-1-u6-C8","difficulty":3,"kind":"error","stem":"소수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「0.1이 10개면 0.10이야」","correct":true,"mis_target":"M3-1-u6-X13"},{"t":"민서 — 「가운데 점을 소수점이라고 해」","mis":"M3-1-u6-X18"},{"t":"유나 — 「⟨3/10⟩은 0.3이야」","mis":"M3-1-u6-X18"}],"explanation":["⟨1/10⟩ = 0.1, 0.1이 10개면 1이에요.","0.8은 「영 점 팔」, ⟨7/10⟩ = 0.7이에요.","태오의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 소수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유나 — 「0.8은 팔 점 영이라고 읽어」","correct":true,"mis_target":"M3-1-u6-X14"},{"t":"민서 — 「⟨2/10⟩는 0.2야」","mis":"M3-1-u6-X18"},{"t":"도윤 — 「0.2는 0.1이 2개야」","mis":"M3-1-u6-X18"}],"explanation":["⟨1/10⟩ = 0.1, 0.1이 10개면 1이에요.","0.8은 「영 점 팔」, ⟨7/10⟩ = 0.7이에요.","유나의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 소수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「⟨7/10⟩은 0.07이야」","correct":true,"mis_target":"M3-1-u6-X13"},{"t":"나래 — 「0.9는 0.1이 9개야」","mis":"M3-1-u6-X18"},{"t":"지윤 — 「가운데 점을 소수점이라고 해」","mis":"M3-1-u6-X18"}],"explanation":["⟨1/10⟩ = 0.1, 0.1이 10개면 1이에요.","0.8은 「영 점 팔」, ⟨7/10⟩ = 0.7이에요.","현우의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L08_challenge#5','math',3,1,'u6','L08','g3_1_math_u6_L08_challenge','lesson_challenge','M3-1-u6-C8',3,'mc','auto','단추 구멍의 길이는 7 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?',ARRAY['M3-1-u6-X17','M3-1-u6-X13']::text[],true,'{"seq":5,"concept":"M3-1-u6-C8","difficulty":3,"kind":"mc","stem":"단추 구멍의 길이는 7 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.7 cm","correct":true},{"t":"7 cm","mis":"M3-1-u6-X17"},{"t":"0.07 cm","mis":"M3-1-u6-X17"},{"t":"7.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","7 mm = 0.1 cm가 7개 = 0.7 cm."],"asset":{"type":"mmruler","len":7,"label":"단추 구멍"},"variant_rule":{"alt":[{"stem":"리본 폭의 길이는 6 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.6 cm","correct":true},{"t":"6 cm","mis":"M3-1-u6-X17"},{"t":"0.06 cm","mis":"M3-1-u6-X17"},{"t":"6.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","6 mm = 0.1 cm가 6개 = 0.6 cm."],"asset":{"type":"mmruler","len":6,"label":"리본 폭"}},{"stem":"나뭇잎 자루의 길이는 3 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.3 cm","correct":true},{"t":"3 cm","mis":"M3-1-u6-X17"},{"t":"0.03 cm","mis":"M3-1-u6-X17"},{"t":"3.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","3 mm = 0.1 cm가 3개 = 0.3 cm."],"asset":{"type":"mmruler","len":3,"label":"나뭇잎 자루"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L08_challenge#6','math',3,1,'u6','L08','g3_1_math_u6_L08_challenge','lesson_challenge','M3-1-u6-C8',3,'mc','auto','0.9보다 0.1만큼 더 큰 수는 무엇인가요?',ARRAY['M3-1-u6-X13','M3-1-u6-X12']::text[],true,'{"seq":6,"concept":"M3-1-u6-C8","difficulty":3,"kind":"mc","stem":"0.9보다 0.1만큼 더 큰 수는 무엇인가요?","options":[{"t":"1","correct":true},{"t":"0.10","mis":"M3-1-u6-X13"},{"t":"0.91","mis":"M3-1-u6-X13"},{"t":"10","mis":"M3-1-u6-X12"}],"explanation":["0.9는 0.1이 9개예요.","0.1이 하나 더 있으면 10개예요.","0.1이 10개면 1이에요."],"variant_rule":{"alt":[{"stem":"0.1이 10개 모이면 얼마인가요?","options":[{"t":"1","correct":true},{"t":"0.10","mis":"M3-1-u6-X13"},{"t":"10","mis":"M3-1-u6-X12"},{"t":"0.1","mis":"M3-1-u6-X19"}],"explanation":["0.1 = ⟨1/10⟩이에요.","⟨1/10⟩이 10개면 1이에요.","0.1이 10개면 1이에요."],"asset":null},{"stem":"1은 0.1이 몇 개인가요?","options":[{"t":"10개","correct":true},{"t":"1개","mis":"M3-1-u6-X19"},{"t":"100개","mis":"M3-1-u6-X12"},{"t":"0.10개","mis":"M3-1-u6-X13"}],"explanation":["0.1은 1을 열로 나눈 한 칸이에요.","한 칸이 10개 모이면 1이에요.","1은 0.1이 10개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L08_challenge#7','math',3,1,'u6','L08','g3_1_math_u6_L08_challenge','lesson_challenge','M3-1-u6-C8',3,'mc','auto','소수 0.4를 분수로 나타내면 무엇인가요?',ARRAY['M3-1-u6-X02','M3-1-u6-X16','M3-1-u6-X04']::text[],true,'{"seq":7,"concept":"M3-1-u6-C8","difficulty":3,"kind":"mc","stem":"소수 0.4를 분수로 나타내면 무엇인가요?","options":[{"t":"⟨4/10⟩","correct":true},{"t":"⟨10/4⟩","mis":"M3-1-u6-X02"},{"t":"⟨1/4⟩","mis":"M3-1-u6-X16"},{"t":"⟨6/10⟩","mis":"M3-1-u6-X04"}],"explanation":["0.1 = ⟨1/10⟩이에요.","0.4는 0.1이 4개 — ⟨1/10⟩이 4개.","0.4 = ⟨4/10⟩예요."],"variant_rule":{"alt":[{"stem":"소수 0.6을 분수로 나타내면 무엇인가요?","options":[{"t":"⟨6/10⟩","correct":true},{"t":"⟨10/6⟩","mis":"M3-1-u6-X02"},{"t":"⟨1/6⟩","mis":"M3-1-u6-X16"},{"t":"⟨4/10⟩","mis":"M3-1-u6-X04"}],"explanation":["0.1 = ⟨1/10⟩이에요.","0.6은 0.1이 6개 — ⟨1/10⟩이 6개.","0.6 = ⟨6/10⟩이에요."],"asset":null},{"stem":"소수 0.2를 분수로 나타내면 무엇인가요?","options":[{"t":"⟨2/10⟩","correct":true},{"t":"⟨10/2⟩","mis":"M3-1-u6-X02"},{"t":"⟨1/2⟩","mis":"M3-1-u6-X16"},{"t":"⟨8/10⟩","mis":"M3-1-u6-X04"}],"explanation":["0.1 = ⟨1/10⟩이에요.","0.2는 0.1이 2개 — ⟨1/10⟩이 2개.","0.2 = ⟨2/10⟩예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L08_challenge#8','math',3,1,'u6','L08','g3_1_math_u6_L08_challenge','lesson_challenge','M3-1-u6-C8',4,'essay','teacher','칼림바 건반의 너비가 3 mm예요. 이 너비를 cm로 나타내면 몇 cm인지 소수로 쓰고, 그렇게 구한 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u6-C8","difficulty":4,"kind":"essay","stem":"칼림바 건반의 너비가 3 mm예요. 이 너비를 cm로 나타내면 몇 cm인지 소수로 쓰고, 그렇게 구한 방법을 설명해 보세요.","answer_guide":{"answer":"예: 1 cm는 10 mm이므로 1 mm는 1 cm를 똑같이 열로 나눈 하나, 곧 ⟨1/10⟩ cm = 0.1 cm이다. 3 mm는 0.1 cm가 3개이므로 0.3 cm이다.","scoring_points":["1 mm = 0.1 cm임을 썼는가","0.1 cm가 3개라고 설명했는가","0.3 cm라고 답했는가"]},"explanation":["1 mm = ⟨1/10⟩ cm = 0.1 cm.","3 mm = 0.1 cm가 3개.","0.3 cm."],"asset":{"type":"mmruler","len":3,"label":"칼림바 건반"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L08_challenge#9','math',3,1,'u6','L08','g3_1_math_u6_L08_challenge','lesson_challenge','M3-1-u6-C8',4,'essay','teacher','민서가 「0.1이 10개면 0.10이야.」라고 했어요. 민서의 말이 맞는지 판단하고, 0.1이 10개면 얼마인지 분수를 이용해 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u6-C8","difficulty":4,"kind":"essay","stem":"민서가 「0.1이 10개면 0.10이야.」라고 했어요. 민서의 말이 맞는지 판단하고, 0.1이 10개면 얼마인지 분수를 이용해 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 0.1은 ⟨1/10⟩이고 ⟨1/10⟩이 10개 모이면 전체인 1이 된다. 그래서 0.1이 10개면 0.10이 아니라 1이다.","scoring_points":["틀렸다고 판단했는가","0.1 = ⟨1/10⟩임을 썼는가","10개 모이면 1이라고 설명했는가"]},"explanation":["0.1 = ⟨1/10⟩.","⟨1/10⟩이 10개면 1.","0.1이 10개면 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L08_challenge#10','math',3,1,'u6','L08','g3_1_math_u6_L08_challenge','lesson_challenge','M3-1-u6-C8',4,'mc','auto','크기가 다른 하나는 어느 것인가요?',ARRAY['M3-1-u6-X16']::text[],true,'{"seq":10,"concept":"M3-1-u6-C8","difficulty":4,"kind":"mc","stem":"크기가 다른 하나는 어느 것인가요?","options":[{"t":"7.0","correct":true},{"t":"⟨7/10⟩","mis":"M3-1-u6-X16"},{"t":"0.1이 7개인 수","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩이 7개인 수","mis":"M3-1-u6-X16"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨7/10⟩, 0.7, 0.1이 7개는 모두 같은 크기예요.","7.0만 크기가 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 크기가 다른 하나는 어느 것인가요?","options":[{"t":"9.0","correct":true},{"t":"⟨9/10⟩","mis":"M3-1-u6-X16"},{"t":"0.1이 9개인 수","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩이 9개인 수","mis":"M3-1-u6-X16"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨9/10⟩, 0.9, 0.1이 9개는 모두 같은 크기예요.","9.0만 크기가 달라요."],"asset":null},{"stem":"이번에는 다른 문제예요. 크기가 다른 하나는 어느 것인가요?","options":[{"t":"0.7","correct":true},{"t":"⟨1/10⟩이 3개인 수","mis":"M3-1-u6-X16"},{"t":"⟨3/10⟩","mis":"M3-1-u6-X16"},{"t":"0.1이 3개인 수","mis":"M3-1-u6-X16"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨3/10⟩, 0.3, 0.1이 3개는 모두 같은 크기예요.","0.7만 크기가 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_basic#1','math',3,1,'u6','L09','g3_1_math_u6_L09_basic','lesson_basic','M3-1-u6-C9',1,'mc','auto','0.4와 0.6 중 더 큰 수는 무엇인가요?',ARRAY['M3-1-u6-X15','M3-1-u6-X20']::text[],true,'{"seq":1,"concept":"M3-1-u6-C9","difficulty":1,"kind":"mc","stem":"0.4와 0.6 중 더 큰 수는 무엇인가요?","options":[{"t":"0.6","correct":true},{"t":"0.4","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.4는 0.1이 4개, 0.6은 0.1이 6개예요.","0.1의 개수가 많을수록 큰 소수예요.","4 < 6 — 0.4 < 0.6."],"variant_rule":{"alt":[{"stem":"0.4와 0.3 중 더 큰 수는 무엇인가요?","options":[{"t":"0.4","correct":true},{"t":"0.3","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.4는 0.1이 4개, 0.3은 0.1이 3개예요.","0.1의 개수가 많을수록 큰 소수예요.","4 > 3 — 0.4 > 0.3."],"asset":null},{"stem":"0.7과 0.9 중 더 큰 수는 무엇인가요?","options":[{"t":"0.9","correct":true},{"t":"0.7","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.7은 0.1이 7개, 0.9는 0.1이 9개예요.","0.1의 개수가 많을수록 큰 소수예요.","7 < 9 — 0.7 < 0.9."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
