INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_basic#4','math',3,1,'u6','L09','g3_1_math_u6_L09_basic','lesson_basic','M3-1-u6-C9',1,'mc','auto','0.몇인 두 소수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['M3-1-u6-X15','M3-1-u6-X20','M3-1-u6-X16']::text[],true,'{"seq":4,"concept":"M3-1-u6-C9","difficulty":1,"kind":"mc","stem":"0.몇인 두 소수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"0.1의 개수가 많을수록 큰 소수예요","correct":true},{"t":"0.1의 개수가 적을수록 큰 소수예요","mis":"M3-1-u6-X15"},{"t":"소수점이 있으면 늘 크기가 같아요","mis":"M3-1-u6-X20"},{"t":"소수는 분수와 크기를 견줄 수 없어요","mis":"M3-1-u6-X16"}],"explanation":["0.몇은 0.1이 몇 개인지로 볼 수 있어요.","0.1이 많을수록 커요.","0.1의 개수가 많을수록 큰 소수예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 0.몇인 두 소수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"분수로 바꾸면 분자가 클수록 커요","correct":true},{"t":"0.1의 개수가 적을수록 큰 소수예요","mis":"M3-1-u6-X15"},{"t":"소수점이 있으면 늘 크기가 같아요","mis":"M3-1-u6-X20"},{"t":"소수는 분수와 크기를 견줄 수 없어요","mis":"M3-1-u6-X16"}],"explanation":["0.몇은 0.1이 몇 개인지로 볼 수 있어요.","0.1이 많을수록 커요.","분수로 바꾸면 분자가 클수록 커요."],"asset":null},{"stem":"이번에는 다른 문제예요. 0.몇인 두 소수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"소수점 뒤 수가 클수록 커요(0.몇끼리)","correct":true},{"t":"0.1의 개수가 적을수록 큰 소수예요","mis":"M3-1-u6-X15"},{"t":"소수점이 있으면 늘 크기가 같아요","mis":"M3-1-u6-X20"},{"t":"소수는 분수와 크기를 견줄 수 없어요","mis":"M3-1-u6-X16"}],"explanation":["0.몇은 0.1이 몇 개인지로 볼 수 있어요.","0.1이 많을수록 커요.","소수점 뒤 수가 클수록 커요(0.몇끼리)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_basic#5','math',3,1,'u6','L09','g3_1_math_u6_L09_basic','lesson_basic','M3-1-u6-C9',2,'mc','auto','가오리연을 만들려고 대나무 살 두 개를 준비했어요. 하나는 0.4 m, 다른 하나는 0.6 m예요. 더 긴 것은 어느 것인가요?',ARRAY['M3-1-u6-X15','M3-1-u6-X20']::text[],true,'{"seq":5,"concept":"M3-1-u6-C9","difficulty":2,"kind":"mc","stem":"가오리연을 만들려고 대나무 살 두 개를 준비했어요. 하나는 0.4 m, 다른 하나는 0.6 m예요. 더 긴 것은 어느 것인가요?","options":[{"t":"0.6 m인 대나무 살","correct":true},{"t":"0.4 m인 대나무 살","mis":"M3-1-u6-X15"},{"t":"두 개의 길이가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.4 m는 0.1 m가 4개, 0.6 m는 6개예요.","0.1이 많을수록 길어요.","0.6 m가 더 길어요."],"variant_rule":{"alt":[{"stem":"가오리연을 만들려고 연 꼬리 끈 두 개를 준비했어요. 하나는 0.4 m, 다른 하나는 0.2 m예요. 더 긴 것은 어느 것인가요?","options":[{"t":"0.4 m인 연 꼬리 끈","correct":true},{"t":"0.2 m인 연 꼬리 끈","mis":"M3-1-u6-X15"},{"t":"두 개의 길이가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.4 m는 0.1 m가 4개, 0.2 m는 2개예요.","0.1이 많을수록 길어요.","0.4 m가 더 길어요."],"asset":null},{"stem":"가오리연을 만들려고 리본 두 개를 준비했어요. 하나는 0.9 m, 다른 하나는 0.6 m예요. 더 긴 것은 어느 것인가요?","options":[{"t":"0.9 m인 리본","correct":true},{"t":"0.6 m인 리본","mis":"M3-1-u6-X15"},{"t":"두 개의 길이가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.9 m는 0.1 m가 9개, 0.6 m는 6개예요.","0.1이 많을수록 길어요.","0.9 m가 더 길어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_basic#6','math',3,1,'u6','L09','g3_1_math_u6_L09_basic','lesson_basic','M3-1-u6-C9',2,'mc','auto','0.2와 0.5 중 더 작은 수는 무엇인가요?',ARRAY['M3-1-u6-X18','M3-1-u6-X20']::text[],true,'{"seq":6,"concept":"M3-1-u6-C9","difficulty":2,"kind":"mc","stem":"0.2와 0.5 중 더 작은 수는 무엇인가요?","options":[{"t":"0.2","correct":true},{"t":"0.5","mis":"M3-1-u6-X18"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.2는 0.1이 2개, 0.5는 0.1이 5개예요.","0.1의 개수가 많을수록 큰 소수예요.","2 < 5 — 0.2 < 0.5."],"variant_rule":{"alt":[{"stem":"0.9와 0.4 중 더 작은 수는 무엇인가요?","options":[{"t":"0.4","correct":true},{"t":"0.9","mis":"M3-1-u6-X18"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.9는 0.1이 9개, 0.4는 0.1이 4개예요.","0.1의 개수가 많을수록 큰 소수예요.","9 > 4 — 0.9 > 0.4."],"asset":null},{"stem":"0.3과 0.7 중 더 작은 수는 무엇인가요?","options":[{"t":"0.3","correct":true},{"t":"0.7","mis":"M3-1-u6-X18"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.3은 0.1이 3개, 0.7은 0.1이 7개예요.","0.1의 개수가 많을수록 큰 소수예요.","3 < 7 — 0.3 < 0.7."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_basic#7','math',3,1,'u6','L09','g3_1_math_u6_L09_basic','lesson_basic','M3-1-u6-C9',2,'mc','auto','가장 큰 수는 무엇인가요? 0.4, 0.6, 0.9, 0.3',ARRAY['M3-1-u6-X15','M3-1-u6-X18']::text[],true,'{"seq":7,"concept":"M3-1-u6-C9","difficulty":2,"kind":"mc","stem":"가장 큰 수는 무엇인가요? 0.4, 0.6, 0.9, 0.3","options":[{"t":"0.9","correct":true},{"t":"0.4","mis":"M3-1-u6-X15"},{"t":"0.6","mis":"M3-1-u6-X15"},{"t":"0.3","mis":"M3-1-u6-X18"}],"explanation":["0.1의 개수를 견주어요 — 4, 6, 9, 3.","0.1이 가장 많은 소수가 가장 큰 수예요.","0.9예요."],"variant_rule":{"alt":[{"stem":"가장 큰 수는 무엇인가요? 0.3, 0.4, 0.2, 0.1","options":[{"t":"0.4","correct":true},{"t":"0.3","mis":"M3-1-u6-X15"},{"t":"0.2","mis":"M3-1-u6-X15"},{"t":"0.1","mis":"M3-1-u6-X18"}],"explanation":["0.1의 개수를 견주어요 — 3, 4, 2, 1.","0.1이 가장 많은 소수가 가장 큰 수예요.","0.4예요."],"asset":null},{"stem":"가장 큰 수는 무엇인가요? 0.2, 0.4, 0.9, 0.3","options":[{"t":"0.9","correct":true},{"t":"0.2","mis":"M3-1-u6-X18"},{"t":"0.4","mis":"M3-1-u6-X15"},{"t":"0.3","mis":"M3-1-u6-X15"}],"explanation":["0.1의 개수를 견주어요 — 2, 4, 9, 3.","0.1이 가장 많은 소수가 가장 큰 수예요.","0.9예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_basic#8','math',3,1,'u6','L09','g3_1_math_u6_L09_basic','lesson_basic','M3-1-u6-C9',2,'ox','auto','태오가 「0.7이 0.9보다 커.」라고 했어요. 바르게 말했어요.',ARRAY['M3-1-u6-X15']::text[],true,'{"seq":8,"concept":"M3-1-u6-C9","difficulty":2,"kind":"ox","stem":"태오가 「0.7이 0.9보다 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"0.9는 0.1이 9개라 더 커서","correct":true},{"t":"0.1의 개수가 적을수록 커서","mis":"M3-1-u6-X15"}],"mis":"M3-1-u6-X15","explanation":["0.7은 0.1이 7개, 0.9는 9개예요.","0.1이 많을수록 커요.","0.7 < 0.9 — 틀렸어요(×)."],"variant_rule":{"alt":[{"stem":"유나가 「0.4가 0.9보다 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"0.9는 0.1이 9개라 더 커서","correct":true},{"t":"0.1의 개수가 적을수록 커서","mis":"M3-1-u6-X15"}],"explanation":["0.4는 0.1이 4개, 0.9는 9개예요.","0.1이 많을수록 커요.","0.4 < 0.9 — 틀렸어요(×)."],"asset":null},{"stem":"유나가 「0.4가 0.7보다 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"0.7은 0.1이 7개라 더 커서","correct":true},{"t":"0.1의 개수가 적을수록 커서","mis":"M3-1-u6-X15"}],"explanation":["0.4는 0.1이 4개, 0.7은 7개예요.","0.1이 많을수록 커요.","0.4 < 0.7 — 틀렸어요(×)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_basic#9','math',3,1,'u6','L09','g3_1_math_u6_L09_basic','lesson_basic','M3-1-u6-C9',2,'error','auto','소수의 크기 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u6-X15','M3-1-u6-X18']::text[],true,'{"seq":9,"concept":"M3-1-u6-C9","difficulty":2,"kind":"error","stem":"소수의 크기 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「0.1이 적을수록 큰 소수야」","correct":true,"mis_target":"M3-1-u6-X15"},{"t":"도윤 — 「0.1이 많을수록 큰 소수야」","mis":"M3-1-u6-X18"},{"t":"민서 — 「띠에서 더 많이 색칠한 쪽이 커」","mis":"M3-1-u6-X18"}],"explanation":["0.1이 많을수록 큰 소수예요.","0.2 > 0.1, 0.1 = ⟨1/10⟩이에요.","태오의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 소수의 크기 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「0.5와 ⟨5/10⟩는 크기가 달라」","correct":true,"mis_target":"M3-1-u6-X16"},{"t":"나래 — 「띠에서 더 많이 색칠한 쪽이 커」","mis":"M3-1-u6-X18"},{"t":"민서 — 「0.5가 0.4보다 커」","mis":"M3-1-u6-X18"}],"explanation":["0.1이 많을수록 큰 소수예요.","0.5 > 0.4, 0.5 = ⟨5/10⟩예요.","현우의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 소수의 크기 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나래 — 「0.7이 0.8보다 커」","correct":true,"mis_target":"M3-1-u6-X15"},{"t":"지유 — 「0.8이 0.7보다 커」","mis":"M3-1-u6-X18"},{"t":"유나 — 「0.1이 많을수록 큰 소수야」","mis":"M3-1-u6-X18"}],"explanation":["0.1이 많을수록 큰 소수예요.","0.8 > 0.7, 0.7 = ⟨7/10⟩이에요.","나래의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_basic#10','math',3,1,'u6','L09','g3_1_math_u6_L09_basic','lesson_basic','M3-1-u6-C9',3,'mc','auto','두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.5 ○ ⟨5/10⟩',ARRAY['M3-1-u6-X16','M3-1-u6-X20']::text[],true,'{"seq":10,"concept":"M3-1-u6-C9","difficulty":3,"kind":"mc","stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.5 ○ ⟨5/10⟩","options":[{"t":"=","correct":true},{"t":">","mis":"M3-1-u6-X16"},{"t":"<","mis":"M3-1-u6-X16"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.5 = ⟨5/10⟩예요.","분모가 10으로 같으니 분자를 견주어요 — 5와 5.","0.5 = ⟨5/10⟩."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.3 ○ ⟨1/10⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u6-X16"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.3 = ⟨3/10⟩이에요.","분모가 10으로 같으니 분자를 견주어요 — 3과 1.","0.3 > ⟨1/10⟩."],"asset":null},{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.3 ○ ⟨3/10⟩","options":[{"t":"=","correct":true},{"t":">","mis":"M3-1-u6-X16"},{"t":"<","mis":"M3-1-u6-X16"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.3 = ⟨3/10⟩이에요.","분모가 10으로 같으니 분자를 견주어요 — 3과 3.","0.3 = ⟨3/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_challenge#1','math',3,1,'u6','L09','g3_1_math_u6_L09_challenge','lesson_challenge','M3-1-u6-C9',2,'mc','auto','두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.4 ○ 0.7',ARRAY['M3-1-u6-X15','M3-1-u6-X20']::text[],true,'{"seq":1,"concept":"M3-1-u6-C9","difficulty":2,"kind":"mc","stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.4 ○ 0.7","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u6-X15"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.4는 0.1이 4개, 0.7은 0.1이 7개예요.","0.1의 개수가 많을수록 큰 소수예요.","4 < 7 — 0.4 < 0.7."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.7 ○ 0.6","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u6-X15"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.7은 0.1이 7개, 0.6은 0.1이 6개예요.","0.1의 개수가 많을수록 큰 소수예요.","7 > 6 — 0.7 > 0.6."],"asset":null},{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.3 ○ 0.8","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u6-X15"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.3은 0.1이 3개, 0.8은 0.1이 8개예요.","0.1의 개수가 많을수록 큰 소수예요.","3 < 8 — 0.3 < 0.8."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_challenge#2','math',3,1,'u6','L09','g3_1_math_u6_L09_challenge','lesson_challenge','M3-1-u6-C9',2,'mc','auto','가오리연을 만들려고 연 꼬리 끈 두 개를 준비했어요. 하나는 0.3 m, 다른 하나는 0.4 m예요. 더 긴 것은 어느 것인가요?',ARRAY['M3-1-u6-X15','M3-1-u6-X20']::text[],true,'{"seq":2,"concept":"M3-1-u6-C9","difficulty":2,"kind":"mc","stem":"가오리연을 만들려고 연 꼬리 끈 두 개를 준비했어요. 하나는 0.3 m, 다른 하나는 0.4 m예요. 더 긴 것은 어느 것인가요?","options":[{"t":"0.4 m인 연 꼬리 끈","correct":true},{"t":"0.3 m인 연 꼬리 끈","mis":"M3-1-u6-X15"},{"t":"두 개의 길이가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.3 m는 0.1 m가 3개, 0.4 m는 4개예요.","0.1이 많을수록 길어요.","0.4 m가 더 길어요."],"variant_rule":{"alt":[{"stem":"가오리연을 만들려고 리본 두 개를 준비했어요. 하나는 0.7 m, 다른 하나는 0.9 m예요. 더 긴 것은 어느 것인가요?","options":[{"t":"0.9 m인 리본","correct":true},{"t":"0.7 m인 리본","mis":"M3-1-u6-X15"},{"t":"두 개의 길이가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.7 m는 0.1 m가 7개, 0.9 m는 9개예요.","0.1이 많을수록 길어요.","0.9 m가 더 길어요."],"asset":null},{"stem":"가오리연을 만들려고 실 두 개를 준비했어요. 하나는 0.7 m, 다른 하나는 0.8 m예요. 더 긴 것은 어느 것인가요?","options":[{"t":"0.8 m인 실","correct":true},{"t":"0.7 m인 실","mis":"M3-1-u6-X15"},{"t":"두 개의 길이가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.7 m는 0.1 m가 7개, 0.8 m는 8개예요.","0.1이 많을수록 길어요.","0.8 m가 더 길어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_challenge#3','math',3,1,'u6','L09','g3_1_math_u6_L09_challenge','lesson_challenge','M3-1-u6-C9',3,'mc','auto','가장 작은 수는 무엇인가요? 0.5, 0.8, 0.7, 0.4',ARRAY['M3-1-u6-X15','M3-1-u6-X18']::text[],true,'{"seq":3,"concept":"M3-1-u6-C9","difficulty":3,"kind":"mc","stem":"가장 작은 수는 무엇인가요? 0.5, 0.8, 0.7, 0.4","options":[{"t":"0.4","correct":true},{"t":"0.5","mis":"M3-1-u6-X15"},{"t":"0.8","mis":"M3-1-u6-X18"},{"t":"0.7","mis":"M3-1-u6-X15"}],"explanation":["0.1의 개수를 견주어요 — 5, 8, 7, 4.","0.1이 가장 적은 소수가 가장 작은 수예요.","0.4예요."],"variant_rule":{"alt":[{"stem":"가장 작은 수는 무엇인가요? 0.9, 0.4, 0.6, 0.5","options":[{"t":"0.4","correct":true},{"t":"0.9","mis":"M3-1-u6-X18"},{"t":"0.6","mis":"M3-1-u6-X15"},{"t":"0.5","mis":"M3-1-u6-X15"}],"explanation":["0.1의 개수를 견주어요 — 9, 4, 6, 5.","0.1이 가장 적은 소수가 가장 작은 수예요.","0.4예요."],"asset":null},{"stem":"가장 작은 수는 무엇인가요? 0.2, 0.3, 0.8, 0.6","options":[{"t":"0.2","correct":true},{"t":"0.3","mis":"M3-1-u6-X15"},{"t":"0.8","mis":"M3-1-u6-X18"},{"t":"0.6","mis":"M3-1-u6-X15"}],"explanation":["0.1의 개수를 견주어요 — 2, 3, 8, 6.","0.1이 가장 적은 소수가 가장 작은 수예요.","0.2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_challenge#4','math',3,1,'u6','L09','g3_1_math_u6_L09_challenge','lesson_challenge','M3-1-u6-C9',3,'sa','auto','0.□는 0.2보다 크고 0.4보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u6-C9","difficulty":3,"kind":"sa","stem":"0.□는 0.2보다 크고 0.4보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["0.1의 개수로 견주어요.","□는 2보다 크고 4보다 작은 수 — 3.","모두 1개예요."],"variant_rule":{"alt":[{"stem":"0.□는 0.3보다 크고 0.7보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["0.1의 개수로 견주어요.","□는 3보다 크고 7보다 작은 수 — 4, 5, 6.","모두 3개예요."],"asset":null},{"stem":"0.□는 0.1보다 크고 0.4보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["0.1의 개수로 견주어요.","□는 1보다 크고 4보다 작은 수 — 2, 3.","모두 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
