INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_challenge#6','math',3,1,'u6','L09','g3_1_math_u6_L09_challenge','lesson_challenge','M3-1-u6-C9',3,'error','auto','소수의 크기 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u6-X16','M3-1-u6-X18']::text[],true,'{"seq":6,"concept":"M3-1-u6-C9","difficulty":3,"kind":"error","stem":"소수의 크기 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「0.2와 ⟨2/10⟩는 크기가 달라」","correct":true,"mis_target":"M3-1-u6-X16"},{"t":"하은 — 「띠에서 더 많이 색칠한 쪽이 커」","mis":"M3-1-u6-X18"},{"t":"도윤 — 「0.3이 0.2보다 커」","mis":"M3-1-u6-X18"}],"explanation":["0.1이 많을수록 큰 소수예요.","0.3 > 0.2, 0.2 = ⟨2/10⟩예요.","태오의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 소수의 크기 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「0.3이 0.5보다 커」","correct":true,"mis_target":"M3-1-u6-X15"},{"t":"지윤 — 「0.5가 0.3보다 커」","mis":"M3-1-u6-X18"},{"t":"서준 — 「0.1이 많을수록 큰 소수야」","mis":"M3-1-u6-X18"}],"explanation":["0.1이 많을수록 큰 소수예요.","0.5 > 0.3, 0.5 = ⟨5/10⟩예요.","태오의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 소수의 크기 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「0.1이 적을수록 큰 소수야」","correct":true,"mis_target":"M3-1-u6-X15"},{"t":"지윤 — 「0.1이 많을수록 큰 소수야」","mis":"M3-1-u6-X18"},{"t":"현우 — 「띠에서 더 많이 색칠한 쪽이 커」","mis":"M3-1-u6-X18"}],"explanation":["0.1이 많을수록 큰 소수예요.","0.6 > 0.3, 0.3 = ⟨3/10⟩이에요.","서준의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_challenge#7','math',3,1,'u6','L09','g3_1_math_u6_L09_challenge','lesson_challenge','M3-1-u6-C9',3,'mc','auto','가장 큰 수는 어느 것인가요?',ARRAY['M3-1-u6-X16','M3-1-u6-X18']::text[],true,'{"seq":7,"concept":"M3-1-u6-C9","difficulty":3,"kind":"mc","stem":"가장 큰 수는 어느 것인가요?","options":[{"t":"⟨1/10⟩이 9개인 수","correct":true},{"t":"0.8","mis":"M3-1-u6-X16"},{"t":"⟨7/10⟩","mis":"M3-1-u6-X16"},{"t":"0.1이 2개인 수","mis":"M3-1-u6-X18"}],"explanation":["모두 0.1(=⟨1/10⟩)이 몇 개인지로 바꾸어요.","8개, 7개, 2개, 9개예요.","가장 많은 것은 ⟨1/10⟩이 9개인 수예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 가장 큰 수는 어느 것인가요?","options":[{"t":"⟨9/10⟩","correct":true},{"t":"0.3","mis":"M3-1-u6-X18"},{"t":"0.1이 4개인 수","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩이 7개인 수","mis":"M3-1-u6-X16"}],"explanation":["모두 0.1(=⟨1/10⟩)이 몇 개인지로 바꾸어요.","3개, 9개, 4개, 7개예요.","가장 많은 것은 ⟨9/10⟩예요."],"asset":null},{"stem":"이번에는 다른 문제예요. 가장 큰 수는 어느 것인가요?","options":[{"t":"0.1이 8개인 수","correct":true},{"t":"0.2","mis":"M3-1-u6-X16"},{"t":"⟨6/10⟩","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩이 1개인 수","mis":"M3-1-u6-X18"}],"explanation":["모두 0.1(=⟨1/10⟩)이 몇 개인지로 바꾸어요.","2개, 6개, 8개, 1개예요.","가장 많은 것은 0.1이 8개인 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_challenge#8','math',3,1,'u6','L09','g3_1_math_u6_L09_challenge','lesson_challenge','M3-1-u6-C9',4,'essay','teacher','가오리연의 대나무 살 두 개가 0.4 m와 0.6 m예요. 어느 것이 더 긴지 세 가지 방법(0.1의 개수, 띠 그림, 분수로 바꾸기) 중 두 가지 이상으로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u6-C9","difficulty":4,"kind":"essay","stem":"가오리연의 대나무 살 두 개가 0.4 m와 0.6 m예요. 어느 것이 더 긴지 세 가지 방법(0.1의 개수, 띠 그림, 분수로 바꾸기) 중 두 가지 이상으로 설명해 보세요.","answer_guide":{"answer":"예: ① 0.4는 0.1이 4개, 0.6은 6개이므로 0.6이 크다. ② 같은 길이 띠를 10칸으로 나누어 4칸과 6칸을 색칠하면 6칸이 더 길다. ③ 0.4 = ⟨4/10⟩, 0.6 = ⟨6/10⟩이고 분모가 같으니 분자가 큰 0.6이 크다. 그래서 0.6 m 살이 더 길다.","scoring_points":["0.6 m가 더 길다고 답했는가","두 가지 이상의 방법으로 설명했는가","각 방법의 근거(0.1 개수·띠·분자)가 맞는가"]},"explanation":["0.1이 4개 < 6개.","⟨4/10⟩ < ⟨6/10⟩.","0.6 m가 더 길어요."],"asset":{"type":"fbar","bars":[{"den":10,"num":4},{"den":10,"num":6}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L09_challenge#9','math',3,1,'u6','L09','g3_1_math_u6_L09_challenge','lesson_challenge','M3-1-u6-C9',4,'essay','teacher','태오가 「0.7이 0.9보다 커.」라고 했어요. 태오의 말이 맞는지 판단하고 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u6-C9","difficulty":4,"kind":"essay","stem":"태오가 「0.7이 0.9보다 커.」라고 했어요. 태오의 말이 맞는지 판단하고 까닭을 써 보세요.","answer_guide":{"answer":"예: 틀렸다. 0.7은 0.1이 7개, 0.9는 0.1이 9개이다. 0.1의 개수가 많을수록 큰 소수이므로 0.9가 0.7보다 크다.","scoring_points":["틀렸다고 판단했는가","0.1의 개수로 견주었는가","0.9 > 0.7이라고 바르게 썼는가"]},"explanation":["0.7 = 0.1이 7개.","0.9 = 0.1이 9개.","0.9 > 0.7."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
