INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L10_basic#3','math',3,1,'u6','L10','g3_1_math_u6_L10_basic','lesson_basic','M3-1-u6-C10',1,'sa','auto','⟨1/3⟩이 몇 개 모이면 전체가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u6-C10","difficulty":1,"kind":"sa","stem":"⟨1/3⟩이 몇 개 모이면 전체가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨1/3⟩은 전체를 똑같이 3칸으로 나눈 한 칸이에요.","한 칸이 3개 모이면 전체예요.","단위분수는 분모만큼 모이면 전체 — 3개."],"variant_rule":{"alt":[{"stem":"⟨1/7⟩이 몇 개 모이면 전체가 되나요? 숫자로 쓰세요.","answer":["7"],"explanation":["⟨1/7⟩은 전체를 똑같이 7칸으로 나눈 한 칸이에요.","한 칸이 7개 모이면 전체예요.","단위분수는 분모만큼 모이면 전체 — 7개."],"asset":null},{"stem":"⟨1/4⟩이 몇 개 모이면 전체가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨1/4⟩은 전체를 똑같이 4칸으로 나눈 한 칸이에요.","한 칸이 4개 모이면 전체예요.","단위분수는 분모만큼 모이면 전체 — 4개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L10_basic#4','math',3,1,'u6','L10','g3_1_math_u6_L10_basic','lesson_basic','M3-1-u6-C10',1,'mc','auto','⟨2/3⟩만큼인 부분이 있어요. 전체가 되려면 ⟨1/3⟩이 몇 개 더 있어야 하나요?',ARRAY['M3-1-u6-X07','M3-1-u6-X04']::text[],true,'{"seq":4,"concept":"M3-1-u6-C10","difficulty":1,"kind":"mc","stem":"⟨2/3⟩만큼인 부분이 있어요. 전체가 되려면 ⟨1/3⟩이 몇 개 더 있어야 하나요?","options":[{"t":"1개","correct":true},{"t":"3개","mis":"M3-1-u6-X07"},{"t":"2개","mis":"M3-1-u6-X04"},{"t":"0개","mis":"M3-1-u6-X07"}],"explanation":["⟨2/3⟩는 ⟨1/3⟩이 2개예요.","전체가 되려면 ⟨1/3⟩이 3개 있어야 해요.","3 − 2 = 1개 더 필요해요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩만큼인 부분이 있어요. 전체가 되려면 ⟨1/4⟩이 몇 개 더 있어야 하나요?","options":[{"t":"1개","correct":true},{"t":"4개","mis":"M3-1-u6-X07"},{"t":"3개","mis":"M3-1-u6-X04"},{"t":"2개","mis":"M3-1-u6-X19"}],"explanation":["⟨3/4⟩은 ⟨1/4⟩이 3개예요.","전체가 되려면 ⟨1/4⟩이 4개 있어야 해요.","4 − 3 = 1개 더 필요해요."],"asset":null},{"stem":"⟨4/5⟩만큼인 부분이 있어요. 전체가 되려면 ⟨1/5⟩이 몇 개 더 있어야 하나요?","options":[{"t":"1개","correct":true},{"t":"5개","mis":"M3-1-u6-X07"},{"t":"4개","mis":"M3-1-u6-X04"},{"t":"2개","mis":"M3-1-u6-X19"}],"explanation":["⟨4/5⟩는 ⟨1/5⟩이 4개예요.","전체가 되려면 ⟨1/5⟩이 5개 있어야 해요.","5 − 4 = 1개 더 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
