INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L10_basic#7','math',3,1,'u6','L10','g3_1_math_u6_L10_basic','lesson_basic','M3-1-u6-C10',2,'mc','auto','길이가 12 cm인 띠는 똑같이 4칸, 6 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/4⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?',ARRAY['M3-1-u6-X11','M3-1-u6-X10','M3-1-u6-X20']::text[],true,'{"seq":7,"concept":"M3-1-u6-C10","difficulty":2,"kind":"mc","stem":"길이가 12 cm인 띠는 똑같이 4칸, 6 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/4⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"두 조각의 크기가 같아요","correct":true},{"t":"긴 띠의 ⟨1/4⟩이 커요","mis":"M3-1-u6-X11"},{"t":"짧은 띠의 ⟨1/2⟩이 커요","mis":"M3-1-u6-X10"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 12 ÷ 4 = 3 cm, 짧은 띠 한 칸은 6 ÷ 2 = 3 cm예요.","두 조각의 크기가 같아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1.5,0],[1.5,0.9],[0,0.9]],"hi":true},{"p":[[1.5,0],[3,0],[3,0.9],[1.5,0.9]]},{"p":[[3,0],[4.5,0],[4.5,0.9],[3,0.9]]},{"p":[[4.5,0],[6,0],[6,0.9],[4.5,0.9]]},{"p":[[6.9,0],[8.4,0],[8.4,0.9],[6.9,0.9]],"hi":true},{"p":[[8.4,0],[9.9,0],[9.9,0.9],[8.4,0.9]]}],"u":30},"variant_rule":{"alt":[{"stem":"길이가 12 cm인 띠는 똑같이 4칸, 6 cm인 띠는 똑같이 3칸으로 나누었어요. 긴 띠의 ⟨1/4⟩과 짧은 띠의 ⟨1/3⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"긴 띠의 ⟨1/4⟩이 커요","correct":true},{"t":"짧은 띠의 ⟨1/3⟩이 커요","mis":"M3-1-u6-X10"},{"t":"두 조각의 크기가 같아요","mis":"M3-1-u6-X11"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 12 ÷ 4 = 3 cm, 짧은 띠 한 칸은 6 ÷ 3 = 2 cm예요.","긴 띠의 ⟨1/4⟩이 커요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1.5,0],[1.5,0.9],[0,0.9]],"hi":true},{"p":[[1.5,0],[3,0],[3,0.9],[1.5,0.9]]},{"p":[[3,0],[4.5,0],[4.5,0.9],[3,0.9]]},{"p":[[4.5,0],[6,0],[6,0.9],[4.5,0.9]]},{"p":[[6.9,0],[7.9,0],[7.9,0.9],[6.9,0.9]],"hi":true},{"p":[[7.9,0],[8.9,0],[8.9,0.9],[7.9,0.9]]},{"p":[[8.9,0],[9.9,0],[9.9,0.9],[8.9,0.9]]}],"u":30}},{"stem":"길이가 12 cm인 띠는 똑같이 6칸, 6 cm인 띠는 똑같이 3칸으로 나누었어요. 긴 띠의 ⟨1/6⟩과 짧은 띠의 ⟨1/3⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"두 조각의 크기가 같아요","correct":true},{"t":"긴 띠의 ⟨1/6⟩이 커요","mis":"M3-1-u6-X11"},{"t":"짧은 띠의 ⟨1/3⟩이 커요","mis":"M3-1-u6-X10"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 12 ÷ 6 = 2 cm, 짧은 띠 한 칸은 6 ÷ 3 = 2 cm예요.","두 조각의 크기가 같아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,0.9],[0,0.9]],"hi":true},{"p":[[1,0],[2,0],[2,0.9],[1,0.9]]},{"p":[[2,0],[3,0],[3,0.9],[2,0.9]]},{"p":[[3,0],[4,0],[4,0.9],[3,0.9]]},{"p":[[4,0],[5,0],[5,0.9],[4,0.9]]},{"p":[[5,0],[6,0],[6,0.9],[5,0.9]]},{"p":[[6.9,0],[7.9,0],[7.9,0.9],[6.9,0.9]],"hi":true},{"p":[[7.9,0],[8.9,0],[8.9,0.9],[7.9,0.9]]},{"p":[[8.9,0],[9.9,0],[9.9,0.9],[8.9,0.9]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L10_basic#8','math',3,1,'u6','L10','g3_1_math_u6_L10_basic','lesson_basic','M3-1-u6-C10',2,'error','auto','전체와 부분을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u6-X11','M3-1-u6-X18']::text[],true,'{"seq":8,"concept":"M3-1-u6-C10","difficulty":2,"kind":"error","stem":"전체와 부분을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「큰 피자의 ⟨1/8⟩이 작은 피자의 ⟨1/8⟩보다 작아」","correct":true,"mis_target":"M3-1-u6-X11"},{"t":"나래 — 「⟨1/8⟩이 8개면 전체야」","mis":"M3-1-u6-X18"},{"t":"지윤 — 「분수는 어떤 전체인지와 함께 봐야 해」","mis":"M3-1-u6-X18"}],"explanation":["같은 분수라도 전체가 크면 부분도 커요.","⟨1/8⟩이 8개 모이면 전체예요.","현우의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 전체와 부분을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하은 — 「⟨1/7⟩이 8개면 전체야」","correct":true,"mis_target":"M3-1-u6-X19"},{"t":"도윤 — 「분수는 어떤 전체인지와 함께 봐야 해」","mis":"M3-1-u6-X18"},{"t":"나래 — 「전체가 크면 ⟨1/7⟩도 커」","mis":"M3-1-u6-X18"}],"explanation":["같은 분수라도 전체가 크면 부분도 커요.","⟨1/7⟩이 7개 모이면 전체예요.","하은의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 전체와 부분을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「전체가 달라도 ⟨1/5⟩은 늘 같아」","correct":true,"mis_target":"M3-1-u6-X11"},{"t":"서준 — 「전체가 크면 ⟨1/5⟩도 커」","mis":"M3-1-u6-X18"},{"t":"민서 — 「⟨1/5⟩이 5개면 전체야」","mis":"M3-1-u6-X18"}],"explanation":["같은 분수라도 전체가 크면 부분도 커요.","⟨1/5⟩이 5개 모이면 전체예요.","도윤의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L10_basic#9','math',3,1,'u6','L10','g3_1_math_u6_L10_basic','lesson_basic','M3-1-u6-C10',2,'sa','auto','색칠한 그림은 전체의 ⟨1/5⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u6-C10","difficulty":2,"kind":"sa","stem":"색칠한 그림은 전체의 ⟨1/5⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["그림은 작은 칸 1개이고 전체의 ⟨1/5⟩이에요.","이 조각이 5개 모여야 전체예요.","전체는 ⟨1/5⟩이 5개 — 작은 칸 1 × 5 = 5개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true}]},"variant_rule":{"alt":[{"stem":"색칠한 그림은 전체의 ⟨1/2⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["그림은 작은 칸 1개이고 전체의 ⟨1/2⟩이에요.","이 조각이 2개 모여야 전체예요.","전체는 ⟨1/2⟩이 2개 — 작은 칸 1 × 2 = 2개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true}]}},{"stem":"색칠한 그림은 전체의 ⟨1/2⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["그림은 작은 칸 4개이고 전체의 ⟨1/2⟩이에요.","이 조각이 2개 모여야 전체예요.","전체는 ⟨1/2⟩이 2개 — 작은 칸 4 × 2 = 8개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L10_basic#10','math',3,1,'u6','L10','g3_1_math_u6_L10_basic','lesson_basic','M3-1-u6-C10',3,'sa','auto','색칠한 그림은 전체의 ⟨2/5⟩예요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u6-C10","difficulty":3,"kind":"sa","stem":"색칠한 그림은 전체의 ⟨2/5⟩예요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["그림은 작은 칸 6개이고 전체의 ⟨2/5⟩예요.","⟨1/5⟩ 한 개는 작은 칸 6 ÷ 2 = 3개예요.","전체는 ⟨1/5⟩이 5개 — 작은 칸 3 × 5 = 15개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true}]},"variant_rule":{"alt":[{"stem":"색칠한 그림은 전체의 ⟨2/4⟩예요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["그림은 작은 칸 2개이고 전체의 ⟨2/4⟩예요.","⟨1/4⟩ 한 개는 작은 칸 2 ÷ 2 = 1개예요.","전체는 ⟨1/4⟩이 4개 — 작은 칸 1 × 4 = 4개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true}]}},{"stem":"색칠한 그림은 전체의 ⟨2/6⟩예요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["그림은 작은 칸 4개이고 전체의 ⟨2/6⟩예요.","⟨1/6⟩ 한 개는 작은 칸 4 ÷ 2 = 2개예요.","전체는 ⟨1/6⟩이 6개 — 작은 칸 2 × 6 = 12개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
