INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L10_challenge#2','math',3,1,'u6','L10','g3_1_math_u6_L10_challenge','lesson_challenge','M3-1-u6-C10',2,'sa','auto','⟨3/6⟩만큼인 부분이 있어요. 전체가 되려면 ⟨1/6⟩이 몇 개 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u6-C10","difficulty":2,"kind":"sa","stem":"⟨3/6⟩만큼인 부분이 있어요. 전체가 되려면 ⟨1/6⟩이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨3/6⟩은 ⟨1/6⟩이 3개예요.","전체가 되려면 ⟨1/6⟩이 6개 있어야 해요.","6 − 3 = 3개 더 필요해요."],"variant_rule":{"alt":[{"stem":"⟨7/11⟩만큼인 부분이 있어요. 전체가 되려면 ⟨1/11⟩이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨7/11⟩은 ⟨1/11⟩이 7개예요.","전체가 되려면 ⟨1/11⟩이 11개 있어야 해요.","11 − 7 = 4개 더 필요해요."],"asset":null},{"stem":"⟨5/8⟩만큼인 부분이 있어요. 전체가 되려면 ⟨1/8⟩이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨5/8⟩는 ⟨1/8⟩이 5개예요.","전체가 되려면 ⟨1/8⟩이 8개 있어야 해요.","8 − 5 = 3개 더 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L10_challenge#3','math',3,1,'u6','L10','g3_1_math_u6_L10_challenge','lesson_challenge','M3-1-u6-C10',3,'mc','auto','길이가 12 cm인 띠는 똑같이 6칸, 6 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/6⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?',ARRAY['M3-1-u6-X11','M3-1-u6-X20']::text[],true,'{"seq":3,"concept":"M3-1-u6-C10","difficulty":3,"kind":"mc","stem":"길이가 12 cm인 띠는 똑같이 6칸, 6 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/6⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"짧은 띠의 ⟨1/2⟩이 커요","correct":true},{"t":"긴 띠의 ⟨1/6⟩이 커요","mis":"M3-1-u6-X11"},{"t":"두 조각의 크기가 같아요","mis":"M3-1-u6-X11"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 12 ÷ 6 = 2 cm, 짧은 띠 한 칸은 6 ÷ 2 = 3 cm예요.","짧은 띠의 ⟨1/2⟩이 커요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,0.9],[0,0.9]],"hi":true},{"p":[[1,0],[2,0],[2,0.9],[1,0.9]]},{"p":[[2,0],[3,0],[3,0.9],[2,0.9]]},{"p":[[3,0],[4,0],[4,0.9],[3,0.9]]},{"p":[[4,0],[5,0],[5,0.9],[4,0.9]]},{"p":[[5,0],[6,0],[6,0.9],[5,0.9]]},{"p":[[6.9,0],[8.4,0],[8.4,0.9],[6.9,0.9]],"hi":true},{"p":[[8.4,0],[9.9,0],[9.9,0.9],[8.4,0.9]]}],"u":30},"variant_rule":{"alt":[{"stem":"길이가 8 cm인 띠는 똑같이 4칸, 4 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/4⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"두 조각의 크기가 같아요","correct":true},{"t":"긴 띠의 ⟨1/4⟩이 커요","mis":"M3-1-u6-X11"},{"t":"짧은 띠의 ⟨1/2⟩이 커요","mis":"M3-1-u6-X10"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 8 ÷ 4 = 2 cm, 짧은 띠 한 칸은 4 ÷ 2 = 2 cm예요.","두 조각의 크기가 같아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,0.9],[0,0.9]],"hi":true},{"p":[[1,0],[2,0],[2,0.9],[1,0.9]]},{"p":[[2,0],[3,0],[3,0.9],[2,0.9]]},{"p":[[3,0],[4,0],[4,0.9],[3,0.9]]},{"p":[[4.9,0],[5.9,0],[5.9,0.9],[4.9,0.9]],"hi":true},{"p":[[5.9,0],[6.9,0],[6.9,0.9],[5.9,0.9]]}]}},{"stem":"길이가 12 cm인 띠는 똑같이 3칸, 8 cm인 띠는 똑같이 4칸으로 나누었어요. 긴 띠의 ⟨1/3⟩과 짧은 띠의 ⟨1/4⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"긴 띠의 ⟨1/3⟩이 커요","correct":true},{"t":"짧은 띠의 ⟨1/4⟩이 커요","mis":"M3-1-u6-X11"},{"t":"두 조각의 크기가 같아요","mis":"M3-1-u6-X11"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 12 ÷ 3 = 4 cm, 짧은 띠 한 칸은 8 ÷ 4 = 2 cm예요.","긴 띠의 ⟨1/3⟩이 커요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[2,0],[2,0.9],[0,0.9]],"hi":true},{"p":[[2,0],[4,0],[4,0.9],[2,0.9]]},{"p":[[4,0],[6,0],[6,0.9],[4,0.9]]},{"p":[[6.9,0],[7.9,0],[7.9,0.9],[6.9,0.9]],"hi":true},{"p":[[7.9,0],[8.9,0],[8.9,0.9],[7.9,0.9]]},{"p":[[8.9,0],[9.9,0],[9.9,0.9],[8.9,0.9]]},{"p":[[9.9,0],[10.9,0],[10.9,0.9],[9.9,0.9]]}],"u":27}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L10_challenge#4','math',3,1,'u6','L10','g3_1_math_u6_L10_challenge','lesson_challenge','M3-1-u6-C10',3,'sa','auto','색칠한 그림은 전체의 ⟨2/6⟩예요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u6-C10","difficulty":3,"kind":"sa","stem":"색칠한 그림은 전체의 ⟨2/6⟩예요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["그림은 작은 칸 6개이고 전체의 ⟨2/6⟩예요.","⟨1/6⟩ 한 개는 작은 칸 6 ÷ 2 = 3개예요.","전체는 ⟨1/6⟩이 6개 — 작은 칸 3 × 6 = 18개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true}]},"variant_rule":{"alt":[{"stem":"색칠한 그림은 전체의 ⟨2/3⟩예요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["그림은 작은 칸 6개이고 전체의 ⟨2/3⟩예요.","⟨1/3⟩ 한 개는 작은 칸 6 ÷ 2 = 3개예요.","전체는 ⟨1/3⟩이 3개 — 작은 칸 3 × 3 = 9개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true}]}},{"stem":"색칠한 그림은 전체의 ⟨2/3⟩예요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["그림은 작은 칸 4개이고 전체의 ⟨2/3⟩예요.","⟨1/3⟩ 한 개는 작은 칸 4 ÷ 2 = 2개예요.","전체는 ⟨1/3⟩이 3개 — 작은 칸 2 × 3 = 6개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L10_challenge#5','math',3,1,'u6','L10','g3_1_math_u6_L10_challenge','lesson_challenge','M3-1-u6-C10',3,'error','auto','전체와 부분을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u6-X19','M3-1-u6-X18']::text[],true,'{"seq":5,"concept":"M3-1-u6-C10","difficulty":3,"kind":"error","stem":"전체와 부분을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「⟨1/5⟩이 6개면 전체야」","correct":true,"mis_target":"M3-1-u6-X19"},{"t":"하은 — 「분수는 어떤 전체인지와 함께 봐야 해」","mis":"M3-1-u6-X18"},{"t":"서준 — 「전체가 크면 ⟨1/5⟩도 커」","mis":"M3-1-u6-X18"}],"explanation":["같은 분수라도 전체가 크면 부분도 커요.","⟨1/5⟩이 5개 모이면 전체예요.","태오의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 전체와 부분을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지윤 — 「전체가 달라도 ⟨1/4⟩은 늘 같아」","correct":true,"mis_target":"M3-1-u6-X11"},{"t":"지유 — 「전체가 크면 ⟨1/4⟩도 커」","mis":"M3-1-u6-X18"},{"t":"도윤 — 「⟨1/4⟩이 4개면 전체야」","mis":"M3-1-u6-X18"}],"explanation":["같은 분수라도 전체가 크면 부분도 커요.","⟨1/4⟩이 4개 모이면 전체예요.","지윤의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 전체와 부분을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「큰 피자의 ⟨1/9⟩이 작은 피자의 ⟨1/9⟩보다 작아」","correct":true,"mis_target":"M3-1-u6-X11"},{"t":"서준 — 「⟨1/9⟩이 9개면 전체야」","mis":"M3-1-u6-X18"},{"t":"지윤 — 「분수는 어떤 전체인지와 함께 봐야 해」","mis":"M3-1-u6-X18"}],"explanation":["같은 분수라도 전체가 크면 부분도 커요.","⟨1/9⟩이 9개 모이면 전체예요.","지유의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
