INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L10_challenge#7','math',3,1,'u6','L10','g3_1_math_u6_L10_challenge','lesson_challenge','M3-1-u6-C10',3,'mc','auto','길이가 12 cm인 띠는 똑같이 6칸, 8 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/6⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?',ARRAY['M3-1-u6-X11','M3-1-u6-X20']::text[],true,'{"seq":7,"concept":"M3-1-u6-C10","difficulty":3,"kind":"mc","stem":"길이가 12 cm인 띠는 똑같이 6칸, 8 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/6⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"짧은 띠의 ⟨1/2⟩이 커요","correct":true},{"t":"긴 띠의 ⟨1/6⟩이 커요","mis":"M3-1-u6-X11"},{"t":"두 조각의 크기가 같아요","mis":"M3-1-u6-X11"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 12 ÷ 6 = 2 cm, 짧은 띠 한 칸은 8 ÷ 2 = 4 cm예요.","짧은 띠의 ⟨1/2⟩이 커요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,0.9],[0,0.9]],"hi":true},{"p":[[1,0],[2,0],[2,0.9],[1,0.9]]},{"p":[[2,0],[3,0],[3,0.9],[2,0.9]]},{"p":[[3,0],[4,0],[4,0.9],[3,0.9]]},{"p":[[4,0],[5,0],[5,0.9],[4,0.9]]},{"p":[[5,0],[6,0],[6,0.9],[5,0.9]]},{"p":[[6.9,0],[8.9,0],[8.9,0.9],[6.9,0.9]],"hi":true},{"p":[[8.9,0],[10.9,0],[10.9,0.9],[8.9,0.9]]}],"u":27},"variant_rule":{"alt":[{"stem":"길이가 12 cm인 띠는 똑같이 4칸, 6 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/4⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"두 조각의 크기가 같아요","correct":true},{"t":"긴 띠의 ⟨1/4⟩이 커요","mis":"M3-1-u6-X11"},{"t":"짧은 띠의 ⟨1/2⟩이 커요","mis":"M3-1-u6-X10"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 12 ÷ 4 = 3 cm, 짧은 띠 한 칸은 6 ÷ 2 = 3 cm예요.","두 조각의 크기가 같아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1.5,0],[1.5,0.9],[0,0.9]],"hi":true},{"p":[[1.5,0],[3,0],[3,0.9],[1.5,0.9]]},{"p":[[3,0],[4.5,0],[4.5,0.9],[3,0.9]]},{"p":[[4.5,0],[6,0],[6,0.9],[4.5,0.9]]},{"p":[[6.9,0],[8.4,0],[8.4,0.9],[6.9,0.9]],"hi":true},{"p":[[8.4,0],[9.9,0],[9.9,0.9],[8.4,0.9]]}],"u":30}},{"stem":"길이가 12 cm인 띠는 똑같이 6칸, 6 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/6⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"짧은 띠의 ⟨1/2⟩이 커요","correct":true},{"t":"긴 띠의 ⟨1/6⟩이 커요","mis":"M3-1-u6-X11"},{"t":"두 조각의 크기가 같아요","mis":"M3-1-u6-X11"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 12 ÷ 6 = 2 cm, 짧은 띠 한 칸은 6 ÷ 2 = 3 cm예요.","짧은 띠의 ⟨1/2⟩이 커요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,0.9],[0,0.9]],"hi":true},{"p":[[1,0],[2,0],[2,0.9],[1,0.9]]},{"p":[[2,0],[3,0],[3,0.9],[2,0.9]]},{"p":[[3,0],[4,0],[4,0.9],[3,0.9]]},{"p":[[4,0],[5,0],[5,0.9],[4,0.9]]},{"p":[[5,0],[6,0],[6,0.9],[5,0.9]]},{"p":[[6.9,0],[8.4,0],[8.4,0.9],[6.9,0.9]],"hi":true},{"p":[[8.4,0],[9.9,0],[9.9,0.9],[8.4,0.9]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L10_challenge#8','math',3,1,'u6','L10','g3_1_math_u6_L10_challenge','lesson_challenge','M3-1-u6-C10',4,'essay','teacher','지윤이와 현우가 각각 피자의 ⟨1/4⟩을 먹었는데, 현우가 먹은 조각이 더 컸어요. 같은 ⟨1/4⟩인데 왜 크기가 다른지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u6-C10","difficulty":4,"kind":"essay","stem":"지윤이와 현우가 각각 피자의 ⟨1/4⟩을 먹었는데, 현우가 먹은 조각이 더 컸어요. 같은 ⟨1/4⟩인데 왜 크기가 다른지 설명해 보세요.","answer_guide":{"answer":"예: 분수는 전체를 똑같이 나눈 것 중의 몇이다. 현우가 먹은 피자가 지윤이의 피자보다 더 크기 때문에, 같은 ⟨1/4⟩이라도 현우의 조각이 더 크다. 분수는 어떤 전체인지와 함께 봐야 한다.","scoring_points":["전체(피자)의 크기가 다르다고 썼는가","같은 분수라도 전체가 크면 부분도 크다고 썼는가","분수는 전체와 함께 봐야 한다고 정리했는가"]},"explanation":["두 피자의 크기가 달라요.","큰 전체의 ⟨1/4⟩이 더 커요.","전체를 함께 봐야 해요."],"asset":{"type":"tiles","pieces":[{"p":[[1,1],[1,0],[1.105,0.005],[1.208,0.022],[1.309,0.049],[1.407,0.086],[1.5,0.134],[1.588,0.191],[1.669,0.257],[1.743,0.331],[1.809,0.412],[1.866,0.5],[1.914,0.593],[1.951,0.691],[1.978,0.792],[1.995,0.895],[2,1]],"hi":true},{"p":[[1,1],[2,1],[1.995,1.105],[1.978,1.208],[1.951,1.309],[1.914,1.407],[1.866,1.5],[1.809,1.588],[1.743,1.669],[1.669,1.743],[1.588,1.809],[1.5,1.866],[1.407,1.914],[1.309,1.951],[1.208,1.978],[1.105,1.995],[1,2]]},{"p":[[1,1],[1,2],[0.895,1.995],[0.792,1.978],[0.691,1.951],[0.593,1.914],[0.5,1.866],[0.412,1.809],[0.331,1.743],[0.257,1.669],[0.191,1.588],[0.134,1.5],[0.086,1.407],[0.049,1.309],[0.022,1.208],[0.005,1.105],[0,1]]},{"p":[[1,1],[0,1],[0.005,0.895],[0.022,0.792],[0.049,0.691],[0.086,0.593],[0.134,0.5],[0.191,0.412],[0.257,0.331],[0.331,0.257],[0.412,0.191],[0.5,0.134],[0.593,0.086],[0.691,0.049],[0.792,0.022],[0.895,0.005],[1,0]]},{"p":[[4.5,1.6],[4.5,0],[4.667,0.009],[4.833,0.035],[4.994,0.078],[5.151,0.138],[5.3,0.214],[5.44,0.306],[5.571,0.411],[5.689,0.529],[5.794,0.66],[5.886,0.8],[5.962,0.949],[6.022,1.106],[6.065,1.267],[6.091,1.433],[6.1,1.6]],"hi":true},{"p":[[4.5,1.6],[6.1,1.6],[6.091,1.767],[6.065,1.933],[6.022,2.094],[5.962,2.251],[5.886,2.4],[5.794,2.54],[5.689,2.671],[5.571,2.789],[5.44,2.894],[5.3,2.986],[5.151,3.062],[4.994,3.122],[4.833,3.165],[4.667,3.191],[4.5,3.2]]},{"p":[[4.5,1.6],[4.5,3.2],[4.333,3.191],[4.167,3.165],[4.006,3.122],[3.849,3.062],[3.7,2.986],[3.56,2.894],[3.429,2.789],[3.311,2.671],[3.206,2.54],[3.114,2.4],[3.038,2.251],[2.978,2.094],[2.935,1.933],[2.909,1.767],[2.9,1.6]]},{"p":[[4.5,1.6],[2.9,1.6],[2.909,1.433],[2.935,1.267],[2.978,1.106],[3.038,0.949],[3.114,0.8],[3.206,0.66],[3.311,0.529],[3.429,0.411],[3.56,0.306],[3.7,0.214],[3.849,0.138],[4.006,0.078],[4.167,0.035],[4.333,0.009],[4.5,0]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L10_challenge#9','math',3,1,'u6','L10','g3_1_math_u6_L10_challenge','lesson_challenge','M3-1-u6-C10',4,'essay','teacher','⟨3/5⟩만큼인 부분이 있어요. 이 부분을 보고 전체를 완성하려면 ⟨1/5⟩이 몇 개 더 필요한지 구하고, 그 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u6-C10","difficulty":4,"kind":"essay","stem":"⟨3/5⟩만큼인 부분이 있어요. 이 부분을 보고 전체를 완성하려면 ⟨1/5⟩이 몇 개 더 필요한지 구하고, 그 방법을 설명해 보세요.","answer_guide":{"answer":"예: ⟨3/5⟩은 ⟨1/5⟩이 3개이다. 전체가 되려면 ⟨1/5⟩이 분모만큼, 곧 5개 있어야 하므로 5 − 3 = 2개가 더 필요하다. 부분을 셋으로 똑같이 나누어 한 조각(⟨1/5⟩)을 알아낸 뒤 2개를 더 이어 붙인다.","scoring_points":["⟨3/5⟩은 ⟨1/5⟩이 3개라고 썼는가","전체는 ⟨1/5⟩이 5개라고 썼는가","2개 더 필요하다고 구했는가"]},"explanation":["⟨3/5⟩ = ⟨1/5⟩이 3개.","전체 = 5개.","2개 더 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_L10_challenge#10','math',3,1,'u6','L10','g3_1_math_u6_L10_challenge','lesson_challenge','M3-1-u6-C10',4,'sa','auto','색칠한 그림은 전체의 ⟨3/4⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u6-C10","difficulty":4,"kind":"sa","stem":"색칠한 그림은 전체의 ⟨3/4⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["그림은 작은 칸 3개이고 전체의 ⟨3/4⟩이에요.","⟨1/4⟩ 한 개는 작은 칸 3 ÷ 3 = 1개예요.","전체는 ⟨1/4⟩이 4개 — 작은 칸 1 × 4 = 4개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true}]},"variant_rule":{"alt":[{"stem":"색칠한 그림은 전체의 ⟨3/5⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["그림은 작은 칸 6개이고 전체의 ⟨3/5⟩이에요.","⟨1/5⟩ 한 개는 작은 칸 6 ÷ 3 = 2개예요.","전체는 ⟨1/5⟩이 5개 — 작은 칸 2 × 5 = 10개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true}]}},{"stem":"색칠한 그림은 전체의 ⟨3/5⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["그림은 작은 칸 9개이고 전체의 ⟨3/5⟩이에요.","⟨1/5⟩ 한 개는 작은 칸 9 ÷ 3 = 3개예요.","전체는 ⟨1/5⟩이 5개 — 작은 칸 3 × 5 = 15개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2,1],[3,1],[3,2],[2,2]],"hi":true},{"p":[[3,1],[4,1],[4,2],[3,2]],"hi":true},{"p":[[0,2],[1,2],[1,3],[0,3]],"hi":true}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
