INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#8','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C9',1,'mc','auto','0.7과 0.8 중 더 큰 수는 무엇인가요?',ARRAY['M3-1-u6-X15','M3-1-u6-X20']::text[],true,'{"seq":8,"concept":"M3-1-u6-C9","difficulty":1,"kind":"mc","stem":"0.7과 0.8 중 더 큰 수는 무엇인가요?","options":[{"t":"0.8","correct":true},{"t":"0.7","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.7은 0.1이 7개, 0.8은 0.1이 8개예요.","0.1의 개수가 많을수록 큰 소수예요.","7 < 8 — 0.7 < 0.8."],"variant_rule":{"alt":[{"stem":"0.9와 0.4 중 더 큰 수는 무엇인가요?","options":[{"t":"0.9","correct":true},{"t":"0.4","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.9는 0.1이 9개, 0.4는 0.1이 4개예요.","0.1의 개수가 많을수록 큰 소수예요.","9 > 4 — 0.9 > 0.4."],"asset":null},{"stem":"0.2와 0.6 중 더 큰 수는 무엇인가요?","options":[{"t":"0.6","correct":true},{"t":"0.2","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.2는 0.1이 2개, 0.6은 0.1이 6개예요.","0.1의 개수가 많을수록 큰 소수예요.","2 < 6 — 0.2 < 0.6."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#9','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C1',2,'ox','auto','이 도형은 똑같이 둘로 나누어졌어요.',ARRAY['M3-1-u6-X01']::text[],true,'{"seq":9,"concept":"M3-1-u6-C1","difficulty":2,"kind":"ox","stem":"이 도형은 똑같이 둘로 나누어졌어요.","answer":"X","reason_options":[{"t":"조각의 크기가 서로 달라서","correct":true},{"t":"조각이 2개라서","mis":"M3-1-u6-X01"}],"mis":"M3-1-u6-X01","explanation":["조각은 2개지만 크기가 서로 달라요.","겹쳐 보면 꼭 맞지 않아요.","조각 수만 같다고 똑같이 나눈 것이 아니에요 — ×."],"asset":{"type":"tiles","pieces":[{"p":[[0,2],[0.6,2],[1,0]]},{"p":[[0.6,2],[2,2],[1,0]]}]},"variant_rule":{"alt":[{"stem":"이 도형은 똑같이 나누어졌어요.","answer":"O","reason_options":[{"t":"조각의 모양과 크기가 모두 같아서","correct":true},{"t":"조각 수만 세면 되어서","mis":"M3-1-u6-X01"}],"explanation":["조각을 겹쳐 보면 모양과 크기가 꼭 맞아요.","9조각의 크기가 모두 같아요.","그래서 똑같이 나눈 거예요 — ○."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[0.8,0],[0.8,0.8],[0,0.8]]},{"p":[[0.8,0],[1.6,0],[1.6,0.8],[0.8,0.8]]},{"p":[[1.6,0],[2.4,0],[2.4,0.8],[1.6,0.8]]},{"p":[[0,0.8],[0.8,0.8],[0.8,1.6],[0,1.6]]},{"p":[[0.8,0.8],[1.6,0.8],[1.6,1.6],[0.8,1.6]]},{"p":[[1.6,0.8],[2.4,0.8],[2.4,1.6],[1.6,1.6]]},{"p":[[0,1.6],[0.8,1.6],[0.8,2.4],[0,2.4]]},{"p":[[0.8,1.6],[1.6,1.6],[1.6,2.4],[0.8,2.4]]},{"p":[[1.6,1.6],[2.4,1.6],[2.4,2.4],[1.6,2.4]]}]}},{"stem":"이 도형은 똑같이 넷으로 나누어졌어요.","answer":"X","reason_options":[{"t":"조각의 크기가 서로 달라서","correct":true},{"t":"조각이 4개라서","mis":"M3-1-u6-X01"}],"explanation":["조각은 4개지만 크기가 서로 달라요.","겹쳐 보면 꼭 맞지 않아요.","조각 수만 같다고 똑같이 나눈 것이 아니에요 — ×."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,2],[0,2]]},{"p":[[1,0],[2,0],[2,2],[1,2]]},{"p":[[2,0],[4,0],[4,2],[2,2]]},{"p":[[4,0],[5,0],[5,2],[4,2]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#10','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C2',2,'mc','auto','분수 ⟨2/4⟩를 바르게 읽은 것은 무엇인가요?',ARRAY['M3-1-u6-X02','M3-1-u6-X06']::text[],true,'{"seq":10,"concept":"M3-1-u6-C2","difficulty":2,"kind":"mc","stem":"분수 ⟨2/4⟩를 바르게 읽은 것은 무엇인가요?","options":[{"t":"사분의 이","correct":true},{"t":"이분의 사","mis":"M3-1-u6-X02"},{"t":"이 점 사","mis":"M3-1-u6-X06"},{"t":"사 더하기 이","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 4, 분자 2예요.","⟨2/4⟩는 「사분의 이」라고 읽어요."],"variant_rule":{"alt":[{"stem":"분수 ⟨6/8⟩을 바르게 읽은 것은 무엇인가요?","options":[{"t":"팔분의 육","correct":true},{"t":"육분의 팔","mis":"M3-1-u6-X02"},{"t":"육 점 팔","mis":"M3-1-u6-X06"},{"t":"팔 더하기 육","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 8, 분자 6이에요.","⟨6/8⟩은 「팔분의 육」이라고 읽어요."],"asset":null},{"stem":"분수 ⟨2/7⟩를 바르게 읽은 것은 무엇인가요?","options":[{"t":"칠분의 이","correct":true},{"t":"이분의 칠","mis":"M3-1-u6-X02"},{"t":"이 점 칠","mis":"M3-1-u6-X06"},{"t":"칠 더하기 이","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 7, 분자 2예요.","⟨2/7⟩는 「칠분의 이」라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#11','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C3',2,'sa','auto','⟨2/4⟩는 ⟨1/4⟩이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-1-u6-C3","difficulty":2,"kind":"sa","stem":"⟨2/4⟩는 ⟨1/4⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨2/4⟩는 전체를 4칸으로 나눈 것 중 2칸이에요.","한 칸이 ⟨1/4⟩이에요.","⟨2/4⟩는 ⟨1/4⟩이 2개예요."],"variant_rule":{"alt":[{"stem":"⟨2/6⟩는 ⟨1/6⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨2/6⟩는 전체를 6칸으로 나눈 것 중 2칸이에요.","한 칸이 ⟨1/6⟩이에요.","⟨2/6⟩는 ⟨1/6⟩이 2개예요."],"asset":null},{"stem":"⟨3/6⟩은 ⟨1/6⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨3/6⟩은 전체를 6칸으로 나눈 것 중 3칸이에요.","한 칸이 ⟨1/6⟩이에요.","⟨3/6⟩은 ⟨1/6⟩이 3개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#12','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C4',2,'sa','auto','부침개의 ⟨1/4⟩만큼인 조각이 1개 있어요. 전체 부침개 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-1-u6-C4","difficulty":2,"kind":"sa","stem":"부침개의 ⟨1/4⟩만큼인 조각이 1개 있어요. 전체 부침개 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨1/4⟩이 4개 모여야 전체예요.","지금 1개가 있어요.","4 − 1 = 3 — 3개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"난의 ⟨1/4⟩만큼인 조각이 3개 있어요. 전체 난 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨1/4⟩이 4개 모여야 전체예요.","지금 3개가 있어요.","4 − 3 = 1 — 1개 더 있어야 해요."],"asset":null},{"stem":"타르트의 ⟨1/4⟩만큼인 조각이 2개 있어요. 전체 타르트 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨1/4⟩이 4개 모여야 전체예요.","지금 2개가 있어요.","4 − 2 = 2 — 2개 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#13','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C5',2,'mc','auto','크기가 같은 떡을 유나는 ⟨3/8⟩만큼, 도윤은 ⟨7/8⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?',ARRAY['M3-1-u6-X09','M3-1-u6-X20']::text[],true,'{"seq":13,"concept":"M3-1-u6-C5","difficulty":2,"kind":"mc","stem":"크기가 같은 떡을 유나는 ⟨3/8⟩만큼, 도윤은 ⟨7/8⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"유나","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["떡 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 3과 7.","분자가 큰 도윤이 더 많이 먹었어요."],"variant_rule":{"alt":[{"stem":"크기가 같은 월병을 서준은 ⟨4/9⟩만큼, 태오는 ⟨7/9⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"태오","correct":true},{"t":"서준","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["월병 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 4와 7.","분자가 큰 태오가 더 많이 먹었어요."],"asset":null},{"stem":"크기가 같은 타르트를 지윤은 ⟨2/9⟩만큼, 유나는 ⟨5/9⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"유나","correct":true},{"t":"지윤","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["타르트 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 2와 5.","분자가 큰 유나가 더 많이 먹었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#14','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C7',2,'sa','auto','⟨8/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-1-u6-C7","difficulty":2,"kind":"sa","stem":"⟨8/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨8/10⟩은 ⟨1/10⟩이 8개예요.","10 − 8 = 2개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"⟨5/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨5/10⟩는 ⟨1/10⟩이 5개예요.","10 − 5 = 5개 더 있어야 해요."],"asset":null},{"stem":"⟨2/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨2/10⟩는 ⟨1/10⟩이 2개예요.","10 − 2 = 8개 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#15','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C8',2,'mc','auto','씨앗의 길이는 5 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?',ARRAY['M3-1-u6-X17','M3-1-u6-X13']::text[],true,'{"seq":15,"concept":"M3-1-u6-C8","difficulty":2,"kind":"mc","stem":"씨앗의 길이는 5 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.5 cm","correct":true},{"t":"5 cm","mis":"M3-1-u6-X17"},{"t":"0.05 cm","mis":"M3-1-u6-X17"},{"t":"5.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","5 mm = 0.1 cm가 5개 = 0.5 cm."],"asset":{"type":"mmruler","len":5,"label":"씨앗"},"variant_rule":{"alt":[{"stem":"단추 구멍의 길이는 7 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.7 cm","correct":true},{"t":"7 cm","mis":"M3-1-u6-X17"},{"t":"0.07 cm","mis":"M3-1-u6-X17"},{"t":"7.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","7 mm = 0.1 cm가 7개 = 0.7 cm."],"asset":{"type":"mmruler","len":7,"label":"단추 구멍"}},{"stem":"리본 폭의 길이는 6 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.6 cm","correct":true},{"t":"6 cm","mis":"M3-1-u6-X17"},{"t":"0.06 cm","mis":"M3-1-u6-X17"},{"t":"6.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","6 mm = 0.1 cm가 6개 = 0.6 cm."],"asset":{"type":"mmruler","len":6,"label":"리본 폭"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
