INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#18','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C4',3,'sa','auto','색칠한 그림은 전체의 ⟨1/5⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M3-1-u6-C4","difficulty":3,"kind":"sa","stem":"색칠한 그림은 전체의 ⟨1/5⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["그림은 작은 칸 2개이고 전체의 ⟨1/5⟩이에요.","이 조각이 5개 모여야 전체예요.","전체는 ⟨1/5⟩이 5개 — 작은 칸 2 × 5 = 10개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true}]},"variant_rule":{"alt":[{"stem":"색칠한 그림은 전체의 ⟨1/6⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["그림은 작은 칸 4개이고 전체의 ⟨1/6⟩이에요.","이 조각이 6개 모여야 전체예요.","전체는 ⟨1/6⟩이 6개 — 작은 칸 4 × 6 = 24개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true}]}},{"stem":"색칠한 그림은 전체의 ⟨1/2⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["그림은 작은 칸 1개이고 전체의 ⟨1/2⟩이에요.","이 조각이 2개 모여야 전체예요.","전체는 ⟨1/2⟩이 2개 — 작은 칸 1 × 2 = 2개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#19','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C5',3,'sa','auto','⟨□/9⟩는 ⟨2/9⟩보다 크고 ⟨7/9⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M3-1-u6-C5","difficulty":3,"kind":"sa","stem":"⟨□/9⟩는 ⟨2/9⟩보다 크고 ⟨7/9⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모가 같으니 분자만 견주어요.","□는 2보다 크고 7보다 작은 수 — 3, 4, 5, 6.","모두 4개예요."],"variant_rule":{"alt":[{"stem":"⟨□/9⟩는 ⟨5/9⟩보다 크고 ⟨8/9⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모가 같으니 분자만 견주어요.","□는 5보다 크고 8보다 작은 수 — 6, 7.","모두 2개예요."],"asset":null},{"stem":"⟨□/11⟩는 ⟨3/11⟩보다 크고 ⟨5/11⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["분모가 같으니 분자만 견주어요.","□는 3보다 크고 5보다 작은 수 — 4.","모두 1개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#20','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C7',3,'sa','auto','1과 ⟨9/10⟩를 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M3-1-u6-C7","difficulty":3,"kind":"sa","stem":"1과 ⟨9/10⟩를 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["1은 ⟨1/10⟩이 10개예요.","⟨9/10⟩는 ⟨1/10⟩이 9개예요.","10 + 9 = 19개예요."],"variant_rule":{"alt":[{"stem":"1과 ⟨7/10⟩을 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["1은 ⟨1/10⟩이 10개예요.","⟨7/10⟩은 ⟨1/10⟩이 7개예요.","10 + 7 = 17개예요."],"asset":null},{"stem":"1과 ⟨1/10⟩을 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["1은 ⟨1/10⟩이 10개예요.","⟨1/10⟩은 ⟨1/10⟩이 1개예요.","10 + 1 = 11개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#21','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C9',3,'mc','auto','두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.5 ○ ⟨9/10⟩',ARRAY['M3-1-u6-X16','M3-1-u6-X20']::text[],true,'{"seq":21,"concept":"M3-1-u6-C9","difficulty":3,"kind":"mc","stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.5 ○ ⟨9/10⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u6-X16"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.5 = ⟨5/10⟩예요.","분모가 10으로 같으니 분자를 견주어요 — 5와 9.","0.5 < ⟨9/10⟩."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.6 ○ ⟨3/10⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u6-X16"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.6 = ⟨6/10⟩이에요.","분모가 10으로 같으니 분자를 견주어요 — 6과 3.","0.6 > ⟨3/10⟩."],"asset":null},{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.1 ○ ⟨5/10⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u6-X16"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.1 = ⟨1/10⟩이에요.","분모가 10으로 같으니 분자를 견주어요 — 1과 5.","0.1 < ⟨5/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#22','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C10',3,'mc','auto','길이가 12 cm인 띠는 똑같이 6칸, 8 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/6⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?',ARRAY['M3-1-u6-X11','M3-1-u6-X20']::text[],true,'{"seq":22,"concept":"M3-1-u6-C10","difficulty":3,"kind":"mc","stem":"길이가 12 cm인 띠는 똑같이 6칸, 8 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/6⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"짧은 띠의 ⟨1/2⟩이 커요","correct":true},{"t":"긴 띠의 ⟨1/6⟩이 커요","mis":"M3-1-u6-X11"},{"t":"두 조각의 크기가 같아요","mis":"M3-1-u6-X11"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 12 ÷ 6 = 2 cm, 짧은 띠 한 칸은 8 ÷ 2 = 4 cm예요.","짧은 띠의 ⟨1/2⟩이 커요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,0.9],[0,0.9]],"hi":true},{"p":[[1,0],[2,0],[2,0.9],[1,0.9]]},{"p":[[2,0],[3,0],[3,0.9],[2,0.9]]},{"p":[[3,0],[4,0],[4,0.9],[3,0.9]]},{"p":[[4,0],[5,0],[5,0.9],[4,0.9]]},{"p":[[5,0],[6,0],[6,0.9],[5,0.9]]},{"p":[[6.9,0],[8.9,0],[8.9,0.9],[6.9,0.9]],"hi":true},{"p":[[8.9,0],[10.9,0],[10.9,0.9],[8.9,0.9]]}],"u":27},"variant_rule":{"alt":[{"stem":"길이가 12 cm인 띠는 똑같이 2칸, 6 cm인 띠는 똑같이 3칸으로 나누었어요. 긴 띠의 ⟨1/2⟩과 짧은 띠의 ⟨1/3⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"긴 띠의 ⟨1/2⟩이 커요","correct":true},{"t":"짧은 띠의 ⟨1/3⟩이 커요","mis":"M3-1-u6-X11"},{"t":"두 조각의 크기가 같아요","mis":"M3-1-u6-X11"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 12 ÷ 2 = 6 cm, 짧은 띠 한 칸은 6 ÷ 3 = 2 cm예요.","긴 띠의 ⟨1/2⟩이 커요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[3,0],[3,0.9],[0,0.9]],"hi":true},{"p":[[3,0],[6,0],[6,0.9],[3,0.9]]},{"p":[[6.9,0],[7.9,0],[7.9,0.9],[6.9,0.9]],"hi":true},{"p":[[7.9,0],[8.9,0],[8.9,0.9],[7.9,0.9]]},{"p":[[8.9,0],[9.9,0],[9.9,0.9],[8.9,0.9]]}],"u":30}},{"stem":"길이가 12 cm인 띠는 똑같이 4칸, 6 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/4⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"두 조각의 크기가 같아요","correct":true},{"t":"긴 띠의 ⟨1/4⟩이 커요","mis":"M3-1-u6-X11"},{"t":"짧은 띠의 ⟨1/2⟩이 커요","mis":"M3-1-u6-X10"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 12 ÷ 4 = 3 cm, 짧은 띠 한 칸은 6 ÷ 2 = 3 cm예요.","두 조각의 크기가 같아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1.5,0],[1.5,0.9],[0,0.9]],"hi":true},{"p":[[1.5,0],[3,0],[3,0.9],[1.5,0.9]]},{"p":[[3,0],[4.5,0],[4.5,0.9],[3,0.9]]},{"p":[[4.5,0],[6,0],[6,0.9],[4.5,0.9]]},{"p":[[6.9,0],[8.4,0],[8.4,0.9],[6.9,0.9]],"hi":true},{"p":[[8.4,0],[9.9,0],[9.9,0.9],[8.4,0.9]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#23','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C6',4,'sa','auto','⟨1/□⟩ > ⟨1/8⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-1-u6-C6","difficulty":4,"kind":"sa","stem":"⟨1/□⟩ > ⟨1/8⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 8보다 작고 1보다 큰 수 — 2, 3, 4, 5, 6, 7.","모두 6개예요."],"variant_rule":{"alt":[{"stem":"⟨1/□⟩ > ⟨1/7⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 7보다 작고 1보다 큰 수 — 2, 3, 4, 5, 6.","모두 5개예요."],"asset":null},{"stem":"⟨1/□⟩ > ⟨1/10⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 10보다 작고 1보다 큰 수 — 2, 3, 4, 5, 6, 7, 8, 9.","모두 8개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#24','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C9',4,'mc','auto','가장 큰 수는 어느 것인가요?',ARRAY['M3-1-u6-X16','M3-1-u6-X18']::text[],true,'{"seq":24,"concept":"M3-1-u6-C9","difficulty":4,"kind":"mc","stem":"가장 큰 수는 어느 것인가요?","options":[{"t":"0.9","correct":true},{"t":"⟨2/10⟩","mis":"M3-1-u6-X16"},{"t":"0.1이 1개인 수","mis":"M3-1-u6-X18"},{"t":"⟨1/10⟩이 4개인 수","mis":"M3-1-u6-X16"}],"explanation":["모두 0.1(=⟨1/10⟩)이 몇 개인지로 바꾸어요.","9개, 2개, 1개, 4개예요.","가장 많은 것은 0.9예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 가장 큰 수는 어느 것인가요?","options":[{"t":"0.8","correct":true},{"t":"⟨4/10⟩","mis":"M3-1-u6-X16"},{"t":"0.1이 7개인 수","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩이 3개인 수","mis":"M3-1-u6-X18"}],"explanation":["모두 0.1(=⟨1/10⟩)이 몇 개인지로 바꾸어요.","8개, 4개, 7개, 3개예요.","가장 많은 것은 0.8이에요."],"asset":null},{"stem":"이번에는 다른 문제예요. 가장 큰 수는 어느 것인가요?","options":[{"t":"⟨9/10⟩","correct":true},{"t":"0.2","mis":"M3-1-u6-X16"},{"t":"0.1이 1개인 수","mis":"M3-1-u6-X18"},{"t":"⟨1/10⟩이 3개인 수","mis":"M3-1-u6-X16"}],"explanation":["모두 0.1(=⟨1/10⟩)이 몇 개인지로 바꾸어요.","2개, 9개, 1개, 3개예요.","가장 많은 것은 ⟨9/10⟩예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_a#25','math',3,1,'u6','','g3_1_math_u6_review_a','unit_review','M3-1-u6-C2',4,'essay','teacher','똑같이 여섯 칸으로 나눈 띠에서 4칸을 색칠했어요. 색칠한 부분과 색칠하지 않은 부분을 각각 분수로 나타내고, 분모와 분자가 무엇을 뜻하는지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u6-C2","difficulty":4,"kind":"essay","stem":"똑같이 여섯 칸으로 나눈 띠에서 4칸을 색칠했어요. 색칠한 부분과 색칠하지 않은 부분을 각각 분수로 나타내고, 분모와 분자가 무엇을 뜻하는지 써 보세요.","answer_guide":{"answer":"예: 색칠한 부분은 ⟨4/6⟩, 색칠하지 않은 부분은 ⟨2/6⟩이다. 분모 6은 전체를 똑같이 나눈 칸 수이고, 분자는 그중 몇 칸인지(4칸, 2칸)를 나타낸다.","scoring_points":["색칠한 부분 ⟨4/6⟩를 썼는가","색칠하지 않은 부분 ⟨2/6⟩를 썼는가","분모·분자의 뜻을 바르게 썼는가"]},"explanation":["6칸 중 4칸 = ⟨4/6⟩.","남은 2칸 = ⟨2/6⟩.","분모 = 나눈 수, 분자 = 그중 몇."],"asset":{"type":"fbar","bars":[{"den":6,"num":4}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_b#1','math',3,1,'u6','','g3_1_math_u6_review_b','unit_review','M3-1-u6-C1',1,'mc','auto','이 도형은 똑같이 몇으로 나누었나요?',ARRAY['M3-1-u6-X19']::text[],true,'{"seq":1,"concept":"M3-1-u6-C1","difficulty":1,"kind":"mc","stem":"이 도형은 똑같이 몇으로 나누었나요?","options":[{"t":"셋","correct":true},{"t":"둘","mis":"M3-1-u6-X19"},{"t":"넷","mis":"M3-1-u6-X19"},{"t":"여섯","mis":"M3-1-u6-X19"}],"explanation":["조각을 하나씩 짚어 세면 3개예요.","조각의 모양과 크기가 모두 같아요.","그래서 똑같이 셋으로 나눈 거예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,2],[0,2]]},{"p":[[1,0],[2,0],[2,2],[1,2]]},{"p":[[2,0],[3,0],[3,2],[2,2]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 이 도형은 똑같이 몇으로 나누었나요?","options":[{"t":"둘","correct":true},{"t":"하나","mis":"M3-1-u6-X19"},{"t":"셋","mis":"M3-1-u6-X19"},{"t":"넷","mis":"M3-1-u6-X19"}],"explanation":["조각을 하나씩 짚어 세면 2개예요.","조각의 모양과 크기가 모두 같아요.","그래서 똑같이 둘로 나눈 거예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[3,0],[3,0.7],[0,0.7]]},{"p":[[0,0.7],[3,0.7],[3,1.4],[0,1.4]]}]}},{"stem":"이번에는 다른 문제예요. 이 도형은 똑같이 몇으로 나누었나요?","options":[{"t":"넷","correct":true},{"t":"셋","mis":"M3-1-u6-X19"},{"t":"다섯","mis":"M3-1-u6-X19"},{"t":"여덟","mis":"M3-1-u6-X19"}],"explanation":["조각을 하나씩 짚어 세면 4개예요.","조각의 모양과 크기가 모두 같아요.","그래서 똑같이 넷으로 나눈 거예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[2,0],[1,1]]},{"p":[[2,0],[2,2],[1,1]]},{"p":[[2,2],[0,2],[1,1]]},{"p":[[0,2],[0,0],[1,1]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
