INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_b#8','math',3,1,'u6','','g3_1_math_u6_review_b','unit_review','M3-1-u6-C9',1,'mc','auto','0.2와 0.6 중 더 큰 수는 무엇인가요?',ARRAY['M3-1-u6-X15','M3-1-u6-X20']::text[],true,'{"seq":8,"concept":"M3-1-u6-C9","difficulty":1,"kind":"mc","stem":"0.2와 0.6 중 더 큰 수는 무엇인가요?","options":[{"t":"0.6","correct":true},{"t":"0.2","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.2는 0.1이 2개, 0.6은 0.1이 6개예요.","0.1의 개수가 많을수록 큰 소수예요.","2 < 6 — 0.2 < 0.6."],"variant_rule":{"alt":[{"stem":"0.2와 0.9 중 더 큰 수는 무엇인가요?","options":[{"t":"0.9","correct":true},{"t":"0.2","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.2는 0.1이 2개, 0.9는 0.1이 9개예요.","0.1의 개수가 많을수록 큰 소수예요.","2 < 9 — 0.2 < 0.9."],"asset":null},{"stem":"0.8과 0.1 중 더 큰 수는 무엇인가요?","options":[{"t":"0.8","correct":true},{"t":"0.1","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.8은 0.1이 8개, 0.1은 0.1이 1개예요.","0.1의 개수가 많을수록 큰 소수예요.","8 > 1 — 0.8 > 0.1."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_b#9','math',3,1,'u6','','g3_1_math_u6_review_b','unit_review','M3-1-u6-C1',2,'ox','auto','이 도형은 똑같이 넷으로 나누어졌어요.',ARRAY['M3-1-u6-X01']::text[],true,'{"seq":9,"concept":"M3-1-u6-C1","difficulty":2,"kind":"ox","stem":"이 도형은 똑같이 넷으로 나누어졌어요.","answer":"X","reason_options":[{"t":"조각의 크기가 서로 달라서","correct":true},{"t":"조각이 4개라서","mis":"M3-1-u6-X01"}],"mis":"M3-1-u6-X01","explanation":["조각은 4개지만 크기가 서로 달라요.","겹쳐 보면 꼭 맞지 않아요.","조각 수만 같다고 똑같이 나눈 것이 아니에요 — ×."],"asset":{"type":"tiles","pieces":[{"p":[[1.5,1.5],[1.5,0],[1.657,0.008],[1.812,0.033],[1.964,0.073],[2.11,0.13],[2.25,0.201],[2.382,0.286],[2.504,0.385],[2.615,0.496],[2.714,0.618],[2.799,0.75]]},{"p":[[1.5,1.5],[2.799,0.75],[2.87,0.89],[2.927,1.036],[2.967,1.188],[2.992,1.343],[3,1.5],[2.992,1.657],[2.967,1.812],[2.927,1.964],[2.87,2.11],[2.799,2.25]]},{"p":[[1.5,1.5],[2.799,2.25],[2.714,2.382],[2.615,2.504],[2.504,2.615],[2.382,2.714],[2.25,2.799],[2.11,2.87],[1.964,2.927],[1.812,2.967],[1.657,2.992],[1.5,3]]},{"p":[[1.5,3],[1.343,2.992],[1.188,2.967],[1.036,2.927],[0.89,2.87],[0.75,2.799],[0.618,2.714],[0.496,2.615],[0.385,2.504],[0.286,2.382],[0.201,2.25],[0.13,2.11],[0.073,1.964],[0.033,1.812],[0.008,1.657],[0,1.5],[0.008,1.343],[0.033,1.188],[0.073,1.036],[0.13,0.89],[0.201,0.75],[0.286,0.618],[0.385,0.496],[0.496,0.385],[0.618,0.286],[0.75,0.201],[0.89,0.13],[1.036,0.073],[1.188,0.033],[1.343,0.008],[1.5,0]]}]},"variant_rule":{"alt":[{"stem":"이 도형은 똑같이 둘로 나누어졌어요.","answer":"X","reason_options":[{"t":"조각의 크기가 서로 달라서","correct":true},{"t":"조각이 2개라서","mis":"M3-1-u6-X01"}],"explanation":["조각은 2개지만 크기가 서로 달라요.","겹쳐 보면 꼭 맞지 않아요.","조각 수만 같다고 똑같이 나눈 것이 아니에요 — ×."],"asset":{"type":"tiles","pieces":[{"p":[[0,2],[0.6,2],[1,0]]},{"p":[[0.6,2],[2,2],[1,0]]}]}},{"stem":"이 도형은 똑같이 나누어졌어요.","answer":"O","reason_options":[{"t":"조각의 모양과 크기가 모두 같아서","correct":true},{"t":"조각 수만 세면 되어서","mis":"M3-1-u6-X01"}],"explanation":["조각을 겹쳐 보면 모양과 크기가 꼭 맞아요.","5조각의 크기가 모두 같아요.","그래서 똑같이 나눈 거예요 — ○."],"asset":{"type":"tiles","pieces":[{"p":[[1.5,1.5],[1.5,0],[1.657,0.008],[1.812,0.033],[1.964,0.073],[2.11,0.13],[2.25,0.201],[2.382,0.286],[2.504,0.385],[2.615,0.496],[2.714,0.618],[2.799,0.75],[2.87,0.89],[2.927,1.036]]},{"p":[[1.5,1.5],[2.927,1.036],[2.967,1.188],[2.992,1.343],[3,1.5],[2.992,1.657],[2.967,1.812],[2.927,1.964],[2.87,2.11],[2.799,2.25],[2.714,2.382],[2.615,2.504],[2.504,2.615],[2.382,2.714]]},{"p":[[1.5,1.5],[2.382,2.714],[2.25,2.799],[2.11,2.87],[1.964,2.927],[1.812,2.967],[1.657,2.992],[1.5,3],[1.343,2.992],[1.188,2.967],[1.036,2.927],[0.89,2.87],[0.75,2.799],[0.618,2.714]]},{"p":[[1.5,1.5],[0.618,2.714],[0.496,2.615],[0.385,2.504],[0.286,2.382],[0.201,2.25],[0.13,2.11],[0.073,1.964],[0.033,1.812],[0.008,1.657],[0,1.5],[0.008,1.343],[0.033,1.188],[0.073,1.036]]},{"p":[[1.5,1.5],[0.073,1.036],[0.13,0.89],[0.201,0.75],[0.286,0.618],[0.385,0.496],[0.496,0.385],[0.618,0.286],[0.75,0.201],[0.89,0.13],[1.036,0.073],[1.188,0.033],[1.343,0.008],[1.5,0]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_b#10','math',3,1,'u6','','g3_1_math_u6_review_b','unit_review','M3-1-u6-C2',2,'mc','auto','분수 ⟨6/7⟩을 바르게 읽은 것은 무엇인가요?',ARRAY['M3-1-u6-X02','M3-1-u6-X06']::text[],true,'{"seq":10,"concept":"M3-1-u6-C2","difficulty":2,"kind":"mc","stem":"분수 ⟨6/7⟩을 바르게 읽은 것은 무엇인가요?","options":[{"t":"칠분의 육","correct":true},{"t":"육분의 칠","mis":"M3-1-u6-X02"},{"t":"육 점 칠","mis":"M3-1-u6-X06"},{"t":"칠 더하기 육","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 7, 분자 6이에요.","⟨6/7⟩은 「칠분의 육」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"분수 ⟨1/9⟩을 바르게 읽은 것은 무엇인가요?","options":[{"t":"구분의 일","correct":true},{"t":"일분의 구","mis":"M3-1-u6-X02"},{"t":"일 점 구","mis":"M3-1-u6-X06"},{"t":"구 더하기 일","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 9, 분자 1이에요.","⟨1/9⟩은 「구분의 일」이라고 읽어요."],"asset":null},{"stem":"분수 ⟨5/9⟩를 바르게 읽은 것은 무엇인가요?","options":[{"t":"구분의 오","correct":true},{"t":"오분의 구","mis":"M3-1-u6-X02"},{"t":"오 점 구","mis":"M3-1-u6-X06"},{"t":"구 더하기 오","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 9, 분자 5예요.","⟨5/9⟩는 「구분의 오」라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_b#11','math',3,1,'u6','','g3_1_math_u6_review_b','unit_review','M3-1-u6-C3',2,'sa','auto','⟨2/5⟩는 ⟨1/5⟩이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-1-u6-C3","difficulty":2,"kind":"sa","stem":"⟨2/5⟩는 ⟨1/5⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨2/5⟩는 전체를 5칸으로 나눈 것 중 2칸이에요.","한 칸이 ⟨1/5⟩이에요.","⟨2/5⟩는 ⟨1/5⟩이 2개예요."],"variant_rule":{"alt":[{"stem":"⟨2/8⟩는 ⟨1/8⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨2/8⟩는 전체를 8칸으로 나눈 것 중 2칸이에요.","한 칸이 ⟨1/8⟩이에요.","⟨2/8⟩는 ⟨1/8⟩이 2개예요."],"asset":null},{"stem":"⟨2/9⟩는 ⟨1/9⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨2/9⟩는 전체를 9칸으로 나눈 것 중 2칸이에요.","한 칸이 ⟨1/9⟩이에요.","⟨2/9⟩는 ⟨1/9⟩이 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_b#12','math',3,1,'u6','','g3_1_math_u6_review_b','unit_review','M3-1-u6-C4',2,'sa','auto','떡의 ⟨1/4⟩만큼인 조각이 3개 있어요. 전체 떡 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-1-u6-C4","difficulty":2,"kind":"sa","stem":"떡의 ⟨1/4⟩만큼인 조각이 3개 있어요. 전체 떡 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨1/4⟩이 4개 모여야 전체예요.","지금 3개가 있어요.","4 − 3 = 1 — 1개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"월병의 ⟨1/9⟩만큼인 조각이 4개 있어요. 전체 월병 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨1/9⟩이 9개 모여야 전체예요.","지금 4개가 있어요.","9 − 4 = 5 — 5개 더 있어야 해요."],"asset":null},{"stem":"전병의 ⟨1/5⟩만큼인 조각이 1개 있어요. 전체 전병 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨1/5⟩이 5개 모여야 전체예요.","지금 1개가 있어요.","5 − 1 = 4 — 4개 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_b#13','math',3,1,'u6','','g3_1_math_u6_review_b','unit_review','M3-1-u6-C5',2,'mc','auto','크기가 같은 초콜릿을 민서는 ⟨6/8⟩만큼, 유나는 ⟨5/8⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?',ARRAY['M3-1-u6-X09','M3-1-u6-X20']::text[],true,'{"seq":13,"concept":"M3-1-u6-C5","difficulty":2,"kind":"mc","stem":"크기가 같은 초콜릿을 민서는 ⟨6/8⟩만큼, 유나는 ⟨5/8⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"민서","correct":true},{"t":"유나","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["초콜릿 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 6과 5.","분자가 큰 민서가 더 많이 먹었어요."],"variant_rule":{"alt":[{"stem":"크기가 같은 떡을 민서는 ⟨3/8⟩만큼, 유나는 ⟨7/8⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"유나","correct":true},{"t":"민서","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["떡 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 3과 7.","분자가 큰 유나가 더 많이 먹었어요."],"asset":null},{"stem":"크기가 같은 월병을 나래는 ⟨5/6⟩만큼, 서준은 ⟨3/6⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"나래","correct":true},{"t":"서준","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["월병 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 5와 3.","분자가 큰 나래가 더 많이 먹었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_b#14','math',3,1,'u6','','g3_1_math_u6_review_b','unit_review','M3-1-u6-C7',2,'sa','auto','⟨7/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-1-u6-C7","difficulty":2,"kind":"sa","stem":"⟨7/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨7/10⟩은 ⟨1/10⟩이 7개예요.","10 − 7 = 3개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"⟨5/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨5/10⟩는 ⟨1/10⟩이 5개예요.","10 − 5 = 5개 더 있어야 해요."],"asset":null},{"stem":"⟨9/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨9/10⟩는 ⟨1/10⟩이 9개예요.","10 − 9 = 1개 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_b#15','math',3,1,'u6','','g3_1_math_u6_review_b','unit_review','M3-1-u6-C8',2,'mc','auto','단추 구멍의 길이는 5 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?',ARRAY['M3-1-u6-X17','M3-1-u6-X13']::text[],true,'{"seq":15,"concept":"M3-1-u6-C8","difficulty":2,"kind":"mc","stem":"단추 구멍의 길이는 5 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.5 cm","correct":true},{"t":"5 cm","mis":"M3-1-u6-X17"},{"t":"0.05 cm","mis":"M3-1-u6-X17"},{"t":"5.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","5 mm = 0.1 cm가 5개 = 0.5 cm."],"asset":{"type":"mmruler","len":5,"label":"단추 구멍"},"variant_rule":{"alt":[{"stem":"리본 폭의 길이는 6 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.6 cm","correct":true},{"t":"6 cm","mis":"M3-1-u6-X17"},{"t":"0.06 cm","mis":"M3-1-u6-X17"},{"t":"6.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","6 mm = 0.1 cm가 6개 = 0.6 cm."],"asset":{"type":"mmruler","len":6,"label":"리본 폭"}},{"stem":"나뭇잎 자루의 길이는 4 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.4 cm","correct":true},{"t":"4 cm","mis":"M3-1-u6-X17"},{"t":"0.04 cm","mis":"M3-1-u6-X17"},{"t":"4.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","4 mm = 0.1 cm가 4개 = 0.4 cm."],"asset":{"type":"mmruler","len":4,"label":"나뭇잎 자루"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
