INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#8','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C9',1,'mc','auto','0.9와 0.6 중 더 큰 수는 무엇인가요?',ARRAY['M3-1-u6-X15','M3-1-u6-X20']::text[],true,'{"seq":8,"concept":"M3-1-u6-C9","difficulty":1,"kind":"mc","stem":"0.9와 0.6 중 더 큰 수는 무엇인가요?","options":[{"t":"0.9","correct":true},{"t":"0.6","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.9는 0.1이 9개, 0.6은 0.1이 6개예요.","0.1의 개수가 많을수록 큰 소수예요.","9 > 6 — 0.9 > 0.6."],"variant_rule":{"alt":[{"stem":"0.9와 0.2 중 더 큰 수는 무엇인가요?","options":[{"t":"0.9","correct":true},{"t":"0.2","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.9는 0.1이 9개, 0.2는 0.1이 2개예요.","0.1의 개수가 많을수록 큰 소수예요.","9 > 2 — 0.9 > 0.2."],"asset":null},{"stem":"0.4와 0.8 중 더 큰 수는 무엇인가요?","options":[{"t":"0.8","correct":true},{"t":"0.4","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.4는 0.1이 4개, 0.8은 0.1이 8개예요.","0.1의 개수가 많을수록 큰 소수예요.","4 < 8 — 0.4 < 0.8."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#9','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C1',2,'ox','auto','이 도형은 똑같이 셋으로 나누어졌어요.',ARRAY['M3-1-u6-X01']::text[],true,'{"seq":9,"concept":"M3-1-u6-C1","difficulty":2,"kind":"ox","stem":"이 도형은 똑같이 셋으로 나누어졌어요.","answer":"X","reason_options":[{"t":"조각의 크기가 서로 달라서","correct":true},{"t":"조각이 3개라서","mis":"M3-1-u6-X01"}],"mis":"M3-1-u6-X01","explanation":["조각은 3개지만 크기가 서로 달라요.","겹쳐 보면 꼭 맞지 않아요.","조각 수만 같다고 똑같이 나눈 것이 아니에요 — ×."],"asset":{"type":"tiles","pieces":[{"p":[[1.5,1.5],[1.5,0],[1.657,0.008],[1.812,0.033],[1.964,0.073],[2.11,0.13],[2.25,0.201],[2.382,0.286],[2.504,0.385],[2.615,0.496],[2.714,0.618],[2.799,0.75],[2.87,0.89],[2.927,1.036],[2.967,1.188],[2.992,1.343],[3,1.5]]},{"p":[[1.5,1.5],[3,1.5],[2.992,1.657],[2.967,1.812],[2.927,1.964],[2.87,2.11],[2.799,2.25],[2.714,2.382],[2.615,2.504],[2.504,2.615],[2.382,2.714],[2.25,2.799],[2.11,2.87],[1.964,2.927],[1.812,2.967],[1.657,2.992],[1.5,3]]},{"p":[[1.5,3],[1.343,2.992],[1.188,2.967],[1.036,2.927],[0.89,2.87],[0.75,2.799],[0.618,2.714],[0.496,2.615],[0.385,2.504],[0.286,2.382],[0.201,2.25],[0.13,2.11],[0.073,1.964],[0.033,1.812],[0.008,1.657],[0,1.5],[0.008,1.343],[0.033,1.188],[0.073,1.036],[0.13,0.89],[0.201,0.75],[0.286,0.618],[0.385,0.496],[0.496,0.385],[0.618,0.286],[0.75,0.201],[0.89,0.13],[1.036,0.073],[1.188,0.033],[1.343,0.008],[1.5,0]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 이 도형은 똑같이 셋으로 나누어졌어요.","answer":"X","reason_options":[{"t":"조각의 크기가 서로 달라서","correct":true},{"t":"조각이 3개라서","mis":"M3-1-u6-X01"}],"explanation":["조각은 3개지만 크기가 서로 달라요.","겹쳐 보면 꼭 맞지 않아요.","조각 수만 같다고 똑같이 나눈 것이 아니에요 — ×."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,2],[0,2]]},{"p":[[1,0],[3,0],[3,2],[1,2]]},{"p":[[3,0],[4,0],[4,2],[3,2]]}]}},{"stem":"이 도형은 똑같이 나누어졌어요.","answer":"O","reason_options":[{"t":"조각의 모양과 크기가 모두 같아서","correct":true},{"t":"조각 수만 세면 되어서","mis":"M3-1-u6-X01"}],"explanation":["조각을 겹쳐 보면 모양과 크기가 꼭 맞아요.","4조각의 크기가 모두 같아요.","그래서 똑같이 나눈 거예요 — ○."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[3,0],[3,0.7],[0,0.7]]},{"p":[[0,0.7],[3,0.7],[3,1.4],[0,1.4]]},{"p":[[0,1.4],[3,1.4],[3,2.1],[0,2.1]]},{"p":[[0,2.1],[3,2.1],[3,2.8],[0,2.8]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#10','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C2',2,'mc','auto','분수 ⟨2/6⟩를 바르게 읽은 것은 무엇인가요?',ARRAY['M3-1-u6-X02','M3-1-u6-X06']::text[],true,'{"seq":10,"concept":"M3-1-u6-C2","difficulty":2,"kind":"mc","stem":"분수 ⟨2/6⟩를 바르게 읽은 것은 무엇인가요?","options":[{"t":"육분의 이","correct":true},{"t":"이분의 육","mis":"M3-1-u6-X02"},{"t":"이 점 육","mis":"M3-1-u6-X06"},{"t":"육 더하기 이","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 6, 분자 2예요.","⟨2/6⟩는 「육분의 이」라고 읽어요."],"variant_rule":{"alt":[{"stem":"분수 ⟨1/4⟩을 바르게 읽은 것은 무엇인가요?","options":[{"t":"사분의 일","correct":true},{"t":"일분의 사","mis":"M3-1-u6-X02"},{"t":"일 점 사","mis":"M3-1-u6-X06"},{"t":"사 더하기 일","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 4, 분자 1이에요.","⟨1/4⟩은 「사분의 일」이라고 읽어요."],"asset":null},{"stem":"분수 ⟨2/7⟩를 바르게 읽은 것은 무엇인가요?","options":[{"t":"칠분의 이","correct":true},{"t":"이분의 칠","mis":"M3-1-u6-X02"},{"t":"이 점 칠","mis":"M3-1-u6-X06"},{"t":"칠 더하기 이","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 7, 분자 2예요.","⟨2/7⟩는 「칠분의 이」라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#11','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C3',2,'sa','auto','⟨2/6⟩는 ⟨1/6⟩이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-1-u6-C3","difficulty":2,"kind":"sa","stem":"⟨2/6⟩는 ⟨1/6⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨2/6⟩는 전체를 6칸으로 나눈 것 중 2칸이에요.","한 칸이 ⟨1/6⟩이에요.","⟨2/6⟩는 ⟨1/6⟩이 2개예요."],"variant_rule":{"alt":[{"stem":"⟨2/5⟩는 ⟨1/5⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨2/5⟩는 전체를 5칸으로 나눈 것 중 2칸이에요.","한 칸이 ⟨1/5⟩이에요.","⟨2/5⟩는 ⟨1/5⟩이 2개예요."],"asset":null},{"stem":"⟨3/4⟩은 ⟨1/4⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨3/4⟩은 전체를 4칸으로 나눈 것 중 3칸이에요.","한 칸이 ⟨1/4⟩이에요.","⟨3/4⟩은 ⟨1/4⟩이 3개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#12','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C4',2,'sa','auto','피자의 ⟨1/9⟩만큼인 조각이 5개 있어요. 전체 피자 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-1-u6-C4","difficulty":2,"kind":"sa","stem":"피자의 ⟨1/9⟩만큼인 조각이 5개 있어요. 전체 피자 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨1/9⟩이 9개 모여야 전체예요.","지금 5개가 있어요.","9 − 5 = 4 — 4개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"케이크의 ⟨1/5⟩만큼인 조각이 4개 있어요. 전체 케이크 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨1/5⟩이 5개 모여야 전체예요.","지금 4개가 있어요.","5 − 4 = 1 — 1개 더 있어야 해요."],"asset":null},{"stem":"부침개의 ⟨1/6⟩만큼인 조각이 4개 있어요. 전체 부침개 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨1/6⟩이 6개 모여야 전체예요.","지금 4개가 있어요.","6 − 4 = 2 — 2개 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#13','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C5',2,'mc','auto','크기가 같은 타르트를 서준은 ⟨1/6⟩만큼, 현우는 ⟨5/6⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?',ARRAY['M3-1-u6-X09','M3-1-u6-X20']::text[],true,'{"seq":13,"concept":"M3-1-u6-C5","difficulty":2,"kind":"mc","stem":"크기가 같은 타르트를 서준은 ⟨1/6⟩만큼, 현우는 ⟨5/6⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"현우","correct":true},{"t":"서준","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["타르트 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 1과 5.","분자가 큰 현우가 더 많이 먹었어요."],"variant_rule":{"alt":[{"stem":"크기가 같은 초콜릿을 지윤은 ⟨2/5⟩만큼, 태오는 ⟨1/5⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"지윤","correct":true},{"t":"태오","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["초콜릿 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 2와 1.","분자가 큰 지윤이 더 많이 먹었어요."],"asset":null},{"stem":"크기가 같은 떡을 현우는 ⟨4/9⟩만큼, 민서는 ⟨3/9⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"현우","correct":true},{"t":"민서","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["떡 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 4와 3.","분자가 큰 현우가 더 많이 먹었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#14','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C7',2,'sa','auto','⟨1/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-1-u6-C7","difficulty":2,"kind":"sa","stem":"⟨1/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["9"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨1/10⟩은 ⟨1/10⟩이 1개예요.","10 − 1 = 9개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"⟨6/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨6/10⟩은 ⟨1/10⟩이 6개예요.","10 − 6 = 4개 더 있어야 해요."],"asset":null},{"stem":"⟨9/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨9/10⟩는 ⟨1/10⟩이 9개예요.","10 − 9 = 1개 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#15','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C8',2,'mc','auto','리본 폭의 길이는 7 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?',ARRAY['M3-1-u6-X17','M3-1-u6-X13']::text[],true,'{"seq":15,"concept":"M3-1-u6-C8","difficulty":2,"kind":"mc","stem":"리본 폭의 길이는 7 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.7 cm","correct":true},{"t":"7 cm","mis":"M3-1-u6-X17"},{"t":"0.07 cm","mis":"M3-1-u6-X17"},{"t":"7.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","7 mm = 0.1 cm가 7개 = 0.7 cm."],"asset":{"type":"mmruler","len":7,"label":"리본 폭"},"variant_rule":{"alt":[{"stem":"나뭇잎 자루의 길이는 8 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.8 cm","correct":true},{"t":"8 cm","mis":"M3-1-u6-X17"},{"t":"0.08 cm","mis":"M3-1-u6-X17"},{"t":"8.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","8 mm = 0.1 cm가 8개 = 0.8 cm."],"asset":{"type":"mmruler","len":8,"label":"나뭇잎 자루"}},{"stem":"칼림바 건반의 길이는 6 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.6 cm","correct":true},{"t":"6 cm","mis":"M3-1-u6-X17"},{"t":"0.06 cm","mis":"M3-1-u6-X17"},{"t":"6.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","6 mm = 0.1 cm가 6개 = 0.6 cm."],"asset":{"type":"mmruler","len":6,"label":"칼림바 건반"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
