INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#18','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C4',3,'sa','auto','색칠한 그림은 전체의 ⟨1/6⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M3-1-u6-C4","difficulty":3,"kind":"sa","stem":"색칠한 그림은 전체의 ⟨1/6⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["그림은 작은 칸 1개이고 전체의 ⟨1/6⟩이에요.","이 조각이 6개 모여야 전체예요.","전체는 ⟨1/6⟩이 6개 — 작은 칸 1 × 6 = 6개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true}]},"variant_rule":{"alt":[{"stem":"색칠한 그림은 전체의 ⟨1/2⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["그림은 작은 칸 4개이고 전체의 ⟨1/2⟩이에요.","이 조각이 2개 모여야 전체예요.","전체는 ⟨1/2⟩이 2개 — 작은 칸 4 × 2 = 8개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true}]}},{"stem":"색칠한 그림은 전체의 ⟨1/2⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["그림은 작은 칸 1개이고 전체의 ⟨1/2⟩이에요.","이 조각이 2개 모여야 전체예요.","전체는 ⟨1/2⟩이 2개 — 작은 칸 1 × 2 = 2개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#19','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C5',3,'sa','auto','⟨□/11⟩는 ⟨4/11⟩보다 크고 ⟨8/11⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M3-1-u6-C5","difficulty":3,"kind":"sa","stem":"⟨□/11⟩는 ⟨4/11⟩보다 크고 ⟨8/11⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모가 같으니 분자만 견주어요.","□는 4보다 크고 8보다 작은 수 — 5, 6, 7.","모두 3개예요."],"variant_rule":{"alt":[{"stem":"⟨□/6⟩는 ⟨1/6⟩보다 크고 ⟨5/6⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모가 같으니 분자만 견주어요.","□는 1보다 크고 5보다 작은 수 — 2, 3, 4.","모두 3개예요."],"asset":null},{"stem":"⟨□/11⟩는 ⟨6/11⟩보다 크고 ⟨8/11⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["분모가 같으니 분자만 견주어요.","□는 6보다 크고 8보다 작은 수 — 7.","모두 1개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#20','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C7',3,'sa','auto','1과 ⟨9/10⟩를 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M3-1-u6-C7","difficulty":3,"kind":"sa","stem":"1과 ⟨9/10⟩를 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["1은 ⟨1/10⟩이 10개예요.","⟨9/10⟩는 ⟨1/10⟩이 9개예요.","10 + 9 = 19개예요."],"variant_rule":{"alt":[{"stem":"1과 ⟨5/10⟩를 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["1은 ⟨1/10⟩이 10개예요.","⟨5/10⟩는 ⟨1/10⟩이 5개예요.","10 + 5 = 15개예요."],"asset":null},{"stem":"1과 ⟨7/10⟩을 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["1은 ⟨1/10⟩이 10개예요.","⟨7/10⟩은 ⟨1/10⟩이 7개예요.","10 + 7 = 17개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#21','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C9',3,'mc','auto','두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.8 ○ ⟨8/10⟩',ARRAY['M3-1-u6-X16','M3-1-u6-X20']::text[],true,'{"seq":21,"concept":"M3-1-u6-C9","difficulty":3,"kind":"mc","stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.8 ○ ⟨8/10⟩","options":[{"t":"=","correct":true},{"t":">","mis":"M3-1-u6-X16"},{"t":"<","mis":"M3-1-u6-X16"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.8 = ⟨8/10⟩이에요.","분모가 10으로 같으니 분자를 견주어요 — 8과 8.","0.8 = ⟨8/10⟩."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.4 ○ ⟨2/10⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u6-X16"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.4 = ⟨4/10⟩예요.","분모가 10으로 같으니 분자를 견주어요 — 4와 2.","0.4 > ⟨2/10⟩."],"asset":null},{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.5 ○ ⟨5/10⟩","options":[{"t":"=","correct":true},{"t":">","mis":"M3-1-u6-X16"},{"t":"<","mis":"M3-1-u6-X16"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.5 = ⟨5/10⟩예요.","분모가 10으로 같으니 분자를 견주어요 — 5와 5.","0.5 = ⟨5/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#22','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C10',3,'mc','auto','길이가 8 cm인 띠는 똑같이 8칸, 4 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/8⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?',ARRAY['M3-1-u6-X11','M3-1-u6-X20']::text[],true,'{"seq":22,"concept":"M3-1-u6-C10","difficulty":3,"kind":"mc","stem":"길이가 8 cm인 띠는 똑같이 8칸, 4 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/8⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"짧은 띠의 ⟨1/2⟩이 커요","correct":true},{"t":"긴 띠의 ⟨1/8⟩이 커요","mis":"M3-1-u6-X11"},{"t":"두 조각의 크기가 같아요","mis":"M3-1-u6-X11"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 8 ÷ 8 = 1 cm, 짧은 띠 한 칸은 4 ÷ 2 = 2 cm예요.","짧은 띠의 ⟨1/2⟩이 커요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[0.5,0],[0.5,0.9],[0,0.9]],"hi":true},{"p":[[0.5,0],[1,0],[1,0.9],[0.5,0.9]]},{"p":[[1,0],[1.5,0],[1.5,0.9],[1,0.9]]},{"p":[[1.5,0],[2,0],[2,0.9],[1.5,0.9]]},{"p":[[2,0],[2.5,0],[2.5,0.9],[2,0.9]]},{"p":[[2.5,0],[3,0],[3,0.9],[2.5,0.9]]},{"p":[[3,0],[3.5,0],[3.5,0.9],[3,0.9]]},{"p":[[3.5,0],[4,0],[4,0.9],[3.5,0.9]]},{"p":[[4.9,0],[5.9,0],[5.9,0.9],[4.9,0.9]],"hi":true},{"p":[[5.9,0],[6.9,0],[6.9,0.9],[5.9,0.9]]}]},"variant_rule":{"alt":[{"stem":"길이가 12 cm인 띠는 똑같이 3칸, 6 cm인 띠는 똑같이 3칸으로 나누었어요. 긴 띠의 ⟨1/3⟩과 짧은 띠의 ⟨1/3⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"긴 띠의 ⟨1/3⟩이 커요","correct":true},{"t":"짧은 띠의 ⟨1/3⟩이 커요","mis":"M3-1-u6-X11"},{"t":"두 조각의 크기가 같아요","mis":"M3-1-u6-X11"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 12 ÷ 3 = 4 cm, 짧은 띠 한 칸은 6 ÷ 3 = 2 cm예요.","긴 띠의 ⟨1/3⟩이 커요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[2,0],[2,0.9],[0,0.9]],"hi":true},{"p":[[2,0],[4,0],[4,0.9],[2,0.9]]},{"p":[[4,0],[6,0],[6,0.9],[4,0.9]]},{"p":[[6.9,0],[7.9,0],[7.9,0.9],[6.9,0.9]],"hi":true},{"p":[[7.9,0],[8.9,0],[8.9,0.9],[7.9,0.9]]},{"p":[[8.9,0],[9.9,0],[9.9,0.9],[8.9,0.9]]}],"u":30}},{"stem":"길이가 10 cm인 띠는 똑같이 2칸, 8 cm인 띠는 똑같이 4칸으로 나누었어요. 긴 띠의 ⟨1/2⟩과 짧은 띠의 ⟨1/4⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"긴 띠의 ⟨1/2⟩이 커요","correct":true},{"t":"짧은 띠의 ⟨1/4⟩이 커요","mis":"M3-1-u6-X11"},{"t":"두 조각의 크기가 같아요","mis":"M3-1-u6-X11"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 10 ÷ 2 = 5 cm, 짧은 띠 한 칸은 8 ÷ 4 = 2 cm예요.","긴 띠의 ⟨1/2⟩이 커요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[2.5,0],[2.5,0.9],[0,0.9]],"hi":true},{"p":[[2.5,0],[5,0],[5,0.9],[2.5,0.9]]},{"p":[[5.9,0],[6.9,0],[6.9,0.9],[5.9,0.9]],"hi":true},{"p":[[6.9,0],[7.9,0],[7.9,0.9],[6.9,0.9]]},{"p":[[7.9,0],[8.9,0],[8.9,0.9],[7.9,0.9]]},{"p":[[8.9,0],[9.9,0],[9.9,0.9],[8.9,0.9]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#23','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C6',4,'sa','auto','⟨1/□⟩ > ⟨1/8⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-1-u6-C6","difficulty":4,"kind":"sa","stem":"⟨1/□⟩ > ⟨1/8⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 8보다 작고 1보다 큰 수 — 2, 3, 4, 5, 6, 7.","모두 6개예요."],"variant_rule":{"alt":[{"stem":"⟨1/□⟩ > ⟨1/10⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 10보다 작고 1보다 큰 수 — 2, 3, 4, 5, 6, 7, 8, 9.","모두 8개예요."],"asset":null},{"stem":"⟨1/□⟩ > ⟨1/6⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 6보다 작고 1보다 큰 수 — 2, 3, 4, 5.","모두 4개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#24','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C9',4,'mc','auto','가장 큰 수는 어느 것인가요?',ARRAY['M3-1-u6-X16','M3-1-u6-X18']::text[],true,'{"seq":24,"concept":"M3-1-u6-C9","difficulty":4,"kind":"mc","stem":"가장 큰 수는 어느 것인가요?","options":[{"t":"⟨8/10⟩","correct":true},{"t":"0.4","mis":"M3-1-u6-X16"},{"t":"0.1이 7개인 수","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩이 3개인 수","mis":"M3-1-u6-X18"}],"explanation":["모두 0.1(=⟨1/10⟩)이 몇 개인지로 바꾸어요.","4개, 8개, 7개, 3개예요.","가장 많은 것은 ⟨8/10⟩이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 가장 큰 수는 어느 것인가요?","options":[{"t":"⟨7/10⟩","correct":true},{"t":"0.4","mis":"M3-1-u6-X16"},{"t":"0.1이 1개인 수","mis":"M3-1-u6-X18"},{"t":"⟨1/10⟩이 2개인 수","mis":"M3-1-u6-X16"}],"explanation":["모두 0.1(=⟨1/10⟩)이 몇 개인지로 바꾸어요.","4개, 7개, 1개, 2개예요.","가장 많은 것은 ⟨7/10⟩이에요."],"asset":null},{"stem":"이번에는 다른 문제예요. 가장 큰 수는 어느 것인가요?","options":[{"t":"0.9","correct":true},{"t":"⟨2/10⟩","mis":"M3-1-u6-X18"},{"t":"0.1이 6개인 수","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩이 4개인 수","mis":"M3-1-u6-X16"}],"explanation":["모두 0.1(=⟨1/10⟩)이 몇 개인지로 바꾸어요.","9개, 2개, 6개, 4개예요.","가장 많은 것은 0.9예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_c#25','math',3,1,'u6','','g3_1_math_u6_review_c','unit_review','M3-1-u6-C8',4,'essay','teacher','⟨7/10⟩을 소수로 나타내고 읽어 보세요. 또 이 수가 0.1이 몇 개인지 쓰고 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u6-C8","difficulty":4,"kind":"essay","stem":"⟨7/10⟩을 소수로 나타내고 읽어 보세요. 또 이 수가 0.1이 몇 개인지 쓰고 그 까닭을 설명해 보세요.","answer_guide":{"answer":"예: ⟨7/10⟩ = 0.7이고 「영 점 칠」이라고 읽는다. ⟨1/10⟩은 0.1이므로 ⟨7/10⟩은 0.1이 7개이다.","scoring_points":["0.7로 나타냈는가","「영 점 칠」로 읽었는가","0.1이 7개라고 설명했는가"]},"explanation":["⟨1/10⟩ = 0.1.","⟨7/10⟩ = 0.7(영 점 칠).","0.1이 7개."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#1','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C1',1,'mc','auto','이 도형은 똑같이 몇으로 나누었나요?',ARRAY['M3-1-u6-X19']::text[],true,'{"seq":1,"concept":"M3-1-u6-C1","difficulty":1,"kind":"mc","stem":"이 도형은 똑같이 몇으로 나누었나요?","options":[{"t":"넷","correct":true},{"t":"셋","mis":"M3-1-u6-X19"},{"t":"다섯","mis":"M3-1-u6-X19"},{"t":"여덟","mis":"M3-1-u6-X19"}],"explanation":["조각을 하나씩 짚어 세면 4개예요.","조각의 모양과 크기가 모두 같아요.","그래서 똑같이 넷으로 나눈 거예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[2,0],[1,1]]},{"p":[[2,0],[2,2],[1,1]]},{"p":[[2,2],[0,2],[1,1]]},{"p":[[0,2],[0,0],[1,1]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 이 도형은 똑같이 몇으로 나누었나요?","options":[{"t":"여덟","correct":true},{"t":"일곱","mis":"M3-1-u6-X19"},{"t":"아홉","mis":"M3-1-u6-X19"},{"t":"열여섯","mis":"M3-1-u6-X19"}],"explanation":["조각을 하나씩 짚어 세면 8개예요.","조각의 모양과 크기가 모두 같아요.","그래서 똑같이 여덟으로 나눈 거예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[2,0],[3,0],[3,1],[2,1]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]},{"p":[[2,1],[3,1],[3,2],[2,2]]},{"p":[[3,1],[4,1],[4,2],[3,2]]}]}},{"stem":"이번에는 다른 문제예요. 이 도형은 똑같이 몇으로 나누었나요?","options":[{"t":"여섯","correct":true},{"t":"다섯","mis":"M3-1-u6-X19"},{"t":"일곱","mis":"M3-1-u6-X19"},{"t":"열둘","mis":"M3-1-u6-X19"}],"explanation":["조각을 하나씩 짚어 세면 6개예요.","조각의 모양과 크기가 모두 같아요.","그래서 똑같이 여섯으로 나눈 거예요."],"asset":{"type":"tiles","pieces":[{"p":[[1.5,1.5],[1.5,0],[1.657,0.008],[1.812,0.033],[1.964,0.073],[2.11,0.13],[2.25,0.201],[2.382,0.286],[2.504,0.385],[2.615,0.496],[2.714,0.618],[2.799,0.75]]},{"p":[[1.5,1.5],[2.799,0.75],[2.87,0.89],[2.927,1.036],[2.967,1.188],[2.992,1.343],[3,1.5],[2.992,1.657],[2.967,1.812],[2.927,1.964],[2.87,2.11],[2.799,2.25]]},{"p":[[1