INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#8','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C9',1,'mc','auto','0.5와 0.7 중 더 큰 수는 무엇인가요?',ARRAY['M3-1-u6-X15','M3-1-u6-X20']::text[],true,'{"seq":8,"concept":"M3-1-u6-C9","difficulty":1,"kind":"mc","stem":"0.5와 0.7 중 더 큰 수는 무엇인가요?","options":[{"t":"0.7","correct":true},{"t":"0.5","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.5는 0.1이 5개, 0.7은 0.1이 7개예요.","0.1의 개수가 많을수록 큰 소수예요.","5 < 7 — 0.5 < 0.7."],"variant_rule":{"alt":[{"stem":"0.6과 0.9 중 더 큰 수는 무엇인가요?","options":[{"t":"0.9","correct":true},{"t":"0.6","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.6은 0.1이 6개, 0.9는 0.1이 9개예요.","0.1의 개수가 많을수록 큰 소수예요.","6 < 9 — 0.6 < 0.9."],"asset":null},{"stem":"0.6과 0.4 중 더 큰 수는 무엇인가요?","options":[{"t":"0.6","correct":true},{"t":"0.4","mis":"M3-1-u6-X15"},{"t":"두 수가 같아요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.6은 0.1이 6개, 0.4는 0.1이 4개예요.","0.1의 개수가 많을수록 큰 소수예요.","6 > 4 — 0.6 > 0.4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
