":[[1,0],[2,0],[2,2],[1,2]]},{"p":[[2,0],[3,0],[3,2],[2,2]]}]}},{"stem":"이 도형은 똑같이 넷으로 나누어졌어요.","answer":"X","reason_options":[{"t":"조각의 크기가 서로 달라서","correct":true},{"t":"조각이 4개라서","mis":"M3-1-u6-X01"}],"explanation":["조각은 4개지만 크기가 서로 달라요.","겹쳐 보면 꼭 맞지 않아요.","조각 수만 같다고 똑같이 나눈 것이 아니에요 — ×."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,2],[0,2]]},{"p":[[1,0],[2,0],[2,2],[1,2]]},{"p":[[2,0],[4,0],[4,2],[2,2]]},{"p":[[4,0],[5,0],[5,2],[4,2]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#10','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C2',2,'mc','auto','분수 ⟨2/8⟩를 바르게 읽은 것은 무엇인가요?',ARRAY['M3-1-u6-X02','M3-1-u6-X06']::text[],true,'{"seq":10,"concept":"M3-1-u6-C2","difficulty":2,"kind":"mc","stem":"분수 ⟨2/8⟩를 바르게 읽은 것은 무엇인가요?","options":[{"t":"팔분의 이","correct":true},{"t":"이분의 팔","mis":"M3-1-u6-X02"},{"t":"이 점 팔","mis":"M3-1-u6-X06"},{"t":"팔 더하기 이","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 8, 분자 2예요.","⟨2/8⟩는 「팔분의 이」라고 읽어요."],"variant_rule":{"alt":[{"stem":"분수 ⟨5/7⟩를 바르게 읽은 것은 무엇인가요?","options":[{"t":"칠분의 오","correct":true},{"t":"오분의 칠","mis":"M3-1-u6-X02"},{"t":"오 점 칠","mis":"M3-1-u6-X06"},{"t":"칠 더하기 오","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 7, 분자 5예요.","⟨5/7⟩는 「칠분의 오」라고 읽어요."],"asset":null},{"stem":"분수 ⟨3/8⟩을 바르게 읽은 것은 무엇인가요?","options":[{"t":"팔분의 삼","correct":true},{"t":"삼분의 팔","mis":"M3-1-u6-X02"},{"t":"삼 점 팔","mis":"M3-1-u6-X06"},{"t":"팔 더하기 삼","mis":"M3-1-u6-X06"}],"explanation":["분수는 아래 분모부터 「○분의」, 위 분자를 「△」로 읽어요.","분모 8, 분자 3이에요.","⟨3/8⟩은 「팔분의 삼」이라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#11','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C3',2,'sa','auto','⟨4/5⟩는 ⟨1/5⟩이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M3-1-u6-C3","difficulty":2,"kind":"sa","stem":"⟨4/5⟩는 ⟨1/5⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨4/5⟩는 전체를 5칸으로 나눈 것 중 4칸이에요.","한 칸이 ⟨1/5⟩이에요.","⟨4/5⟩는 ⟨1/5⟩이 4개예요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩은 ⟨1/4⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨3/4⟩은 전체를 4칸으로 나눈 것 중 3칸이에요.","한 칸이 ⟨1/4⟩이에요.","⟨3/4⟩은 ⟨1/4⟩이 3개예요."],"asset":null},{"stem":"⟨2/5⟩는 ⟨1/5⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨2/5⟩는 전체를 5칸으로 나눈 것 중 2칸이에요.","한 칸이 ⟨1/5⟩이에요.","⟨2/5⟩는 ⟨1/5⟩이 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#12','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C4',2,'sa','auto','난의 ⟨1/8⟩만큼인 조각이 4개 있어요. 전체 난 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-1-u6-C4","difficulty":2,"kind":"sa","stem":"난의 ⟨1/8⟩만큼인 조각이 4개 있어요. 전체 난 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨1/8⟩이 8개 모여야 전체예요.","지금 4개가 있어요.","8 − 4 = 4 — 4개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"타르트의 ⟨1/7⟩만큼인 조각이 1개 있어요. 전체 타르트 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["⟨1/7⟩이 7개 모여야 전체예요.","지금 1개가 있어요.","7 − 1 = 6 — 6개 더 있어야 해요."],"asset":null},{"stem":"떡의 ⟨1/9⟩만큼인 조각이 4개 있어요. 전체 떡 한 개가 되려면 같은 조각이 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨1/9⟩이 9개 모여야 전체예요.","지금 4개가 있어요.","9 − 4 = 5 — 5개 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#13','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C5',2,'mc','auto','크기가 같은 월병을 유나는 ⟨6/8⟩만큼, 지유는 ⟨7/8⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?',ARRAY['M3-1-u6-X09','M3-1-u6-X20']::text[],true,'{"seq":13,"concept":"M3-1-u6-C5","difficulty":2,"kind":"mc","stem":"크기가 같은 월병을 유나는 ⟨6/8⟩만큼, 지유는 ⟨7/8⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"지유","correct":true},{"t":"유나","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["월병 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 6과 7.","분자가 큰 지유가 더 많이 먹었어요."],"variant_rule":{"alt":[{"stem":"크기가 같은 타르트를 유나는 ⟨7/9⟩만큼, 하은은 ⟨3/9⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"유나","correct":true},{"t":"하은","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["타르트 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 7과 3.","분자가 큰 유나가 더 많이 먹었어요."],"asset":null},{"stem":"크기가 같은 초콜릿을 하은은 ⟨6/9⟩만큼, 민서는 ⟨4/9⟩만큼 먹었어요. 더 많이 먹은 친구는 누구인가요?","options":[{"t":"하은","correct":true},{"t":"민서","mis":"M3-1-u6-X09"},{"t":"똑같이 먹었어요","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["초콜릿 전체의 크기가 같아요.","분모가 같으니 분자를 견주어요 — 6과 4.","분자가 큰 하은이 더 많이 먹었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#14','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C7',2,'sa','auto','⟨5/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-1-u6-C7","difficulty":2,"kind":"sa","stem":"⟨5/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨5/10⟩는 ⟨1/10⟩이 5개예요.","10 − 5 = 5개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"⟨3/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["7"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨3/10⟩은 ⟨1/10⟩이 3개예요.","10 − 3 = 7개 더 있어야 해요."],"asset":null},{"stem":"⟨2/10⟩에 ⟨1/10⟩이 몇 개 더 모이면 1이 되나요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨1/10⟩이 10개 모이면 1이에요.","⟨2/10⟩는 ⟨1/10⟩이 2개예요.","10 − 2 = 8개 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#15','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C8',2,'mc','auto','나뭇잎 자루의 길이는 4 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?',ARRAY['M3-1-u6-X17','M3-1-u6-X13']::text[],true,'{"seq":15,"concept":"M3-1-u6-C8","difficulty":2,"kind":"mc","stem":"나뭇잎 자루의 길이는 4 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.4 cm","correct":true},{"t":"4 cm","mis":"M3-1-u6-X17"},{"t":"0.04 cm","mis":"M3-1-u6-X17"},{"t":"4.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","4 mm = 0.1 cm가 4개 = 0.4 cm."],"asset":{"type":"mmruler","len":4,"label":"나뭇잎 자루"},"variant_rule":{"alt":[{"stem":"칼림바 건반의 길이는 5 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.5 cm","correct":true},{"t":"5 cm","mis":"M3-1-u6-X17"},{"t":"0.05 cm","mis":"M3-1-u6-X17"},{"t":"5.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","5 mm = 0.1 cm가 5개 = 0.5 cm."],"asset":{"type":"mmruler","len":5,"label":"칼림바 건반"}},{"stem":"구슬의 길이는 3 mm예요. 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.3 cm","correct":true},{"t":"3 cm","mis":"M3-1-u6-X17"},{"t":"0.03 cm","mis":"M3-1-u6-X17"},{"t":"3.0 cm","mis":"M3-1-u6-X13"}],"explanation":["1 cm = 10 mm — 1 mm는 1 cm를 열로 나눈 한 칸이에요.","1 mm = ⟨1/10⟩ cm = 0.1 cm예요.","3 mm = 0.1 cm가 3개 = 0.3 cm."],"asset":{"type":"mmruler","len":3,"label":"구슬"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
