INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#18','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C4',3,'sa','auto','색칠한 그림은 전체의 ⟨1/6⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M3-1-u6-C4","difficulty":3,"kind":"sa","stem":"색칠한 그림은 전체의 ⟨1/6⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["그림은 작은 칸 3개이고 전체의 ⟨1/6⟩이에요.","이 조각이 6개 모여야 전체예요.","전체는 ⟨1/6⟩이 6개 — 작은 칸 3 × 6 = 18개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true}]},"variant_rule":{"alt":[{"stem":"색칠한 그림은 전체의 ⟨1/4⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["그림은 작은 칸 1개이고 전체의 ⟨1/4⟩이에요.","이 조각이 4개 모여야 전체예요.","전체는 ⟨1/4⟩이 4개 — 작은 칸 1 × 4 = 4개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true}]}},{"stem":"색칠한 그림은 전체의 ⟨1/3⟩이에요. 전체는 작은 칸 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["그림은 작은 칸 4개이고 전체의 ⟨1/3⟩이에요.","이 조각이 3개 모여야 전체예요.","전체는 ⟨1/3⟩이 3개 — 작은 칸 4 × 3 = 12개."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#19','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C5',3,'sa','auto','⟨□/9⟩는 ⟨1/9⟩보다 크고 ⟨7/9⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M3-1-u6-C5","difficulty":3,"kind":"sa","stem":"⟨□/9⟩는 ⟨1/9⟩보다 크고 ⟨7/9⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모가 같으니 분자만 견주어요.","□는 1보다 크고 7보다 작은 수 — 2, 3, 4, 5, 6.","모두 5개예요."],"variant_rule":{"alt":[{"stem":"⟨□/12⟩는 ⟨1/12⟩보다 크고 ⟨9/12⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분모가 같으니 분자만 견주어요.","□는 1보다 크고 9보다 작은 수 — 2, 3, 4, 5, 6, 7, 8.","모두 7개예요."],"asset":null},{"stem":"⟨□/8⟩는 ⟨1/8⟩보다 크고 ⟨7/8⟩보다 작아요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모가 같으니 분자만 견주어요.","□는 1보다 크고 7보다 작은 수 — 2, 3, 4, 5, 6.","모두 5개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#20','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C7',3,'sa','auto','1과 ⟨3/10⟩을 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M3-1-u6-C7","difficulty":3,"kind":"sa","stem":"1과 ⟨3/10⟩을 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["1은 ⟨1/10⟩이 10개예요.","⟨3/10⟩은 ⟨1/10⟩이 3개예요.","10 + 3 = 13개예요."],"variant_rule":{"alt":[{"stem":"1과 ⟨7/10⟩을 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["1은 ⟨1/10⟩이 10개예요.","⟨7/10⟩은 ⟨1/10⟩이 7개예요.","10 + 7 = 17개예요."],"asset":null},{"stem":"1과 ⟨1/10⟩을 합한 크기는 ⟨1/10⟩이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["1은 ⟨1/10⟩이 10개예요.","⟨1/10⟩은 ⟨1/10⟩이 1개예요.","10 + 1 = 11개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#21','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C9',3,'mc','auto','두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.5 ○ ⟨5/10⟩',ARRAY['M3-1-u6-X16','M3-1-u6-X20']::text[],true,'{"seq":21,"concept":"M3-1-u6-C9","difficulty":3,"kind":"mc","stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.5 ○ ⟨5/10⟩","options":[{"t":"=","correct":true},{"t":">","mis":"M3-1-u6-X16"},{"t":"<","mis":"M3-1-u6-X16"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.5 = ⟨5/10⟩예요.","분모가 10으로 같으니 분자를 견주어요 — 5와 5.","0.5 = ⟨5/10⟩."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.1 ○ ⟨6/10⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u6-X16"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.1 = ⟨1/10⟩이에요.","분모가 10으로 같으니 분자를 견주어요 — 1과 6.","0.1 < ⟨6/10⟩."],"asset":null},{"stem":"두 수의 크기를 견주어 ○ 안에 알맞은 것을 고르세요. 0.7 ○ ⟨9/10⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u6-X16"},{"t":"=","mis":"M3-1-u6-X20"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["0.7 = ⟨7/10⟩이에요.","분모가 10으로 같으니 분자를 견주어요 — 7과 9.","0.7 < ⟨9/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#22','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C10',3,'mc','auto','길이가 8 cm인 띠는 똑같이 8칸, 4 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/8⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?',ARRAY['M3-1-u6-X11','M3-1-u6-X20']::text[],true,'{"seq":22,"concept":"M3-1-u6-C10","difficulty":3,"kind":"mc","stem":"길이가 8 cm인 띠는 똑같이 8칸, 4 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/8⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"짧은 띠의 ⟨1/2⟩이 커요","correct":true},{"t":"긴 띠의 ⟨1/8⟩이 커요","mis":"M3-1-u6-X11"},{"t":"두 조각의 크기가 같아요","mis":"M3-1-u6-X11"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 8 ÷ 8 = 1 cm, 짧은 띠 한 칸은 4 ÷ 2 = 2 cm예요.","짧은 띠의 ⟨1/2⟩이 커요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[0.5,0],[0.5,0.9],[0,0.9]],"hi":true},{"p":[[0.5,0],[1,0],[1,0.9],[0.5,0.9]]},{"p":[[1,0],[1.5,0],[1.5,0.9],[1,0.9]]},{"p":[[1.5,0],[2,0],[2,0.9],[1.5,0.9]]},{"p":[[2,0],[2.5,0],[2.5,0.9],[2,0.9]]},{"p":[[2.5,0],[3,0],[3,0.9],[2.5,0.9]]},{"p":[[3,0],[3.5,0],[3.5,0.9],[3,0.9]]},{"p":[[3.5,0],[4,0],[4,0.9],[3.5,0.9]]},{"p":[[4.9,0],[5.9,0],[5.9,0.9],[4.9,0.9]],"hi":true},{"p":[[5.9,0],[6.9,0],[6.9,0.9],[5.9,0.9]]}]},"variant_rule":{"alt":[{"stem":"길이가 12 cm인 띠는 똑같이 6칸, 8 cm인 띠는 똑같이 2칸으로 나누었어요. 긴 띠의 ⟨1/6⟩과 짧은 띠의 ⟨1/2⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"짧은 띠의 ⟨1/2⟩이 커요","correct":true},{"t":"긴 띠의 ⟨1/6⟩이 커요","mis":"M3-1-u6-X11"},{"t":"두 조각의 크기가 같아요","mis":"M3-1-u6-X11"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 12 ÷ 6 = 2 cm, 짧은 띠 한 칸은 8 ÷ 2 = 4 cm예요.","짧은 띠의 ⟨1/2⟩이 커요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,0.9],[0,0.9]],"hi":true},{"p":[[1,0],[2,0],[2,0.9],[1,0.9]]},{"p":[[2,0],[3,0],[3,0.9],[2,0.9]]},{"p":[[3,0],[4,0],[4,0.9],[3,0.9]]},{"p":[[4,0],[5,0],[5,0.9],[4,0.9]]},{"p":[[5,0],[6,0],[6,0.9],[5,0.9]]},{"p":[[6.9,0],[8.9,0],[8.9,0.9],[6.9,0.9]],"hi":true},{"p":[[8.9,0],[10.9,0],[10.9,0.9],[8.9,0.9]]}],"u":27}},{"stem":"길이가 12 cm인 띠는 똑같이 6칸, 6 cm인 띠는 똑같이 3칸으로 나누었어요. 긴 띠의 ⟨1/6⟩과 짧은 띠의 ⟨1/3⟩ 중 어느 조각이 더 큰가요?","options":[{"t":"두 조각의 크기가 같아요","correct":true},{"t":"긴 띠의 ⟨1/6⟩이 커요","mis":"M3-1-u6-X11"},{"t":"짧은 띠의 ⟨1/3⟩이 커요","mis":"M3-1-u6-X10"},{"t":"알 수 없어요","mis":"M3-1-u6-X20"}],"explanation":["분모만 보면 안 돼요 — 전체 띠의 길이가 달라요.","긴 띠 한 칸은 12 ÷ 6 = 2 cm, 짧은 띠 한 칸은 6 ÷ 3 = 2 cm예요.","두 조각의 크기가 같아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,0.9],[0,0.9]],"hi":true},{"p":[[1,0],[2,0],[2,0.9],[1,0.9]]},{"p":[[2,0],[3,0],[3,0.9],[2,0.9]]},{"p":[[3,0],[4,0],[4,0.9],[3,0.9]]},{"p":[[4,0],[5,0],[5,0.9],[4,0.9]]},{"p":[[5,0],[6,0],[6,0.9],[5,0.9]]},{"p":[[6.9,0],[7.9,0],[7.9,0.9],[6.9,0.9]],"hi":true},{"p":[[7.9,0],[8.9,0],[8.9,0.9],[7.9,0.9]]},{"p":[[8.9,0],[9.9,0],[9.9,0.9],[8.9,0.9]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#23','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C6',4,'sa','auto','⟨1/□⟩ > ⟨1/10⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-1-u6-C6","difficulty":4,"kind":"sa","stem":"⟨1/□⟩ > ⟨1/10⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 10보다 작고 1보다 큰 수 — 2, 3, 4, 5, 6, 7, 8, 9.","모두 8개예요."],"variant_rule":{"alt":[{"stem":"⟨1/□⟩ > ⟨1/6⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 6보다 작고 1보다 큰 수 — 2, 3, 4, 5.","모두 4개예요."],"asset":null},{"stem":"⟨1/□⟩ > ⟨1/7⟩ — □ 안에 들어갈 수 있는 1보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["단위분수는 분모가 작을수록 커요.","□는 7보다 작고 1보다 큰 수 — 2, 3, 4, 5, 6.","모두 5개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#24','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C9',4,'mc','auto','가장 큰 수는 어느 것인가요?',ARRAY['M3-1-u6-X16','M3-1-u6-X18']::text[],true,'{"seq":24,"concept":"M3-1-u6-C9","difficulty":4,"kind":"mc","stem":"가장 큰 수는 어느 것인가요?","options":[{"t":"⟨9/10⟩","correct":true},{"t":"0.4","mis":"M3-1-u6-X16"},{"t":"0.1이 2개인 수","mis":"M3-1-u6-X18"},{"t":"⟨1/10⟩이 7개인 수","mis":"M3-1-u6-X16"}],"explanation":["모두 0.1(=⟨1/10⟩)이 몇 개인지로 바꾸어요.","4개, 9개, 2개, 7개예요.","가장 많은 것은 ⟨9/10⟩예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 가장 큰 수는 어느 것인가요?","options":[{"t":"0.1이 9개인 수","correct":true},{"t":"0.1","mis":"M3-1-u6-X18"},{"t":"⟨3/10⟩","mis":"M3-1-u6-X16"},{"t":"⟨1/10⟩이 4개인 수","mis":"M3-1-u6-X16"}],"explanation":["모두 0.1(=⟨1/10⟩)이 몇 개인지로 바꾸어요.","1개, 3개, 9개, 4개예요.","가장 많은 것은 0.1이 9개인 수예요."],"asset":null},{"stem":"이번에는 다른 문제예요. 가장 큰 수는 어느 것인가요?","options":[{"t":"⟨1/10⟩이 7개인 수","correct":true},{"t":"0.2","mis":"M3-1-u6-X18"},{"t":"⟨6/10⟩","mis":"M3-1-u6-X16"},{"t":"0.1이 5개인 수","mis":"M3-1-u6-X16"}],"explanation":["모두 0.1(=⟨1/10⟩)이 몇 개인지로 바꾸어요.","2개, 6개, 5개, 7개예요.","가장 많은 것은 ⟨1/10⟩이 7개인 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u6_review_d#25','math',3,1,'u6','','g3_1_math_u6_review_d','unit_review','M3-1-u6-C10',4,'essay','teacher','같은 ⟨1/2⟩인데 큰 떡의 ⟨1/2⟩이 작은 떡의 ⟨1/2⟩보다 커요. 그 까닭을 쓰고, 분수의 크기를 견줄 때 무엇을 먼저 확인해야 하는지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u6-C10","difficulty":4,"kind":"essay","stem":"같은 ⟨1/2⟩인데 큰 떡의 ⟨1/2⟩이 작은 떡의 ⟨1/2⟩보다 커요. 그 까닭을 쓰고, 분수의 크기를 견줄 때 무엇을 먼저 확인해야 하는지 써 보세요.","answer_guide":{"answer":"예: 큰 떡과 작은 떡은 전체의 크기가 다르기 때문이다. 분수는 전체를 똑같이 나눈 것 중의 몇이라 전체가 크면 부분도 크다. 분수를 견줄 때는 전체의 크기가 같은지 먼저 확인해야 한다.","scoring_points":["전체의 크기가 다르다고 썼는가","전체가 크면 부분도 크다고 썼는가","전체의 크기가 같은지 먼저 확인해야 한다고 썼는가"]},"explanation":["두 떡의 크기가 달라요.","전체가 크면 부분도 커요.","전체의 크기부터 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
